// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":12,"question":"لقد تزوج والدي زوجةَ ولد أخيه بعد وفاته بسنوات، وأنجب منها ولدًا وطفلتين، وأريد أنا الزواج من ابنتها التي من زوجها السابق، فهل يجوز ذلك أم لا؟","title":"حكم الزواج بربيبة الأب أو أم زوجته","answer":"الجواب: نعم، ما فيه شيء، إذا تزوج أبوك زوجةَ ولد أخيه، أو تزوَّج زوجة أخيه بعد طلاقه لها، أو موته، أو زوجة عمّه أو خاله؛ فلا بأس، ولك أن تنكح بنت الزوجة من غير أبيك، سواء كانت هذه البنتُ من زوجٍ قبله أو زوجٍ بعده، فهي أجنبية منك، إنما هي ربيبةٌ لأبيك، لا ينكحها أبوك، وأما أنت فهي أجنبيةٌ، فإذا تزوج الإنسانُ امرأةً وتزوَّج ابنُه بنتَها أو أمَّها فلا بأس.","link":"https://binbaz.org.sa/fatwas/2791/حكم-الزواج-بربيبة-الاب-او-ام-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0264.mp3","categories":["شروط وأركان الزواج","أحكام المولود"]},{"id":109,"question":"يقول السائل: إذا عُقد قران على زوجةٍ، وكانت الزوجة والزوج مُقصرين في أداء الصلاة، أي: يُصليان أوقاتًا ويتركان أوقاتًا، فما صحَّة ذلك العقد؟ وهل الأطفال حلالٌ أم حرامٌ إن وُجِدُوا؟","title":"أثر عدم الصلاة على صحة العقد بين الزوجين","answer":"الجواب: إذا كان الزوجان يُصليان أو لا يُصليان فالعقد صحيح، والأولاد يُلحقون بهم؛ لشُبهة النكاح، إذا كانا يُصليان أو لا يُصليان جميعًا، فالنكاح صحيحٌ كسائر الكفرة، نكاحهم صحيحٌ على حسب ما اعتادوه في أنكحتهم.\nأما إذا كان واحدٌ يُصلي وواحدٌ ما يُصلي فلا يصح النكاح، ولا بدّ أن يُجدد إذا كانت هي تُصلي وهو ما يُصلي، أو هو يُصلي وهي ما تُصلي؛ لأنَّ ترك الصلاة كفرٌ مطلقًا على الأصح، وإن كانت ما جحدت وجوبها، وإن كان ما جحد وجوبها، يقول النبيُّ ﷺ: بين الرجل وبين الكفر والشِّرك: ترك الصلاة، ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر.\nفإذا كانت لا تُصلي وجب تجديد النكاح، أو كان هو لا يُصلي أو يُصلي تارةً ويترك تارةً أو هي كذلك وجب التَّجديد، فيُعاد النكاح بعد توبتهما، إذا تاب مَن ترك الصلاة، فإذا تاب تاركُ الصلاة إلى الله يُجدد النكاح بعقدٍ جديدٍ، وشهادة عدلين، ومهر جديد ولو قليلًا، ولو لم يذهبوا إلى المحكمة، ولو لم يذهبوا إلى المسؤول، ولكن هم بأنفسهم يفعلون ذلك، يعني: يحضر الولي والزوج وشاهدان عدلان، ويُجدد النكاح بشرط المهر الذي ترضى به المرأة ولو قليلًا، يقول: زوَّجْتُك، ويقول: قبلتُ على مهر كذا، بحضرة شاهدين، إذا كان أحدُهما حين العقد الأول لا يُصلي.\nأما إذا كانا يُصليان فهذا معروفٌ، أو كانا لا يُصليان جميعًا فعقدهما صحيحٌ؛ لأنَّهما اشتركا في الكفر: كالوثنين، واليهود، والنصارى، وأشباههم، فأنكحتهم صحيحة على ما اعتادوه في دينهم، وإنما المُصيبة إذا كان أحدُهما لا يُصلي، هذا هو محل تجديد النكاح -نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/3545/اثر-عدم-الصلاة-على-صحة-العقد-بين-الزوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0092.mp3","categories":["شروط وأركان الزواج","أحكام المولود"]},{"id":241,"question":"ما الموقف الشرعي من شخصٍ ربَّته جاريةُ والدته عندما كان عمره ست سنوات في الصِّغر، وحين كبر تزوَّجها زواجًا غير شرعيٍّ رغمًا عنها، فحملت منه، وأنجبت ولدًا، هل الولد يكون ابنًا له؟ وهل يحقّ لوالده أن يُنكره بعد وفاة الابن؟ وهل يحق لوالده أن يُنكر حقوق أبناء المُتوفى الذين يُعتبرون أحفادًا له؟ وهل يحقّ لهذا الوالد أن يُفرِّق في المُعاملة بين أبناء المُتوفى وبين أبناء أبنائه الآخرين؟ وما عاقبة ذلك على الرغم من أنني قد تعبتُ من المطالبة بالحقِّ ولكن الموقف كان يُقابل بلا مبالاة؟ أرجو إفادتي بما أوضحته لسماحتكم، جزاكم الله خيرًا.","title":"حكم الأولاد من زواج غير الشرعي، والتزوج ممن ربَّته","answer":"الجواب: المُربية لا تحرم على المُربَّى إذا كان ما بينهما رضاع ولا نسب: كالخادمة المملوكة، أو الخادمة غير المملوكة، ربَّته وأحسنت إليه؛ لأنها مُستأجرة أو متطوعة: كبنت عمِّه، أو بنت خاله، أو أجنبية ربَّت إنسانًا، ثم كبر وتزوَّجها؛ لا بأس، لكن كونه يتزوَّجها زواجًا غير شرعيٍّ بالزنا أو بغير وليٍّ شرعي؛ هذا لا يجوز، ما يُسمَّى: زواجًا هذا، هذا يُسمَّى: زنا، أو يُسمَّى: عقدًا فاسدًا، أو يُسمَّى: جرأة على الله، وتلاعبًا بالدين.\nفالحاصل أنَّ الذي اتَّخذ الخادمة التي ربَّته، ولم تُرضعه ولكن ربَّته، الذي تعدَّى عليها بالزنا أو بنكاحٍ غير شرعيٍّ؛ هذا لا يجوز، لكن يختلف: إن كان بنكاحٍ ظنَّه شرعيًّا فأولاده يُلحقون به، الأولاد يُنسبون إليه. أما إن كان زنًا فلا يُلحقون به، ولا يُنسبون إليه، بل يُنسبون إلى أمِّهم، ولا يجوز الاعتراف به بأنه ولدٌ له؛ لأنه من طريق الزنا. أما إن كان من طريق النِّكاح لكنه نكاح غير شرعيٍّ؛ بأن زوَّجها مَن ليس وليًّا لها، وظنُّوا أنه يصلح في ذلك -كما يوجد في بعض الدول- فهذا يكون نكاحًا غير شرعيٍّ، ويكون نكاحًا فاسدًا، والأولاد لاحقون به، لاحقون بأبيهم.","link":"https://binbaz.org.sa/fatwas/4121/حكم-الاولاد-من-زواج-غير-الشرعي-والتزوج-ممن-ربته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0281.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":513,"question":"بعض التربويين يقترحون ألا يتزوج الإنسان إلا بعد سن النضوج 21 أو 25 سنة، فما رأيكم؟","title":"ما الرد على من يرى تأخير سن الزواج؟","answer":"الجواب: هم مشرِّعون ولا عبيد؟! هم عبيد ولا مشرِّعون؟! الطلاب: عبيد. الشيخ: والعبد يعمل بشرع الله ولا يعمل برأيه؟! (......). (دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6343/ما-الرد-على-من-يرى-تاخير-سن-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/maram078 - 01 -  Start.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":528,"question":"النساء في الخارج لا يكون لهن ولي؟","title":"من يكون ولي الزواج للنساء في الخارج؟","answer":"الجواب: وليهن القضاء إن كان في دولة مسلمة، وإذا كان ما في دولة مسلمة فرئيس المركز الإسلامي يقوم مقام القاضي، أو رئيس الجمعية الإسلامية؛ حتى لا تتعطل.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6359/من-يكون-ولي-الزواج-للنساء-في-الخارج","audio":"https://files.zadapps.info/binbaz.org.sa/maram094 - 04 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":529,"question":"بالنسبة للصغيرة لو أُجبرت على الزواج؟","title":"ما حكم إجبار الصغيرة على الزواج؟","answer":"الجواب: إذا كانت بكرًا لا تُجبر، أما الصغيرة اللي دون التسع مثل ما تزوج النبي ﷺ عائشة زوَّجه إياها الصديق .\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6360/ما-حكم-اجبار-الصغيرة-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/maram095 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":530,"question":"هل للشهود سماع إذن الزوجة البكر؟","title":"هل للشهود سماع إذن الزوجة البكر؟","answer":"الجواب: نعم، إذنها السكوت، إذا استأذنها أبوها وسكتت يكفي؛ هو مُصَدَّق.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6361/هل-للشهود-سماع-اذن-الزوجة-البكر","audio":"https://files.zadapps.info/binbaz.org.sa/maram096 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":532,"question":"إذا لم تُستأذن البكر هل يبطل زواجها؟","title":"حكم زواج البكر بدون إذنها","answer":"الجواب: ج: نعم، ما يصح زواجها.","link":"https://binbaz.org.sa/fatwas/6363/حكم-زواج-البكر-بدون-اذنها","audio":"https://files.zadapps.info/binbaz.org.sa/maram098 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":533,"question":"البلاد الذين يحكمون بالمذهب الحنفي: إذا زوجوا بغير ولي ثم جاءت المرأة واستفت على مذهب آخر ماذا يكون؟","title":"ما حكم الزواج بغير ولي؟","answer":"الجواب: هذا محل نظر، قد يكون حكم لها حاكم، فهو محل نظر، فعلى جمهور أهل العلم لا بدّ من ولي، ومذهب الأحناف هذا مذهب ضعيف لا يُعَوَّل عليه.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6364/ما-حكم-الزواج-بغير-ولي","audio":"https://files.zadapps.info/binbaz.org.sa/maram099 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":535,"question":"اليتيمة هل تجبر؟","title":"حكم إجبار اليتيمة على الزواج","answer":"الجواب: لا،ـ يستأذنها أخوها أو عمها.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6366/حكم-اجبار-اليتيمة-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/maram101 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":536,"question":"اشتراط العدالة في الولي؟","title":"هل تُشترط العَدَالة في ولي النكاح؟","answer":"الجواب: هذا هو المشروع عند العلماء؛ لا بدّ من العدالة. والقول بأنه لا يشترط قول قوي؛ لأن الرسول ﷺ أطلق لا نكاح إلا بولي ولا يعرف أنه استفصل، فإذا كان ما هو كافر؛ فالأمر واسع إن شاء الله ولو كان فيه بعض المعاصي.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6367/هل-تشترط-العدالة-في-ولي-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/maram102 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":537,"question":"البكر التي عُقِد عليها ولم يُدْخَل بها يبقى عليها حكم البِكْر في الاستئذان؟","title":"هل تُستأذن المطلقة التي لم يُدخل بها للزواج؟","answer":"الجواب: ظاهر الحديث أنه يبقى؛ لأنه يقول: \"الثيب\" والثيب هي التي وُطئت، تزوجت ووُطئت. أما إذا ما وُطئت فهي ما زالت بِكرًا، لكن مقتضى العلة أنه لا بدّ من نطقها؛ لأنها زال عنها في الغالب الحياء بعد ما تزوجت، لكن مقتضى التعبير بالبِكر يقتضي أنه يكفي سكوتُها.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6368/هل-تستاذن-المطلقة-التي-لم-يدخل-بها-للزواج","audio":"https://files.zadapps.info/binbaz.org.sa/maram103 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":539,"question":"أيُّما امرأةٍ زوَّجها وليانِ فهي للأول منهما هل يُستفاد من هذا الحديث أن المرأة تُزَوَّج بدون علمها؟","title":"ما حكم تزويج المرأة بدون علمها؟","answer":"الجواب: لا، قد تكون أذنت لهما جميعًا، قد تقول لكل واحد: اللي تشوفه.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6370/ما-حكم-تزويج-المراة-بدون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/maram105 - 02 - .mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":694,"question":"ما قولكم في امرأة زُوِّجت قبل بلوغها، وبعد بلوغها رفضت قبول هذا الزواج. هل يجوز لها أن تتزوج بدون طلاق الزوج، أم لابد من الطلاق؟ وما هو الدليل في هذه المسألة إن كان معلومًا؟","title":"هل لمن زُوِّجت صغيرةً الطلاق بعد بلوغها؟","answer":"الجواب: إذا كانت المرأة قد زُوِّجت بإذنها، فعليها السمع والطاعة للزوج، وتنفيذ مقتضى النكاح، وليس لها أن تتزوج سوى زوجها الذي تم له العقد عليها قبل بلوغها، والمزوج لها أبوها؛ لقول النبي ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن، قالوا: يا رسول الله كيف إذنها، قال: أن تسكت[1] متفق على صحته، وهو يعم البالغة ومن دونها.\nوفي صحيح مسلم عن ابن عباس رضي الله عنهما أن النبي ﷺ قال: الأيم أحق بنفسها من وليها، والبكر تستأمر، وإذنها سكوتها[2] وخرجه أبو داود والنسائي بإسناد جيد بلفظ: ليس للولي مع الثيب أمر، واليتيمة تستأمر، وصمتها إقرارها[3]، وهذا صريح في صحة نكاح غير البالغة إذا أذنت، ولو بالسكوت.\nأما إذا كانت لم تستأذن والمزوج لها غير أبيها، فالنكاح فاسد في أصح قولي العلماء لكن ليس لها أن تتزوج إلا بعد تطليقه لها، أو فسخ نكاحها منه بواسطة الحاكم الشرعي؛ خروجًا من خلاف من قال: إن النكاح صحيح، ولها الخيار بعد البلوغ، وحسمًا لتعلقه بها، وليس لها أيضًا نكاح غيره حتى تستبرأ بحيضة إن كان قد وطئها.\nأما إذا كان المزوج لها بدون إذنها هو أبوها، فهذه المسألة فيها خلاف أيضًا بين العلماء، فكثير منهم يصحح هذا النكاح إذا كانت البنت بكرًا؛ لمفهوم قوله ﷺ: واليتيمة تستأمر، قالوا: فهذا يدل على أن غير اليتيمة لا تستأمر، بل يستقل أبوها بتزويجها بدون إذنها.\nوذهب جمع من أهل العلم: إلى أن الأب ليس له إجبار ابنته البكر، ولا تزويجها بدون إذنها، إذا كانت قد بلغت تسع سنين. كما أنه ليس له إجبار الثيب، ولا تزويجها بغير إذنها؛ للحديث السابق وهو قوله ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن[4]\nوهو يعم اليتيمة وغيرها، وهو أصح من الحديث الذي احتجوا به على عدم استئذان غير اليتيمة، وهو منطوق، وحديث اليتيمة مفهوم، والمنطوق مقدم على المفهوم؛ ولأنه عليه الصلاة والسلام صرح في رواية ثابتة عنه ﷺ بقوله: والبكر يستأذنها أبوها[5]، وهذا اللفظ لا يبقي شبهة في الموضوع؛ ولأن ذلك هو الموافق لسائر ما ورد في الباب من الأحاديث، وهو الموافق للقواعد الشرعية في الاحتياط للفروج، وعدم التساهل بشأنها.\nوهذا القول هو الصواب؛ لوضوح أدلته، وعلى هذا القول يجب على الزوج الذي عقد له والد البكر عليها بدون إذنها، أن يطلقها طلقة واحدة؛ خروجًا من خلاف العلماء، وحسمًا لتعلقه بها بسبب الخلاف المذكور.\nوهذه الطلقة تكون بائنة ليس فيها رجعة؛ لأن المقصود منها قطع تعلق المعقود له بها، والتفريق بينه وبينها، ولا يتم ذلك إلا باعتبارها طلقة مبينة لها بينونة صغرى؛ كالطلاق على عوض.\nويجب أن يكون ذلك بواسطة قاضٍ شرعي يحكم بينهما، ويريح كل واحد منهما من صاحبه على مقتضى الأدلة الشرعية؛ لأن حكم القاضي يرفع الخلاف في المسائل الخلافية، ويحسم النزاع. أما إذا كانت البنت دون التسع فقد حكى ابن المنذر: إجماع العلماء على أن لأبيها تزويجها بالكفء بغير إذنها؛ لأن الرسول ﷺ تزوج عائشة رضي الله عنه بدون إذنها وعلمها، وكانت دون التسع.\nونسأل الله أن يوفقنا وإياكم وسائر المسلمين للفقه في دينه والثبات عليه؛ إنه خير مسؤول، والسلام عليكم[6].","link":"https://binbaz.org.sa/fatwas/19445/هل-لمن-زوجت-صغيرة-الطلاق-بعد-بلوغها","audio":"undefined","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":711,"question":"رجلٌ عقد على امرأةٍ ولم يدخل بها، ثم زنا بأمِّها -والعياذ بالله- هل يجوز الدُّخول بالبنت؟ مع العلم أنه بعد ذلك دخل بالبنت وأنجب منها، فما حكم الزَّواج؟","title":"هل يجوز لرجلٍ الزواج ببنتٍ زنا بأمها؟","answer":"الجواب: الصحيح أنه يدخل بالبنت، وأن الزنا لا يُحرِّمها عليه؛ لأن الزنا محرَّم، ولا تجوز إشاعته، ولا يُحَرِّم الحلالَ، وهو عاصٍ في زناه، وعليه التوبة إلى الله، والرجوع إليه، والإنابة إليه، وزوجته تبقى معه، ولا تحرم عليه في أصح قولي العلماء ولو زنا بأمِّها -نسأل الله العافية- كما لو زنا ببنتها.\nالمقصود أنها لا تَحْرُم عليه، وتبقى زوجته في عصمته على الصحيح، وعليه التوبة إلى الله، ومتى عُلم ذلك يُقام عليه الحدّ الشرعي، وإذا كان بينه وبين الله فعليه التوبة، وألا يُفشي ذلك، وألا يُبينه لأحدٍ، وألا يقوله لأحدٍ، فليكن بينه وبين الله .\nوذهب بعضُ أهل العلم إلى أنها تحرم عليه البنت، وأن عليه فراقها؛ لأنه استحلَّ أمَّها، ولكنه قول مرجوح، والصواب أنها لا تحرم عليه، وأن نكاحه باقٍ، وعليه التوبة إلى الله، ويُقام عليه الحدُّ إذا عُرف ذلك وثبتت البينة، أما إن كان بينه وبين الله فعليه أن يستتر بستر الله، ولا يُبينه لأحدٍ، ويتوب إلى الله توبةً صادقةً، فمَن تاب تاب الله عليه.","link":"https://binbaz.org.sa/fatwas/20574/هل-يجوز-لرجل-الزواج-ببنت-زنا-بامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0528فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["شروط وأركان الزواج","الجنايات والحدود"]},{"id":747,"question":"إنَّ كثيرًا من الخُطَّاب أتوا إليَّ يخطبوا والدتي، وأنا أكره في نفسي أن أُزوّجها وأنا موجود، وأكره أن يدخل عليها رجلٌ غير أبي، فهل تصرُّفي هذا خطأ أم هو صواب؟","title":"هل يجوز منعُ الابن أمه من الزواج؟","answer":"الجواب: بل هو خطأ منك، إذا كانت ترغب الزواج هي فالواجب عليك تزويجها، ولا حرج في ذلك عليك، بل الواجب أن تسعى في برِّها، كما تسعى في برِّ والدك، وحقّ الأم أكبر وأعظم من حقِّ الأب، يقول النبيُّ ﷺ لما سُئل: قال له رجلٌ: يا رسول الله، مَن أحقُّ الناس بحُسن صُحبتي؟ قال: أمُّك، قال: ثم مَن؟ قال: أمك، قال: ثم مَن؟ قال: أمك، قال: ثم مَن؟ قال: أبوك، هو في الرابعة، فحق الوالدة أكبر.\nفإذا كانت ترغب في الزواج؛ فعليك أن تُجيبها إلى ذلك إذا خطبها الشخصُ المناسبُ، وليس لك أن تُعرقل الموضوع من أجل هواك، لا.","link":"https://binbaz.org.sa/fatwas/20648/هل-يجوز-منع-الابن-امه-من-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0570حكم منع الآم من الزواج ؟ ابن باز فتاوى المحاضرات.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":877,"question":"سمعتُ بأنَّ سماحتكم قد أجاز زواج المُتعة، فهل هذا صحيح؟","title":"حكم الزواج بنية الطلاق وتمييزه عن المتعة","answer":"الجواب: ليس بصحيحٍ، هذا باطلٌ، وإنما صدرت فتوى مني ومن اللجنة الدائمة بأنَّ الإنسان إذا تزوج وفي نيَّته الطلاق لا بأس عليه، وليس هذا من المتعة، هذا بينه وبين الله، إذا تزوج ونيّته أن يُطلِّق إذا فرغ من دراسته، أو من تجارته، أو من كونه سفيرًا، أو ما أشبه ذلك لا يضرُّه، هذا هو الصواب الذي عليه جمهور أهل العلم، حكاه الموفق في \"المغني\" عن جمهور أهل العلم، ولم يذكر خلافه إلا الأوزاعي.\nأما المتعة: فهي أن يتفق على مدةٍ معلومةٍ مع وليها أو معها: على شهرٍ، على شهرين، على سنةٍ، هذه المتعة، يتَّفقا على شيءٍ معلومٍ شرطًا بينهما.","link":"https://binbaz.org.sa/fatwas/20924/حكم-الزواج-بنية-الطلاق-وتمييزه-عن-المتعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0719ما حكم الزواج بنية الطلاق؟ ابن باز فتاوى المحاضرات.mp3","categories":["شروط وأركان الزواج","الأنكحة المحرمة"]},{"id":1594,"question":"الراجح في الكفاءة المُعتبرة في النكاح: في الدِّين فقط؟","title":"ما الكفاءة المُعتبرة في النكاح؟","answer":"الجواب: الدِّين والحرية.","link":"https://binbaz.org.sa/fatwas/21698/ما-الكفاءة-المعتبرة-في-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الكفاءة المُعتبرة في النكاح.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":2044,"question":"هل يجوز للابن أن يتزوج أخت زوجة أبيه؟","title":"حكم زواج الرجل بأخت زوجة أبيه","answer":"الجواب:\nزوجة أبيه ما هي بأمه.\nس: لا.\nالشيخ: ما في بأس، واحد يتزوج هذه وواحد يتزوج هذه، ما في بأس ما داموا أخوات ما يخالف.","link":"https://binbaz.org.sa/fatwas/22161/حكم-زواج-الرجل-باخت-زوجة-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للابن أن يتزوج أخت زوجة أبيه.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":2127,"question":"السفر بنية الزواج بالطلاق ما حكمه؟","title":"حكم السفر من أجل الزواج بنية الطلاق","answer":"الجواب:\nلا حرج عند الجمهور، لكن تركه أحوط وأفضل؛ خروجًا من خلاف مَن حرَّمه.","link":"https://binbaz.org.sa/fatwas/22245/حكم-السفر-من-اجل-الزواج-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السفر بنية الزواج بالطلاق.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":2608,"question":"اشتراط الكفاءة في النسب في النكاح عليه دليل؟","title":"حكم اشتراط الكفاءة في النسب في النكاح","answer":"الجواب: لا ما عليه، إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] المُعَوَّل عليه التقوى، فاظفر بذات الدين ترتبت يداك.\nس: بالنسبة لحكم زواج القبيلي من خضيري، وكذلك...؟\nالشيخ: ما في بأس، كله ما في بأس، هذه أعراف بين الناس، فاطمة بنت قيس تزوجت بأسامة بن زيد، وهو عتيق وهي من قريش، وعائشة بنت الحسين بن علي بن طالب تزوجت بمصعب بن الزبير، ومصعب ما هو من بطن بني هاشم وهو من عامة قريش.","link":"https://binbaz.org.sa/fatwas/22743/حكم-اشتراط-الكفاءة-في-النسب-في-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدليل على اشتراط الكفاءة في النسب في النكاح.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":2920,"question":"تزوجت ابنة عمي ووَلِيَ عقدَها أبوها، وخالها وأخوها هم الشهود، والبنت راضية وبأطيب حال ولله الحمد، ولكنهم ما شاوروها قبل العقد في الرضا؟","title":"هل يصح عقدُ مَن لم تصرِّح برضاها؟","answer":"الجواب: لا، إن أدخلت عليك وهي راضية فهي راضية.\nس: نعم؟\nالشيخ: لما أدخلت عليك وسكتت فمعناه راضية.\nس: معناه العقد صحيح؟\nالشيخ: ما فيه شيء أبدًا، خل عنك وساوس الشيطان.","link":"https://binbaz.org.sa/fatwas/23076/هل-يصح-عقد-من-لم-تصرح-برضاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة عقد من لم تصرح برضاها.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3052,"question":"الكفاءة بين الزوجين من حيث النَّسَب هل تُشترط؟","title":"هل تُشترط الكفاءة بين الزوجين في النَّسَب؟","answer":"الجواب: ما هو بشرط، لا، في الدين إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] في الدين، لا يتزوج المسلم الكافرة؛ لأن الله يقول: وَلَا تَنْكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221]، وَلَا تُنْكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا [البقرة:221]،  لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] وكذلك الحرية والعبودية فيها تفصيل.\nس: الذي يقول: خضيري؟\nالشيخ: هذا شيء جديد بين العامة، وإلا الأصل عرب وعجم، هذا الأصل، وبعضهم لبعض أكفاء إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13].\nس: بعضهم يستدل بقول عمر: لأمنعن ذوات الأنساب؟\nالشيخ: إن صح فهذا محل اجتهاده .","link":"https://binbaz.org.sa/fatwas/23212/هل-تشترط-الكفاءة-بين-الزوجين-في-النسب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تشترط الكفاءة بين الزوجين من حيث النسب.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3483,"question":"بعض العامة يتشددون في نهي تشبيك الأصابع في أثناء عقد النكاح؟","title":"حكم تشبيك الأصابع في أثناء عقد النكاح","answer":"الجواب: لا ما له أصل هذا، هذا سوء ظن.","link":"https://binbaz.org.sa/fatwas/23660/حكم-تشبيك-الاصابع-في-اثناء-عقد-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تشبيك الأصابع في أثناء عقد النكاح.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3644,"question":"إذا تزوج المرأة بدون ولي هل يبطل النكاح؟","title":"هل يبطل زواج المرأة بدون ولي؟","answer":"الجواب: إذا كان يوجد ولي فنعم، ولم يستأذن ولم يوكل؛ يبطل النكاح لا نكاح إلا بولي.","link":"https://binbaz.org.sa/fatwas/23832/هل-يبطل-زواج-المراة-بدون-ولي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم زواج المرأة بدون ولي.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3645,"question":"إذا كان وليها كافرًا أسلمت ...؟","title":"حكم تزويج مَنْ كان وليها كافرًا","answer":"الجواب: الكافر ما له ولاية، ولكن إن كان ولا بدّ وهي ما لها ولي، كونه يتولاه حتى لا تقع فتنة؛ أنسب، يتولاه وهي تزوّج نفسها في الحقيقة، لكن كونها تشاوره حتى لا يقع فتنة بينه وبين الزوج وحتى لا يقع شر بينهم للضرورة، وإلا ليس وليًّا شرعيًّا.","link":"https://binbaz.org.sa/fatwas/23833/حكم-تزويج-من-كان-وليها-كافرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم في من كان وليها كافرًا.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3646,"question":"لو ولي الزوجة عاصٍ؟","title":"هل تزوّج نفسها مَنْ كان وليها عاصيًا؟","answer":"الجواب: ولو، الصواب يزوّجها ولو كان غير عدل، لا تزوج نفسها، لكن إذا وجد الولي العدل فهو أوْلى من غيره، والصواب أنها لا تُشترط العدالة في الولي؛ لأن الغيرة موجودة، يزوجها وليها؛ أبوها أو الأقرب فالأقرب، وإن كان فيه نقص في العدالة، ولا تزوّج نفسها.\nس: وإن كانت بدعته شركية؟\nالشيخ: لا، الكافر ما له ولاية.","link":"https://binbaz.org.sa/fatwas/23834/هل-تزوج-نفسها-من-كان-وليها-عاصيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم في من كان وليها عاصٍ أو مبتدع.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3647,"question":"رضا المرأة شرط لصحة العقد؟","title":"هل رضا المرأة شرط لصحة الزواج؟","answer":"الجواب: لا بدّ منه، نعم، إذا كنت بنت تسع فأكثر، أما دون التسع فلأبيها أن يزوجها، إذا كانت دون التسع كما زوج أبو بكر عائشة على النبي ﷺ وهي دون التسع ولم يستأذنها؛ لأنها لا رأي لها ما دام دون التسع، لأبيها خاصة أن يزوّجها دون التسع. أما غير الأب فلا يزوّج إلا بإذن، بعدما تكون بنت تسع فأكثر، وإذن الصغيرة سكوتها، البكر إذنُها سكوتُها.","link":"https://binbaz.org.sa/fatwas/23835/هل-رضا-المراة-شرط-لصحة-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل رضا المرأة شرط لصحة العقد.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3648,"question":"سمعنا في بعض كتب الفقه أن الأب يُرْغِم - إن رأى فيه مصلحة-  ابنه أو بنته على الزواج؟","title":"هل للولي إرغام ابنه أو ابنته على الزواج؟","answer":"الجواب: ليس بصواب، لا يُجْبَر الولد ولا البنت عليه. أما إذا كان صغيرًا دون التسع؛ له أن يزوجه وله أن يزوجها إن كانت صغيرة وهو صغير دون التسع، الأب خاصة.","link":"https://binbaz.org.sa/fatwas/23836/هل-للولي-ارغام-ابنه-او-ابنته-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُرغم الولي ابنه أو ابنته على الزواج.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3649,"question":"إذا كان الولي يرى أن في هذا الزواج مفسدة شرعية هل له أن يمنعها من هذا الزوج؟","title":"هل للولي منع زواج المرأة لمفسدة شرعية؟","answer":"الجواب: يجتهد في هذا ولا يزوّجها إلا على وجه فيه خير لها ومصلحة لها، وإذا تنازعوا يرجعوا إلى المحكمة، لكن هو عليه أن يجتهد؛ لا يزوّجها إلا بالرجل الصالح الذي يراه أهلًا لها.","link":"https://binbaz.org.sa/fatwas/23837/هل-للولي-منع-زواج-المراة-لمفسدة-شرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمنع الولي المرأة من الزواج إذا كان يرى أن في هذا الزواج مفسدة شرعية.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3650,"question":"إذا كان الولي هو الخاطب يتولى طرفي العقد؟","title":"كيف يتم الزواج إذا كان الولي هو الخاطب؟","answer":"الجواب: نعم، وفيه النهي عن ظلم اليتامى، وأنه لا يجوز ظلم اليتيمات، بل يجب على وليهن تزويجهن، بعض الناس قد يظلمها لأجل مالها، لعلها تموت فيرثها فيتأخر عن تزويجها، وهذا من الظلم، بل يجب أن يزوجها متى خطبها الكفء، وليس له أن يحبسها، فإن رغب فيها ورغبت فيه فلا بأس أن يتزوجها ويتولى طرفي العقد.","link":"https://binbaz.org.sa/fatwas/23838/كيف-يتم-الزواج-اذا-كان-الولي-هو-الخاطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا كان الولي هو الخاطب يتولى طرفي العقد.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3651,"question":"إذا لم يكن لها ولي أصلًا ولا حاكم؟","title":"حكم زواج من ليس لها ولي ولا حاكم؟","answer":"الجواب: تزوّج نفسها، وإن تيسر يزوجها مثل رئيس المركز الإسلامي أو شبهه أنسب؛ لأنه يقوم مقام السلطان، مثل ما قد يقع في أمريكا وأشباهها، رؤساء المراكز الإسلامية مناسب إذا قالت له والتمس لها الكفء، فإذا لم يتيسر تزوّج نفسها للضرورة بحضرة شاهدين..... زوجتك نفسي أو قد تزوجتك بكذا، بحضرة شاهدين وبمهر، تزوج نفسها، يتولى طرفا العقد: زوجتك نفسي، وقبلتُ.\nس: لو وجد مسلم ولو لم يكن سلطانًا هل لها أن توكله؟\nالشيخ: لا يجب عليها؛ لأنه ليس وليًا لها، لكن إن وكلته فلا بأس.","link":"https://binbaz.org.sa/fatwas/23839/حكم-زواج-من-ليس-لها-ولي-ولا-حاكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زواج من لم يكن لها ولي أصلا ولا حاكم.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3654,"question":"إذا أخبرها (الثيب) وسكتت؟","title":"هل يصح سكوت غير البكر للإذن بالنكاح؟","answer":"الجواب: لا يكفي لا بدّ من إذنها الصريح إلا البكر، البكر تستحي فيكفي سكوتها، أما الثيب فلا بدّ من أمرها.\nس: إذا رضيت بعد العقد هل يجدد؟\nالشيخ: يجدد نعم.\nس: إذا دخل بها وهي كارهة..؟\nالشيخ: يُفسخ النكاح، وإذا رضيت بعدين يجدد، إذا رضيت بعد ذلك.\nس: ويكون صداق آخر أو يُكتفى بالصداق الأول؟\nالشيخ: الصداق الأول بما استحل من فرجها، لكن لا بدّ من صداق ثانٍ ولو قليل.\nس: ما جاء في بعض الألفاظ \"قد أجزت ما فعل أبي\"؟\nالشيخ: جاء في بعض الروايات: خيّرها النبيﷺ، لكن الأصح الرد؛ لأن النكاح وقع باطلًا.","link":"https://binbaz.org.sa/fatwas/23842/هل-يصح-سكوت-غير-البكر-للاذن-بالنكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإذن في النكاح لا بد أن يكون صريحا إلا البكر.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":3655,"question":"الإيجاب والقبول يكون في مجلس واحد أو يتراخى؟","title":"هل يجوز تأخر قبول الزواج عن الإيجاب؟","answer":"الجواب: في مجلس واحد.\nس: لو تراخى صح؟\nالشيخ: قريب في مجلس واحد، قريب شيء يسير، مثل ما جرى مع صاحب الخاتم تراخى قليلًا.","link":"https://binbaz.org.sa/fatwas/23843/هل-يجوز-تاخر-قبول-الزواج-عن-الايجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإيجاب والقبول في النكاح على الفور أو على التراخي.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":5045,"question":"عقد النكاح بعد التَّحلل الأول؟","title":"ما حكم عقد النكاح للحاج بعد التَّحلل الأول؟","answer":"الجواب: ما فيه بأس، الصحيح أنه ما يبقى إلا الوطء.","link":"https://binbaz.org.sa/fatwas/29282/ما-حكم-عقد-النكاح-للحاج-بعد-التحلل-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم عقد النكاح للحاج بعد التحلل الأول؟.mp3","categories":["محظورات الإحرام","شروط وأركان الزواج"]},{"id":5072,"question":"رجلٌ تزوَّج من امرأةٍ فعل بها الفاحشة قبل الزواج، ولم يكن ذلك برغبته، بل مُرغمًا؛ وذلك لدخول الشيطان بينهما، وخوفًا من الفضيحة والعار تزوج منها، وأنجبت منه أطفالًا، ولكن الإثم حاك في نفسه، وكره أن يطَّلع عليه الناس فعلًا، وشكوكه دائمًا بها هو ما يجعله فعلًا يرى الماضي دائمًا بين عينيه، ويجعله يشك فيها، وكأنما أعطته قبل الزواج ستُعطيه لغيره بعد زواجه منها، فطلَّقها، وأحسَّ بالراحة النَّفسية فعلًا بعد ذلك، فهل عليه إثمٌ في ذلك؟ وما حال أبنائه في مثل هذه الحالة؟ وهل في ذلك شيءٌ من الناحية الدينية؟ وهل لها الحقُّ في تربية أبنائه أو ردّهم؛ نظرًا لكونها هي التي حاولت إغراءه في بداية الأمر قبل الزواج، واستدرجته لفعل الفاحشة، وربما لا تكون تربيتها إسلاميةً؟  علمًا بأن زواجه منها في بادئ الأمر -وهو ما ذُكِرَ بعاليه- خوفًا من عقاب الله ، علمًا بأنها ثيب عندما تزوَّجها. جزاكم الله خير الجزاء.","title":"حكم من تزوج مَن زَنا بها للسّتر ثم شك بحالها فطلقها","answer":"الجواب: إذا كان الزواجُ بها عن توبةٍ فلا بأس بذلك، إذا كانت أظهرت التوبة والندم، وهو كذلك؛ فلا بأس أن يتزوجها للستر والتَّغطية على ما وقع، ومَن ستر مسلمًا ستره الله في الدنيا والآخرة.\nوأما إن كان تزوجها من أجل مجرد الستر فقط، أو لأجل تشديد أبيه أو أمه أو غير ذلك، وهي على حالها ما أظهرت توبةً؛ فلا يجوز هذا النكاح، ولا يصحّ، وعليه التوبة من ذلك، عليك التوبة من ذلك، وقد أحسنت في طلاقها إذا كان ظاهرها عدم الاستقامة، وأولادك لاحقون بك لأجل شُبهة النكاح، أولادك لاحقون بك من أجل شبهة النكاح، وإن كان نكاحًا فاسدًا، إذا كانت ما تابت من فعلها القبيح، وقد أحسنتَ كما تقدم في الطلاق إذا كانت حالها سيئةً.\nأما إن كانت قد تابت وأظهرت النَّدم وأنت كذلك، وفعلتما ذلك تستُّرًا وإبعادًا للشر؛ فأنتم على خيرٍ إن شاء الله، ولا حرج عليكم. \nلكن ما دامت لم تظهر منها التوبة، وتخشى منها أن تفعل مع غيرك ما فعلتْ معك ولهذا طلَّقتها؛ فقد أحسنتَ في ذلك، والأولاد أولادك، وأما كونهم يبقون عندها أو يُنقلون إليك فهذا عند المحاكم، ما هو عندنا، لكن إذا اصطلحتم فيما بينكم -مع أبيها ومع أقاربها- على أنهم يكونون عندك خوفًا على أولادك؛ هذا لا بأس به، وإن كانت قد استقامت وحسنت حالها فلا بأس ببقاء الأولاد عندها، إذا كانت قد حسنت حالها، ولكن أنت بسبب الشك وبسبب الوسواس طلَّقتها، فلا بأس ببقاء الأولاد عندها؛ لكونها تحسنت حالها.\nأما إن كنت تُسيء الظنَّ بها، ولا ترى أنَّ حالها تحسنت؛ فتعمل ما تستطيع من الطرق الشرعية مع المحكمة في نقل أولادك إليك، أو بواسطة الأخيار، يُصلحون بينكم؛ حتى تسمح هي وأهلها بإعطائك أولادك، فإن لم يتيسر ذلك فالمحكمة، من دون أن تُبين أمر الزنا، ولكن تطلب أولادك وتقول: إنك تخشى عليهم.","link":"https://binbaz.org.sa/fatwas/29384/حكم-من-تزوج-من-زنا-بها-للستر-ثم-شك-بحالها-فطلقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من تزوج من زنا بها للسّتر ثم شك بحالها.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":5098,"question":"يقول هذا السائل بعد السلام على فضيلتكم:رجل مسافر إلى الخارج في مهمة تتعلق بالدراسة، وكان ملزمًا بذلك، وهو لم يتزوج بعد، ويخشى على نفسه، فهل له الزواج من هناك، مضمرًا في نفسه أنه سيطلقها عندما يسافر إلى بلده، دون أن يعلمهم بذلك؟","title":"حكم الزواج بنية أنه سيطلقها عندما يسافر","answer":"الجواب: لا حرج في ذلك إذا تزوج في محل السفر وفي نيته أنه يطلق إذا أراد الرجوع، لا حرج عند جمهور أهل العلم. بعض أهل العلم قد توقف في هذا، وخشي أن يكون من باب نكاح المتعة، وليس كذلك، المتعة يشترط فيها مدة معلومة، يتزوج على أنه يطلقها بعد شهر أو شهرين، على أنه لا نكاح بينهما بعد شهر أو شهرين أو ثلاثة، هذا نكاح المتعة. أما الزواج المطلق ليس فيه شرط، ولكن في نفسه ونيته أنه يطلقها عند سفره من البلاد، هذا لا يكون متعة، فقد يطلقها وقد يرغب فيها، فليس هذا من باب المتعة على الصحيح، وعلى ذلك جمهور أهل العلم. والله أعلم، وصلَّى الله وسلَّم على نبينا محمد، وعلى آله وصحبه أجمعين.","link":"https://binbaz.org.sa/fatwas/30006/حكم-الزواج-بنية-انه-سيطلقها-عندما-يسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 23.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":5242,"question":"بعض المسلمين يُسافرون للدراسة وغيرها إلى الخارج، فهل يجوز أن يتزوج بنية الطلاق؟ وما الفرق بينه وبين زواج المُتعة؟ أرجو توضيح الأمر في هذا وفَّقكم الله.","title":"هل يجوز أن يتزوج بنية الطلاق؟","answer":"الجواب: السفر إلى الخارج فيه خطرٌ عظيمٌ، وفيه بلاءٌ كثيرٌ، فلا يجوز السفر إلى الخارج إلا بشروطٍ مهمةٍ؛ لأنَّ السفر إلى الخارج يُعرِّضه للكفر بالله، ويُعرضه للمعاصي: لشرب الخمور، لتعاطي الزنا، وغير هذا من الشُّرور، ولهذا نصَّ العلماء على تحريم السفر إلى بلاد الكفار؛ عملًا بقول النبي ﷺ: أنا برئٌ من كل مسلمٍ يُقيم بين المشركين، فالإقامة بينهم خطيرةٌ جدًّا، لا للدراسة، ولا لغيرها. فهؤلاء المسافرون من طلبة الثانوي أو المتوسط أو في العالي -الدراسة الجامعية- على خطرٍ عظيمٍ، والواجب على الدولة أن تُؤَمِّن لهم الدراسة في الداخل، وليس لها أن تسمح لهم بالسفر إلى الخارج؛ لما فيه من الخطر العظيم. وقد نشأ عن هذا شرٌّ كثيرٌ: من الردة، والتساهل بالمعاصي، والزنا، والفواحش، وشرب الخمور، كما هو معلومٌ عند مَن سبر أحوالهم. فالواجب منعهم من ذلك، وألا يُسافر إلا الرجال المعروفون بالدِّين والإيمان والعلم والفضل، إذا كان للدعوة إلى الله، أو للتَّخصص في أمورٍ تحتاجها الدولة الإسلامية، والمسافر معروفٌ بالعلم والفضل والإيمان والاستقامة، حتى يدعو إلى الله وينفع الناس هناك، ويتعلم ما تحتاجه منه الدولة، أما هؤلاء الشُّبان الذين يُسافرون فهذا غلطٌ عظيمٌ، ومنكرٌ عظيمٌ، وشرٌّ عظيمٌ، نسأل الله أن يُوفِّق الدولة لمنع ذلك والقضاء عليه. أما الزواج بنية الطلاق: فهذا فيه خلافٌ بين العلماء: منهم مَن كره ذلك، كالأوزاعي رحمه الله وجماعة، وقالوا: إنه يُشبه المتعة، فليس له أن يتزوج بنية الطلاق. وذهب الجمهور -وهم الأكثرون كما قال الموفق ابن قُدامة في \"المغني\"- إلى أنه يجوز إذا كان بينه وبين ربِّه سرًّا، ليس بشرطٍ، كأن يُسافر إلى بلدٍ للدراسة أو لأعمالٍ هناك، ويخشى على نفسه، فيتزوج وبنيته أنه إذا سافر -إذا رجع إلى بلاده- طلَّقها؛ فلا بأس بذلك إذا كان بينه وبين ربِّه، من دون مُشارطةٍ ولا علمٍ ولا اطِّلاعٍ من الولي ولا الزوجة ولا غير ذلك، بل بينه وبين الله، فجمهور أهل العلم يقولون: لا بأس بذلك، وليس من المتعة في شيءٍ؛ لأنه بينه وبين الله، ليس فيه مشارطةٌ. أما المتعة: فهي التي تكون فيها المشارطة على شهرٍ أو شهرين، أو سنة أو سنتين، بينه وبين أهل الزوجة، أو بينه وبين الزوجة، هذه يُقال لها: المتعة، وهي محرَّمة بالإجماع، ولم يتساهل فيها إلا الرافضة، هي محرَّمة بالإجماع. وكان ابن عباسٍ قد توقف فيها، ثم رجع، كان يقول: إنها مثل الميتة للضَّرورة، ولكنه رجع عن ذلك. أما أن يتزوج في بلادٍ سافر إليها للدراسة، أو لكونه سفيرًا، أو لأسبابٍ أخرى، لمسوِّغ شرعيٍّ: سافر واحتاج إلى الزواج خوفًا على نفسه؛ فلا بأس أن يتزوج بنية الطلاق إذا أراد أن يرجع، وترك هذه النية أوْلى، فكونه يتزوج بنية الرغبة أو المصلحة أوْلى وأفضل؛ خروجًا من الخلاف، ولكن لو نواه فيما بينه وبين الله، وليس بشرطٍ بينه وبين أهل الزوجة، ولا بين الزوجة وبينه، فهذا ليس بمتعةٍ؛ لأنه نيَّة بينه وبين الله، والإنسان له أن يُطَلِّق متى شاء، ما هو ممنوع من الطلاق، ولو ما نوى.","link":"https://binbaz.org.sa/fatwas/30653/هل-يجوز-ان-يتزوج-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 516.mp3","categories":["الأنكحة المحرمة","شروط وأركان الزواج"]},{"id":5346,"question":"ما قولكم فيمَن لا يُزوج ابنته لحجَّامٍ أو جزَّارٍ أو حدَّادٍ، حتى ولو كان رجلًا مُتدينًا ذا خلقٍ، فهل هذا العمل صحيح بالنسبة لعيب الزواج من جزارٍ أو حجَّامٍ؟","title":"حكم مَن لا يُزوج ابنته لحجَّامٍ أو جزَّارٍ أو حدَّادٍ","answer":"الجواب: يقول الله جلَّ وعلا: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13]، فإذا وجد الأتقى زوَّج، سواء كان من العرب أو من العجم، أو من بني هاشم أو غيرهم، قال النبي للأنصار: يا بني بياضة، أنكحوا إلى أبي هندٍ، وأنكحوا إليه، وكان حجَّامًا. فالمقصود أن العبرة بالأعمال الصالحة والتقوى، كونه حجامًا أو حدادًا أو خرَّازًا أو نجارًا أو غير ذلك لا يضرّه، كان داود عليه الصلاة والسلام حدادًا يصنع الدروع ويبيعها وهو نبي الله. فالواجب على المؤمن أن يتحرى لموليته صاحب التقوى، وإذا تيسر من نسبٍ طيبٍ فهذا خيرٌ إلى خيرٍ كما قال ﷺ: تُنكح المرأةُ لأربعٍ: لمالها ولحسبها ولجمالها ولدينها، فاظفر بذات الدين تربت يداك، ويقول النبي ﷺ: إذا خطب إليكم مَن ترضون دينَه وخُلقه فزوِّجوه، ما قال: نسبه، مَن ترضون دينَه وخُلقه فزوِّجوه، إلا تفعلوا تكن فتنة في الأرض وفساد كبير. وقد زوَّج النبي ﷺ فاطمة بنت قيسٍ أسامة بن زيد عتيقه ابنَ عتيقه، وهي من قريش، وزوَّج أبو حذيفة بن عتبة سالمًا مولى أبي حذيفة بنته. المقصود أنَّ المؤمن يتحرّى العمل الطيب والتقوى والخير، ولا يهمه كونه من بني فلانٍ، أو كونه يعمل كذا، أو يعمل كذا، متى كان كفئًا في دينه: إذا خطب إليكم مَن ترضون دينه وخُلقه فزوِّجوه، إلا تفعلوا تكن فتنة في الأرض وفساد كبير، زوَّجه بنت أخيه، زوَّجه أبو حذيفة ابنةَ أخيه، نعم، مولى سالم.[1]","link":"https://binbaz.org.sa/fatwas/31025/حكم-من-لا-يزوج-ابنته-لحجام-او-جزار-او-حداد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 067.mp3","categories":["الشروط والعيوب في النكاح","شروط وأركان الزواج"]},{"id":5700,"question":"سؤال آخر: لي أخت أكبر مني رضعت مع عمي، فهل بنات عمي يحللن له ولي، ولإخوتي؟","title":"الزواج من أخت أخته من الرضاعة","answer":"الجواب: ما دامت المرأة التي رضعَتْ أختك فرضاعها ما يضركم، أنت لك أن تنكح بنات عمك، فكون أختك رضعت من زوجة عمك، ما يمنع إذا كنت أنت ما رضعت من زوجة عمك، وبنات عمك ما رضعوا من أمك، ولا من زوجة أبيك، ولا من أخواتك لا يضر.  لكن هذا ينبغي يسأل بنفسه؛ لأن بعض الناس يكتب سؤالا، ولا يعرفه، وين السائل؟ يسأل عن نفسه.","link":"https://binbaz.org.sa/fatwas/986/الزواج-من-اخت-اخته-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_15.mp3","categories":["شروط وأركان الزواج","الرضاع"]},{"id":5911,"question":"لدي ثلاث زوجات -والحمد لله- ولواحدة منهن ابنة خالة لها، أرغب زواجها رابعة، فهل علي بأس في ذلك، بالرغم من رضا هذه، وتلك؟","title":"حكم الجمع بين المرأة وابنة خالتها","answer":"الجواب: لا بأس في أن تجمع بين زوجاتك، بنت خالتهن، أو بنت عمتهن لا بأس، الجمع بين بنتي العم، أو بنتي الخال، أو بنتي الخالة، أو بنتي العمة لا حرج. إنما الممنوع أن تجمع بين الأختين، هذا الممنوع، كما قال الله سبحانه: وَأَنْ تَجْمَعُوا بَيْنَ الْأُخْتَيْنِ [النساء:23] فهو محرم. وهكذا الجمع بين المرأة، وعمتها، أو بين المرأة، وبنت أخيها، أو بين المرأة، وخالتها، أو بنت أختها، هذا ممنوع، لا يجوز الجمع؛ لأن الرسول نهى عن هذا، نهى أن يجمع بين المرأة، وعمتها، وبين المرأة، وخالتها، لا تنكح الصغرى على الكبرى، ولا الكبرى على الصغرى.  فالحاصل: أنك لا تجمع بين امرأتين، إحداهما عمة الأخرى، أو خالة الأخرى، ولو كانت عمة بعيدة رفيعة، أو خالة، ما هو لازم، تكون عمة قريبة، ولو عمة رفيعة، فلا يجمع بين المرأة وبين عمة أبيها، أو عمة أمها، أو عمة جدها، أو عمة جدتها، وكذلك بين المرأة وخالتها، أو خالة أمها، أو خالة أبيها، أو خالة جدتها؛ فإن خالة أبيها خالة لها، خالة المرأة، وخالة أبيها، وخالة أمها خالة لها، والنبي ﷺ نهى أن يجمع بين المرأة، وعمتها، وبين المرأة، وخالتها كما نهى الله في كتابه العظيم عن الجمع بين الأختين. أما الجمع بين ابنتي العم، وابنتي الخال، وابنتي الخالة، وابنتي العمة؛ فلا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/1253/حكم-الجمع-بين-المراة-وابنة-خالتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_249.mp3","categories":["قضايا المرأة","شروط وأركان الزواج"]},{"id":5920,"question":"سمعنا من المحاضرة أن المرأة لها حق الزواج بعد أربع سنين من فقدان زوجها،  لو رجع زوجها الأصلي فما الحكم؟ هل تبقى مع الثاني، أم ترجع للأول، وإذا رجعت للأول كيف ذلك؟","title":"حكم من تزوجت بعد فقد زوجها ثم عاد بعد ذلك","answer":"الجواب: إذا فقد الإنسان بين أهله، ولا تعرف أين هو، فهذا الغالب عليه الهلاك، إذا فقد بين الناس في مدنهم، وقراهم، ولا يدرى أين ذهب؛ إذا مضى أربع سنين، كما حكم عمر، يفرق بينهما، وتؤمر بالعدة، وتزوج، فإذا جاء زوجها الأول يرجع للمحكمة، والمحكمة تنظر في مثل هذا، المحكمة الشرعية تنظر في أمرهما. السؤال: والعدة تكون أربعة أشهر وعشرًا؟ الجواب: أربعة أشهر، وعشرًا، كأنه ميت.","link":"https://binbaz.org.sa/fatwas/1284/حكم-من-تزوجت-بعد-فقد-زوجها-ثم-عاد-بعد-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_271.mp3","categories":["قضايا المرأة","شروط وأركان الزواج"]},{"id":5924,"question":"يقولون: إن العرق دساس من الزوجة، فهل هذا العرق من الأم، أو إلى الخال؟","title":"مراعاة اختيار النسب عند الزواج","answer":"الجواب: لا شك أن العروق لها أصل، ولكن الحديث هذا ضعيف، ولكن العروق لها أساس، ثبت في الصحيحين أن رجلًا جاء إلى النبي ﷺ يشكو أن امرأته ولدت غلامًا أسود يخالف لونها، ولونه، فاتهمها، وعرض بأن ينفيه، فقال له النبيﷺ: هل لك من إبل؟ قال: نعم، قال: فما ألوانها؟ قال: حمر، قال: فهل فيها من أورق؟ يعني أسود، قال: نعم، قال: فأنى أتاها ذلك؟ قال: لعله نزعه عرق! فقال: لعل ابنك هذا نزعه عرق.  فالعرق له أصل، وهكذا جاء في بعض الأحاديث .. النطفة أن الله يصورها تارة كذا، وتارة كذا، تارة يكون الشبه بالزوج، أو يكون الزوج بالوالدة، وقد يكون الشبه ببعض الأقارب. فالحاصل: أن هذا له أساس وله أصل؛ فينبغي اختيار العروق الطيبة، والناس الطيبة أهل الدين، والخير، والاستقامة، والأخلاق الفاضلة.","link":"https://binbaz.org.sa/fatwas/1269/مراعاة-اختيار-النسب-عند-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_256.mp3","categories":["قضايا المرأة","شروط وأركان الزواج"]},{"id":5930,"question":"هل يجوز لرجل أن ينكح زوجته بعد العقد، وقبل أن يعطيها الصداق؟","title":"حكم الدخول على المرأة بعد العقد وقبل إعطائها الصداق","answer":"الجواب: إذا تم العقد فلا بأس، ولو أجل الصداق، إذا تم العقد بينهما؛ حلت له، ولو أجل الصداق إلى سنوات، المهم العقد، إذا تم العقد بشروطه المعتبرة، وصار عقدًا صحيحًا؛ فإنها تحل له، ولو تأجل الصداق.","link":"https://binbaz.org.sa/fatwas/1271/حكم-الدخول-على-المراة-بعد-العقد-وقبل-اعطاىها-الصداق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_258.mp3","categories":["قضايا المرأة","شروط وأركان الزواج"]},{"id":5964,"question":"هل يصح للرجل أن يتزوج امرأة، وابنه يتزوج بنتها، أو العكس؟","title":"هل يصح زواج الرجل بابنة زوجة أبيه؟","answer":"الجواب: لا بأس أن يتزوج الإنسان امرأة، وولده يتزوج بنتها، لا حرج في ذلك، أو يتزوج إنسان بنتًا، وولده يأخذ أمها؛ لأنها أجنبية منه، ليست حرامًا عليه، أو أختها، أو خالتها.","link":"https://binbaz.org.sa/fatwas/1337/هل-يصح-زواج-الرجل-بابنة-زوجة-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_304.mp3","categories":["شروط وأركان الزواج"]},{"id":6058,"question":"سمعنا عن أبي حنيفة أنه يقول: إن الرجل إذا صادق المرأة، وقال: هذه زوجتي عن طريق الصداقة؛ جاز له الزواج؟","title":"حكم الزواج بدون ولي ولا شاهدي عدل","answer":"الجواب: لا هذا غلط ما له أصل، هذا من عمل الشيعة، يقولون: نكاح متعة، يتفقون مع المرأة على أيام معدودة، هذا يقال له: نكاح متعة، هذا من عمل الرافضة. \nالسؤال: سمعتها عن طريق الطنطاوي؟ السؤال: يعني أن هذا ما يجوز، إذا تصادق معها وقالت أن هذا زوجي، وقال أن هذه زوجتي، ما يقوم مقام الولي؟","link":"https://binbaz.org.sa/fatwas/1469/حكم-الزواج-بدون-ولي-ولا-شاهدي-عدل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_399.mp3","categories":["قضايا المرأة","شروط وأركان الزواج"]},{"id":6086,"question":"عندي شقيقتي تبلغ من العمر عشرين سنة، ولم تتزوج، وكلما تقدم رجل إلى خطبتها امتنعت من الزواج منه، وتقول: أنا لا آخذ إلا أولاد عمي؛ علمًا أن أولاد عمها أكثرهم ما يصلي، نرجو أن تدلونا إلى مخرج من هذا المأزق؟","title":"حكم من تأبي الزواج إلا من بني عمومتها","answer":"الجواب: الحاجة لها، فإذا كانت إذا خطبت لا تريد، وتأبى إلا أولاد عمها، تنصح، ويقال لها: ليس من الشرط أولاد عمك أولًا، قد لا يرغبون فيك، قد يكون لهم رغبة في أخرى لمن هو أجمل منك، وغير ذلك من الأسباب، قد يكون أولاد عمك لا خير فيهم؛ لأنهم لا يصلون، فُسَّاق، لا يصلون، فلا وجه لانتظارهم، وإن كان قد يهديهم الله، ويتوبون، لكن لا وجه لانتظارهم؛ لأن المرأة على خطر، والشاب على خطر؛ فينبغي البدار بالزواج، وعدم الانتظار إذا جاء الزوج المناسب. فأولياء المرأة ينصحونها، ويوجهونها إلى الخير، حتى تقبل الخاطب الطيب، ولو كان من غير أولاد عمها، هذا هو الواجب، وعلى الأولياء ألا يحبسوها لأولاد عمها، بعض الأولياء يقول: لا أبدًا إلا ولد عمها، وإلا تبقى عندنا، ويلزمها، ويكرهها على ولد عمها، وقد يكونون غير صالحين، وقد يكونون فيهم علل أخرى غير الصلاح لا ترضاه المرأة. ولا يجوز لأبيها أن يرغمها على أولاد عمها، ولا يجوز لأولاد عمها أيضًا أن يرغموها، ويتوعدوها، ويقولون: إن تزوجت؛ فعلنا، وفعلنا، هذا كله لا يجوز، كله من أمر الجاهلية، لا يجوز، لا لأبيها أن يرغمها، ولا لأولاد عمها أن يرغموها، وليس لهم أن يتوعدوا من تزوجها بقتله، أو ضربه، أو ما أشبه ذلك، كل هذا من أمر الجاهلية، فعلى ولاة الأمور إذا علموا هذا أن يعزروا من فعل ذلك، وأن يؤدبوهم على ذلك؛ ردعًا للظلم، وحسمًا لمادة الفساد.","link":"https://binbaz.org.sa/fatwas/1508/حكم-من-تابي-الزواج-الا-من-بني-عمومتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_438.mp3","categories":["شروط وأركان الزواج"]},{"id":6095,"question":"إذا اتفق الإخوة أن يزوجوا عيالهم كل واحد ابنة الثاني من دون مهر، فهل يدخل في ذلك الشغار؟","title":"حكم النكاح بين الأقارب إذا خلا من المشارطة والمهر","answer":"الجواب: ليس هذا من الشغار، إذا كان ما هو شرط، وهذا خطب هذه، وهذا خطب هذه، واتفق آباء الأولاد والنساء على ذلك من دون شرط؛ فلا بأس بذلك، ولكن لا بدّ من المهر، لكل واحدة مهر المثل، وإن لم يسموا؛ فلا بدّ من المهر؛ لأن الله -جل وعلا- قال: لَا جُنَاحَ عَلَيْكُمْ إِنْ طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً [البقرة:236] فالنكاح صحيح، ثم قال بعده وَمَتِّعُوهُنَّ [البقرة:236]،وفي الحديث الصحيح أن النبي ﷺ سئل عن المرأة التي لا يفرض لها، قال :  لها مهر نسائها، لا وكس، ولا شط.  السؤال:...؟ الجواب: إذا تراضوا به؛ لا بأس، إذا تراضوا على الكسوة، أو على دراهم، أو على حلي ذهب، وفضة؛ كفى.","link":"https://binbaz.org.sa/fatwas/1507/حكم-النكاح-بين-الاقارب-اذا-خلا-من-المشارطة-والمهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_437.mp3","categories":["الآداب والأخلاق","شروط وأركان الزواج"]},{"id":6106,"question":"لي أخ من ناحية الأم، وله أخت من ناحية أبيه، فهل يجوز لي الزواج منها؟","title":"حكم الزواج بأخت الأخ من الأم من جهة أبيه","answer":"الجواب: نعم إذا كان ما بينكما رضاع؛ فلا بأس، أخوك من أمك له أخت من أبيه، فأنت تتزوج أخته من أبيه؛ لأن أباه ليس أباك، إنما اشتركتما في الأم، فإذا تزوجت أخت أخيك من أمك، وهي أخته من أبيه، وليس بينكما رضاعة، ولا قرابة أخرى؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/1539/حكم-الزواج-باخت-الاخ-من-الام-من-جهة-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_469.mp3","categories":["شروط وأركان الزواج"]},{"id":6172,"question":"إذا كان رجل عنده بنت في حق الزواج، ولم يتقدم لخطبتها إلا رجل ليس كفأً في دينه، فهل يزوجها إياه؟","title":"حكم تزويج البنت من ليس كفئاً في دينه","answer":"الجواب: مثل ما تقدم، ينظر إذا كان النقص في دينه لا يبلغ الكفر، ولكن عنده بعض المعاصي؛ فلا حرج في ذلك إذا لم يتيسر من هو خير منه، أما إذا تيسر من هو خير منه؛ فالخير هو الذي يقدم، لكن إذا تعطلت الأمور، ولم ييسر لها الكفء في الدين، وإنما تيسر لها إنسان فيه بعض المعاصي، وليس بكافر؛ فلا بأس. وفق الله الجميع، ورزقنا وإياكم العلم النافع، والعمل الصالح، وأصلح أحوالنا جميعًا، وهدى المسلمين جميعًا، وأصلح شبابهم، وفتياتهم، ومنَّ على الجميع بالاستقامة، إنه جواد كريم، وصلى الله على نبينا محمد.","link":"https://binbaz.org.sa/fatwas/1632/حكم-تزويج-البنت-من-ليس-كفىا-في-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_523.mp3","categories":["قضايا المرأة","شروط وأركان الزواج"]},{"id":6178,"question":"إذا رفضت ابنتي الزواج من الكفء، وعذرها في ذلك أنه ليس من أقربائها، وأنا بحثت الكفء أولًا من أقربائها، ولم أجد، فماذا أفعل؟","title":"حكم رفض البنت الزواج من الكفء","answer":"الجواب: إذا رفضت البنت الزواج من الخاطب؛ لأنه ليس من أقربائها، أو لأنه فقير، أو لأسباب أخرى فليس له إجبارها، الحاجة لها وليست له، فإذا لم ترض؛ فعليه أن ينصح، ويشير، ويقول لأمها، وقريباتها أن ينصحنها، وأن يشرن عليها، ويجتهد في هذا، أما إجبارها لا يجوز، الحاجة لها. لكن إذا رأى أن الزوج جدير بأن يزوج؛ شرح لها حاله، وبين لها فضله، وأن المال أمره سهل، سوف يأتي، وسوف يقوم بالواجب -إن شاء الله- ويقول لها: سأساعده بما يقصر عليك منه، وما أشبه ذلك، ويشير على أمها، وعلى قريباتها أن ينصحنها، ويتكلمن معها في ذلك، وإن رضيت، ووافقت فالحمد لله، وإلا لم يجز له إجبارها. النبي -عليه الصلاة والسلام- قال: لا تزوج الأيم حتى تستأمر، ولا البكر حتى تستأذن قالوا: يا رسول الله، إنها تستحي؟ قال: إذنها سكوتها فإذا أبت، وقالت: لا، لا تزوجوني يتركوها، أما إن سكتت فإنه يزوجها.","link":"https://binbaz.org.sa/fatwas/1629/حكم-رفض-البنت-الزواج-من-الكفء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_520.mp3","categories":["قضايا المرأة","شروط وأركان الزواج"]},{"id":6281,"question":"ما هو حكم الشرع في أخ مسلم أعزب يخشى على نفسه فتنة النساء، وتقدم لأخت ذات دين، ورضيت به، لكن والديه يطلبون في الزوجة أن تكون ذات نسب، وأن تكون حاملة لشهادة علمية عالية، هل يطيع والديه، أم يرضى بزواجه من الصالحة؟","title":"عدم طاعة الوالدين في رفضهم الزواج من المتدينة غير النسيبة","answer":"الجواب: إذا وجد امرأة صالحة، مناسبة؛ يتزوجها ولو ليس معها شهادات، ولا معروفة بنسبها، إذا كانت امرأة في نفسها صالحة، وليس لهما طاعة في هذا؛ إنما الطاعة في المعروف، لكن يخاطبهم بالتي هي أحسن، ويجتهد في إرضائهما، ولا يكون عنيفًا معهما، حقهما عظيم، لكن يلاحظهما بالطريقة الحسنى.. وللأولياء أن يطالبوا بهذا الشيء، وأن يعرف النسب، هذا يجوز عند جمع من أهل العلم، لكن مسألة الشهادة، وما الشهادة! وأن تكون كذا، فهو ليس بلازم، أما النسب فأمره على كل حال له وجاهة عند كثير من أهل العلم، ولكن لا يضر، سواء كانت مولاة، أو أعجمية، أو من قريش، أو من غيرها، لا يضر إِنَّ أَكْرَمَكُمْ عِندَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] ليس بشرط.","link":"https://binbaz.org.sa/fatwas/1798/عدم-طاعة-الوالدين-في-رفضهم-الزواج-من-المتدينة-غير-النسيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_637.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":6282,"question":"خطبت بنتًا ثم فسخت الخطبة وتزوجت أمها فما رأي سماحتكم هل هذا حلال أم حرام؟","title":"حكم الزواج بأم من فسخت خطوبتها","answer":"الجواب:  إذا خطب امرأة ثم ترك الخطبة وتزوج أمها لا بأس، أما إذا عقد عليها تم العقد حرمت أمها، أما إذا كان ما تم العقد وكانت مجرد خطبة فقط ثم هون وأخذ الأم لا بأس.","link":"https://binbaz.org.sa/fatwas/1793/حكم-الزواج-بام-من-فسخت-خطوبتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_632.mp3","categories":["المحرمات من النساء","شروط وأركان الزواج"]},{"id":6312,"question":"وآخر يسأل ما هو فصل القول في العزل؟ وما حكم الزواج بشهود غير عدول؟","title":"القول الفصل في حكم العزل","answer":"الجواب: العزل إذا دعت إليه الحاجة؛ لا بأس، قال جابر : \"كنا نعزل والقرآن ينزل\" وقال في الرواية الأخرى: \"فبلغ النبي ذلك؛ فلم ينهنا\" إذا دعت إليه الحاجة بسبب أن المرأة تعبت بعد الولادة، ويخشي أن تحمل بسرعة، فلا تتمكن  من تربية الأولاد، فعزل عنها بعض الوقت؛ فلا بأس. وقد أرشد المشايخ إلى تحريم الحبوب المانعة من الحمل، وقد قرر مجلس هيئة كبار العلماء بالمنع من تعاطي الحبوب إلا للضرورة، كالمرأة التي بها مرض يضرها الحبل؛ فلا بأس، من تعاطي ذلك إذا كان قرر الأطباء أنه يضرها الحبل، أو امرأة تحمل، هذا على هذا من تعاطيها وقتًا قصيرًا، كالسنة، والسنتين وقت الرضاع؛ حتى تقوى، وتستطيع على تربية أولادها، والعناية بهم، وإلا فالواجب منع ذلك، والحذر من ذلك.  وهكذا العزل إذا عزل كما أقره النبي ﷺ بعض الوقت’ والعزل كونه يجامعها، فإذا أحس بخروج المني؛ أخرج ذكره وألقى المني خارجًا؛ حتى لا تحمل، هذا العزل، وهو يشبه تعاطي الحبوب، وهو الحجة في جواز تعاطيها عند الحاجة، والضرورة. فالمقصود: أن العزل تركه أولى مهما أمكن؛ لأن الأولاد رزقهم على الله، والشارع يطلب تكثير النسل؛ ليعبدوا الله، ويطيعوه، وفي عدم العزل كمال اللذة في الجماع، وقضاء الوطر، وإذا أخرج ذكره عند نزول المني؛ كان هذا فيه ضعف للجماع، وضعف لتعاطي الحاجة، وقضاء الوطر، وقد يكون صعبًا على الإنسان؛ فينبغي في مثل هذا ألا يعزل، وأن يتمتع بما أباح الله له، ورزقه على الله -جل وعلا- إذا حملت. وينبغي لها أن تصبر هي أيضاً، وتستعين بالله على تربية الأولاد، ولو كثروا، لكن إذا دعت الضرورة؛ لا بأس بالعزل، ولا بأس بتعاطي الدواء المانع من الحمل وقتًا قصيرًا، تستعين به المرأة على تربية أولادها.","link":"https://binbaz.org.sa/fatwas/1906/القول-الفصل-في-حكم-العزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_689.mp3","categories":["شروط وأركان الزواج"]},{"id":6333,"question":"وآخر يسأل ما هو فصل القول في العزل؟ وما حكم الزواج بشهود غير عدول؟","title":"القول الفصل في حكم العزل","answer":"الجواب: العزل إذا دعت إليه الحاجة؛ لا بأس، قال جابر : \"كنا نعزل والقرآن ينزل\" وقال في الرواية الأخرى: \"فبلغ النبي ذلك؛ فلم ينهنا\" إذا دعت إليه الحاجة بسبب أن المرأة تعبت بعد الولادة، ويخشي أن تحمل بسرعة، فلا تتمكن  من تربية الأولاد، فعزل عنها بعض الوقت؛ فلا بأس. وقد أرشد المشايخ إلى تحريم الحبوب المانعة من الحمل، وقد قرر مجلس هيئة كبار العلماء بالمنع من تعاطي الحبوب إلا للضرورة، كالمرأة التي بها مرض يضرها الحبل؛ فلا بأس، من تعاطي ذلك إذا كان قرر الأطباء أنه يضرها الحبل، أو امرأة تحمل، هذا على هذا من تعاطيها وقتًا قصيرًا، كالسنة، والسنتين وقت الرضاع؛ حتى تقوى، وتستطيع على تربية أولادها، والعناية بهم، وإلا فالواجب منع ذلك، والحذر من ذلك.  وهكذا العزل إذا عزل كما أقره النبي ﷺ بعض الوقت’ والعزل كونه يجامعها، فإذا أحس بخروج المني؛ أخرج ذكره وألقى المني خارجًا؛ حتى لا تحمل، هذا العزل، وهو يشبه تعاطي الحبوب، وهو الحجة في جواز تعاطيها عند الحاجة، والضرورة. فالمقصود: أن العزل تركه أولى مهما أمكن؛ لأن الأولاد رزقهم على الله، والشارع يطلب تكثير النسل؛ ليعبدوا الله، ويطيعوه، وفي عدم العزل كمال اللذة في الجماع، وقضاء الوطر، وإذا أخرج ذكره عند نزول المني؛ كان هذا فيه ضعف للجماع، وضعف لتعاطي الحاجة، وقضاء الوطر، وقد يكون صعبًا على الإنسان؛ فينبغي في مثل هذا ألا يعزل، وأن يتمتع بما أباح الله له، ورزقه على الله -جل وعلا- إذا حملت. وينبغي لها أن تصبر هي أيضاً، وتستعين بالله على تربية الأولاد، ولو كثروا، لكن إذا دعت الضرورة؛ لا بأس بالعزل، ولا بأس بتعاطي الدواء المانع من الحمل وقتًا قصيرًا، تستعين به المرأة على تربية أولادها.","link":"https://binbaz.org.sa/fatwas/1906/القول-الفصل-في-حكم-العزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_689.mp3","categories":["شروط وأركان الزواج"]},{"id":6373,"question":"تزوجت امرأة، وطلقتها، وجاءت عند رجل آخر، وجاب منها بنات، هل يحلون لأولادي؟","title":"حكم زواج أولاد الرجل ببنات مطلقته من رجل آخر","answer":"الجواب: يحلون لأولادك إذا كان ما بينهم رضاعة، أما أنت لا، بنات زوجك لا، يحلون لأولادك.","link":"https://binbaz.org.sa/fatwas/1949/حكم-زواج-اولاد-الرجل-ببنات-مطلقته-من-رجل-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_736.mp3","categories":["شروط وأركان الزواج"]},{"id":6383,"question":"تزوجت امرأة، وطلقتها، وجاءت عند رجل آخر، وجاب منها بنات، هل يحلون لأولادي؟","title":"حكم زواج أولاد الرجل ببنات مطلقته من رجل آخر","answer":"الجواب: يحلون لأولادك إذا كان ما بينهم رضاعة، أما أنت لا، بنات زوجك لا، يحلون لأولادك.","link":"https://binbaz.org.sa/fatwas/1949/حكم-زواج-اولاد-الرجل-ببنات-مطلقته-من-رجل-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_736.mp3","categories":["شروط وأركان الزواج"]},{"id":6398,"question":"زواج وجد فيه الولي، والخاطب، والمخطوبة، وشاهدين هما إخوة للخاطب، دون وجود قاض لعقد الزواج، فهل هذا نصاب كامل للزواج؟","title":"جواز الاكتفاء بالشاهدين والولي في عقد النكاح","answer":"الجواب: ما هو بشرط، القاضي ليس بشرط، القاضي إذا وجد الشاهدين العدلين مع الولي، والزوج؛ كفى ولو خطب أحد الشاهدين، أو الولي، أو الزوج خطبة النكاح؛ كفى، والخطبة ليست بلازمة، الخطبة: إن الحمد لله، إلى آخره، غير لازمة، مستحبة، فلو قال الولي للزوج: زوجتك، وقال الزوج: قبلت، وحضر الشاهدان؛ كفى، ولو ما في خطبة، هذا كاف لكن الخطبة أفضل كونه يحضر عند عالم، أو طالب عالم، يقرأ الخطبة، ويعلمهم ما قد يجهلون، ويوضح لهم ما قد يخفى عليهم، هذا طيب، لكن ليس بشرط.  المقصود: الولي، والشاهدان، فإذا قال الولي للزوج: زوجتك بنتي فلانة، أو أختي فلانة، وقبلت هذا النكاح، وحضره الشاهدان العدلان، سواء من إخوة الولي، أو من إخوة الزوج، أو من غيرهم؛ كفى ذلك، والحمد لله، بشرط سلامة المرأة من الموانع، المرأة بكر، أو قد مات عنها زوجها، أو مطلقة طلاقًا ثابتًا معروفًا، وقد خرجت من العدة، وبرضاها، قد استُأذنت؛ هذا لا بأس.  وإذا كان على يد طالب العلم يكون يبصرهم في هذه الأمور، إن كانت مطلقة؛ عرف ثبوت الطلاق، وبين لهم العدة، هل انتهت، أم لا؟ ويبصرهم أيضاً هل شاوروا المرأة، هل شاورها وليها؟ هل استأذنها؟ هل هي راضية؟ وقد يحتاج إلى بينة، وشهود أنها راضية؛ لأن بعض الناس قد يتساهل، ويكذب عليها، ويقول: إنها راضية، وهو يكذب، هذا قد يقع من الحاضرة، والبادية، فالتثبت واجب من العاقد لهما.","link":"https://binbaz.org.sa/fatwas/1976/جواز-الاكتفاء-بالشاهدين-والولي-في-عقد-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_763.mp3","categories":["شروط وأركان الزواج"]},{"id":6406,"question":"تزوج رجل من امرأة دون علم والديها، وبقي الزوجان في حيرة، هل ينفك زواجهما بغضب أبوي الزوجة، وهل عليهما إيقاع الطلاق حتى يرضوا الوالدين، فما حكم الكتاب، والسنة في هذا الزواج؟","title":"حكم زواج المرأة دون علم الوالدين","answer":"الجواب: هذا فيه تفصيل، يعني الأب هو الولي، كيف يتزوج وهو ما درى الأب، وهو الولي، هذا ما يصلح، لكن إذا كان الولي عاضلاً، منعها من الزواج بغير حق، فللولي الثاني أن يزوج بدلاً من الأب، كأخيها، أو عمها الموجود، أقرب شخص بعد الأب، يزوج ولو ما درى، الأب إذا كان الأب عاضلًا، ظالمًا، قد حجر عليها ومنعها من الزواج؛ تسقط ولايته، فيزوج من دونه كابنه الذي هو أخوها، أو أخيه الذي هو عمها، إذا كان ما له أبناء، أو كان أبناؤه مثله عاضلين أيضاً، مانعينها من الزواج فللولي الآخر أن يزوج، وللقاضي إذا منعوا كلهم أن يزوج إذا امتنع الأولياء أن يزوجوها بغير حق، وعضلوها إما لمال كثير، أو لعداوة بينهم، وبين الخاطب، أو لأسباب أخرى، فللقاضي ولولي الأمر أن يزوجوها، ولو لم يعلم أبوها، وإخوتها، ولو سجنوا في ذلك؛ فلا بأس؛ لأن هذا من إزالة الظلم عن المرأة. أما أن يزوجها غير أبيها بغير حق، وبغير عضل من أبيها، وبغير سبب شرعي؛ هذا يكون نكاحًا باطلاً، فاسدًا النبي -عليه الصلاة والسلام- قال: لا نكاح إلا بولي وأبوها هو الولي مقدم على بقية الأولياء،. المقصود: أنه إذا زوجت بغير ولي شرعي؛ يكون النكاح فاسدًا، ويستحق الزوج، والزوجة التأديب، والتعزير من جهة ولاة الأمور؛ حتى لا يعودوا إلى مثل هذا، لا هم، ولا غيرهم، أما إذا كان الزواج عن عضل من الأولياء، وعن إذن شرعي من ولاة الأمور؛ لأن هذا الولي عضل، وظلم؛ فتسقط ولايته؛ لأن الله قال: وَلَا تَعْضُلُوهُنَّ[النساء:19] فإذا عضلها أبوها، أو أخوتها، أو أعمامها، أو بنو عمها، وظلموها، ومنعوها من الزواج؛ تدخل ولي الأمر، تدخل القضاء، النبي -عليه الصلاة والسلام- قال: السلطان ولي من لا ولي له والعاضل ليس بولي. السؤال: إذا كان بينهم عداوة، فتزوجها جبرًا ... الجواب: من هو؟ الطالب: يعني إذا كان المتقدم بينه، وبين أهل الزوجة ...؟ الجواب: ينظر ولي الأمر، يرفع الأمر للقاضي، والقاضي ينظر أما يظلمونها لأجل شحناء بينهم في الخصومات، وأشباه ذلك، وهو صالح في نفسه، وهو يريدها، وتريده، ما دخلها؟","link":"https://binbaz.org.sa/fatwas/2121/حكم-زواج-المراة-دون-علم-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_771.mp3","categories":["شروط وأركان الزواج"]},{"id":6438,"question":"هل يجوز العزل بغرض تربية الطفل في حالة الرضاعة الصناعية لمرض في ثدي أمه؟","title":"هل يجوز العزل بغرض تربية الطفل؟","answer":"الجواب: الأصل العزل جائز هذا هو الأصل، الأصل جائز يجوز العزل للمصلحة الشرعية، وللأسباب التي يتفق عليها الزوجان، لكن ينبغي ألا تكون طويلة؛ لأن العزل الكثير قد يسبب مشاكل على الجميع، لكن إذا كان في مدة قليلة، مثل ما جاء عن النبي ﷺ قال جابر: \"كنا نعزل والقرآن ينزل، ولو كان شيئًا ينهى عنه لنهانا عنه القرآن\" فالعزل موجود في عهده -عليه الصلاة والسلام- ولم ينه عنه.","link":"https://binbaz.org.sa/fatwas/2191/هل-يجوز-العزل-بغرض-تربية-الطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_816.mp3","categories":["شروط وأركان الزواج","تنظيم الحمل وموانعه"]},{"id":6451,"question":"هل يجوز العزل بغرض تربية الطفل في حالة الرضاعة الصناعية لمرض في ثدي أمه؟","title":"هل يجوز العزل بغرض تربية الطفل؟","answer":"الجواب: الأصل العزل جائز هذا هو الأصل، الأصل جائز يجوز العزل للمصلحة الشرعية، وللأسباب التي يتفق عليها الزوجان، لكن ينبغي ألا تكون طويلة؛ لأن العزل الكثير قد يسبب مشاكل على الجميع، لكن إذا كان في مدة قليلة، مثل ما جاء عن النبي ﷺ قال جابر: \"كنا نعزل والقرآن ينزل، ولو كان شيئًا ينهى عنه لنهانا عنه القرآن\" فالعزل موجود في عهده -عليه الصلاة والسلام- ولم ينه عنه.","link":"https://binbaz.org.sa/fatwas/2191/هل-يجوز-العزل-بغرض-تربية-الطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_816.mp3","categories":["شروط وأركان الزواج","تنظيم الحمل وموانعه"]},{"id":6502,"question":"ما حكم رجل زنى بامرأة، وتزوجها، وأنجبا أولادًا، وقد أتموا جميعًا هو وزوجته، وأولاده فريضة الحج، هل جريمة الزنا رفعت عنهما بقضاء فريضة الحج؟ وما هو وضع الأولاد، هل يعتبر الأولاد زنا، علمًا بأن الإنجاب تم بعد إتمام الزواج، أي لم يحدث حمل قبل الزواج؟","title":"حكم من زنى بامرأة ثم تزوج بها","answer":"الجواب: من تاب تاب الله عليه، ولو قبل الحج، إذا تابا تابا الله عليهما، ولو قبل الحج، ما هو بشرط الحج، التوبة تكفي، إذا تاب، وندم على ما فعل فالله -جل وعلا- يتوب على من تاب، فالتوبة تَجُبُّ ما قبلها، والإسلام يجب ما قبله، والحج زيادة خير، نسأل الله لهم الهداية. السؤال: هل يصح الزواج بالزانية؟ الجواب: يصح الزواج بها إذا تابت، لا بد من أن توعظ، وتذكر، فإذا تابت، وأظهرت التوبة؛ فلا بأس ...","link":"https://binbaz.org.sa/fatwas/2267/حكم-من-زنى-بامراة-ثم-تزوج-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_890.mp3","categories":["الأنكحة المحرمة","شروط وأركان الزواج","قضايا المرأة"]},{"id":6524,"question":"ما حكم رجل زنى بامرأة، وتزوجها، وأنجبا أولادًا، وقد أتموا جميعًا هو وزوجته، وأولاده فريضة الحج، هل جريمة الزنا رفعت عنهما بقضاء فريضة الحج؟ وما هو وضع الأولاد، هل يعتبر الأولاد زنا، علمًا بأن الإنجاب تم بعد إتمام الزواج، أي لم يحدث حمل قبل الزواج؟","title":"حكم من زنى بامرأة ثم تزوج بها","answer":"الجواب: من تاب تاب الله عليه، ولو قبل الحج، إذا تابا تابا الله عليهما، ولو قبل الحج، ما هو بشرط الحج، التوبة تكفي، إذا تاب، وندم على ما فعل فالله -جل وعلا- يتوب على من تاب، فالتوبة تَجُبُّ ما قبلها، والإسلام يجب ما قبله، والحج زيادة خير، نسأل الله لهم الهداية. السؤال: هل يصح الزواج بالزانية؟ الجواب: يصح الزواج بها إذا تابت، لا بد من أن توعظ، وتذكر، فإذا تابت، وأظهرت التوبة؛ فلا بأس ...","link":"https://binbaz.org.sa/fatwas/2267/حكم-من-زنى-بامراة-ثم-تزوج-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_890.mp3","categories":["الأنكحة المحرمة","شروط وأركان الزواج","قضايا المرأة"]},{"id":6614,"question":"سبق أن قدمت لسماحتكم سؤالي، وهذا وقد جعلني في قلق، وهو أنني خطبت بنتًا متدينة، ولكن أمي لا تريدها زوجة لي لخلافات عائلية، وقد قلتم سماحتكم إنه لا طاعة لمخلوق في معصية الخالق فما هو صحة حديث ابن عمر أطع أباك هذا السؤال ضروري، ونرجو من سماحتكم الإجابة عليه؟","title":"حكم الزواج بدون رضا الوالدة","answer":"الجواب:  إذا كان أبوك مثل عمر بن الخطاب، وأمك مثل عمر بن الخطاب، المقصود أن النبي ﷺ أمر ابن عمر أن يطيع عمر في امرأة ما تصلح، أما إذا كانت المرأة صالحة، وجيدة، ولكن أمك لشيء بينها وبينها لا تريدها، فإذا استطعت أن تجد غيرها، وتجمع بين المصلحتين -بين أمك وبين المرأة- فهذا أحسن، وأطيب، وإذا لم يتيسر ذلك؛ فأرض والديك بالكلام الطيب، وإذا كانت لا تريدها فاجعلها في مكان آخر، وبيت آخر، وأحسن إلى أمك، وعف نفسك، تزوج حتى تعف نفسك، وتطيع ربك بالزواج، أنت مأمور بالزواج، النبي ﷺ يقول: يا معشر الشباب من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج.  أنت مأمور بطاعة ربك، وطاعة أمك، فعليك أن تبر أمك بالكلام الطيب، والإحسان إليها، والإنفاق عليها -إذا كانت محتاجة- وعليك أن تعف نفسك بالزواج إذا تيسرت المرأة الصالحة المناسبة، وإذا استطعت الجمع بين الأمرين -بين إرضائها وبين وجود المرأة المناسبة- فهذا خير، وإذا كان ما تيسر، ولم يتيسر لك إلا هذه المرأة التي تكرهها بغير حق .. فتزوج، وأرض أمك بالشيء الذي تستطيع من الطرق، وإذا لم تستطع؛ فاجعلها في مكان، وأمك في مكان، واستعن بالله على ذلك، والله يعينك إذا أردت الخير، وصدقت في طلب الخير.","link":"https://binbaz.org.sa/fatwas/2462/حكم-الزواج-بدون-رضا-الوالدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_989.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":6622,"question":"بنت صغيرة زوجها أبوها من رجل، ومات أبوها قبل عقد النكاح بينهما، وأصبحت البنت حينئذ يتيمة لصغرها، وبعد ثلاث سنوات بعد ذلك تقريبًا نفذ أخوها الأكبر عملية عقد الزواج مع رفض البنت ألبتة هذا، لما عرس أخوها بينهما في اليوم الأول من العرس؛ فرت هاربة إلى مكان مجهول، وأصبح الناس يبحثون عنها حتى خافوا أن تكون قد ماتت، أو من ضياعة، وبعد أسبوع تقريبًا وجدوها وهي مختبئة -هربت من الزوج- ومن ذلك اليوم لا اتصال بينهما، ومرت بذلك عدة سنوات، وكلما تسأل البنت عن رجوعها إلى زوجها تتردد عليهم بكلام بعيد عن رجوعها إليه، علمًا بأن الرجل يحبه أهل البنت؛ لأنه من أقاربهم، هكذا مل الناس، وأيسوا من رجوع البنت إلى زوجها الأول، وبعد مرور سنوات خطبها رجل آخر، وأعطته نفسها، وولد بينهما ولد، وبعدما ولد الولد؛ صار بين الناس الكلام، والشكوك عن صحة هذا الولد، وهل هو حلال، أو حرام إلى آخره السؤال، هل هذا الزواج الأول يُعتبرُ، علمًا بأنها تعبت كارهة، ويتيمة، وهل الولد الذي حصل بينهما وبين الرجل الذي أحبته حلال، أو حرام؟ ولماذا وما حكم الشرع في هذه المسألة؟","title":"حكم تزويج البنت بدون رضاها","answer":"الجواب:  الزواج الأول إذا كان بالإكراه لا يجوز؛ لأن النبي ﷺ نهى الأولياء أن يزوجوا البنات إلا بالإذن، حتى الأب، يقول ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن قالوا: يا رسول الله إنها تستحي، قال: إذنها سكوتها على البكر يستأذنها أبوها، وإذنها صماتها. وذهب بعض أهل العلم إلى أن البكر يزوجها أبوها بالإكراه، وهو أعلم بمصالحها، لكنه قول ضعيف، قول مرجوح، والصواب الذي عليه المحققون من أهل العلم، وهو الراجح بالدليل: أنه ليس للأب أن يزوجها بالإكراه، بل يصبر حتى ترضى، ويلتمس لها الزوج الصالح الذي ترضى به، وليس له أن يجبرها على ذلك لما في الجبر من النتائج القبيحة، والعواقب الوخيمة. أما هذه المرأة التي فعلت ما فعلت فعليها أن تتقدم، كان الواجب عليها أن تتقدم للمحكمة، وتبين أمرها وتشرح قصتها حتى تتوسط المحكمة في الموضوع، وأما زواجها الأخير، وإن كان بعد الطلاق من الأول، أو بعد التفريق من الحكام بينها، وبين الأول، وبعد العدة؛ صح زواجها، أما إن كان الوطء بالسفاح –بالزنا- فهذا غلط، والولد ليس ولدًا شرعيًا، يتبعها هي، ولا يتبع الواطئ؛ لأن الواطئ عاهر، ظالم، ليس له ولد. أما إن كان هذا نكاحًا شرعيًا بعدما طلقها الزوج الأول، أو بعدما فسخها الحاكم من الزوج الأول، هذا الزواج الثاني إذا كان بملك الشرع، وبشروطه الشرعية يكون نافذًا، ويكون الولد لأبيه، وهذا محل تفصيل، يجب على المرأة أن تتقدم بهذا الأمر إلى المحكمة في بلدها حتى تنظر المحكمة فيما يجب.","link":"https://binbaz.org.sa/fatwas/2459/حكم-تزويج-البنت-بدون-رضاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_986.mp3","categories":["شروط وأركان الزواج"]},{"id":6624,"question":"إذا كان لي بنت عم خطبتها، فأبت أن تتزوجني، مع العلم أن هناك من يريدها رجالًا غير صالحين، فهل يجوز لي أن أمنعه من الزواج منها، مع العلم أنه ليس بقريب منها، وكذلك لها عيال عم صالحين يخطبونها، وتأبى عنهم؟","title":"حكم إرغام المرأة على الزواج ممن لا ترضاه","answer":"الجواب: ليس لأحد من الأقارب أن يمنع المرأة من الزواج، ويحجر عليها كفعل الجاهلية، هذا ممنوع، هذا لا يجوز، ليس لأحد أن يحجر على المرأة أن تزوج إلا من شخص معين، لا أبوها، ولا غيره، حتى أبوها ليس له أن يحجرها إلا من شخص معين كابن أخيه، أو ابن أخته، أو ما أشبه ذلك، هذا ظلم، ولا يجوز أبدًا، بل إذا خطب إليها من يرضى دينه، وخلقه، وأمانته فإنه يزوج، أما أن يحبسها لابن أخيه، أو ابن عمه، أو لأحد قبيلته فقط، أما القبائل الأخرى فلا، هذا منكر، هذا ظلم وعمل جاهلي. ولكن إذا وجد الكفء؛ زوجها مطلقًا، ولو أنها رفضت بني عمها، وبني خالها، وأقاربها رفضتهم، وطلبت شخصًا آخر كفأً لها؛ فلا بأس عليه أن يزوجها من كفئها، ولو كان من غير أقاربها، هذا هو الواجب عليه؛ لأن الله -جل وعلا- قال: إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] وفي الحديث: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوا؛ تكن فتنة في الأرض، وفساد كبير. فإذا خطب إليها كفؤها من العرب، وهي عربية من الموالي، وهي مولاة من العجم، وهي أعجمية، لا بأس يزوجها، وليس له أن يمنعها إلا بعذر شرعي، إما لكونه كافرًا الخاطب، أو لكونه لا يناسب من جهة فساده الظاهر، ومعاصيه الظاهرة، أو من جهة أنه يكسب تزويجه فتنة بينه، وبين أهله؛ لأنه ليس من قبيلتهم، وليس من العرب الذين يزوج أمثالهم، ويحصل بتزويجها له فتنة بينهم، وفساد كبير، فإن هذا يتقى. أما لأجل الهوى، ولأجل طاعة زيد وعمرو من أقاربها هذا ظلم لا يجوز، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2487/حكم-ارغام-المراة-على-الزواج-ممن-لا-ترضاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1014.mp3","categories":["قضايا المرأة","شروط وأركان الزواج"]},{"id":6630,"question":"خطب البنت من أهلها، وقال: إنه سيوريها الشقة، وراحت معه، ويوم راحت معه قال: خلاص هم يعقدون لنا عقداً بعد يومين خلينا ندخل الحين دخلوا، وعقب ما دخلوا أراد الله أنها تحيض عقب الدخلة هذه، ما صار فيها حمل، ولا صار فيها شيء، وبعدين عقدوا العقد الشرعي، ما الحكم في هذا؟","title":"حكم من زنى بمخطوبته ثم عقد عليها بعد ما حاضت","answer":"الشيخ: زنا بها قبل؟ الطاب: نعم. الجواب: هذا منكر، أعوذ بالله، وليس له نكاحها إلا بعد التوبة، بعد ما تتوب إلى الله، ويتوب هو أيضًا. السؤال: يعقد عليها العقد الشرعي؟ الجواب: بعد التوبة إذا ندمت، وأظهرت الندم، والإقلاع .. إذا تابا، ورجعا إلى الله؛ يزوجا، وقبل هذا لا يزوجا. الطالب: أكتب لهم على هذا؟ الجواب: أعلمهم، نعم.","link":"https://binbaz.org.sa/fatwas/2483/حكم-من-زنى-بمخطوبته-ثم-عقد-عليها-بعد-ما-حاضت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1010.mp3","categories":["شروط وأركان الزواج"]},{"id":6639,"question":"إذا كان لي بنت عم خطبتها، فأبت أن تتزوجني، مع العلم أن هناك من يريدها رجالًا غير صالحين، فهل يجوز لي أن أمنعه من الزواج منها، مع العلم أنه ليس بقريب منها، وكذلك لها عيال عم صالحين يخطبونها، وتأبى عنهم؟","title":"حكم إرغام المرأة على الزواج ممن لا ترضاه","answer":"الجواب: ليس لأحد من الأقارب أن يمنع المرأة من الزواج، ويحجر عليها كفعل الجاهلية، هذا ممنوع، هذا لا يجوز، ليس لأحد أن يحجر على المرأة أن تزوج إلا من شخص معين، لا أبوها، ولا غيره، حتى أبوها ليس له أن يحجرها إلا من شخص معين كابن أخيه، أو ابن أخته، أو ما أشبه ذلك، هذا ظلم، ولا يجوز أبدًا، بل إذا خطب إليها من يرضى دينه، وخلقه، وأمانته فإنه يزوج، أما أن يحبسها لابن أخيه، أو ابن عمه، أو لأحد قبيلته فقط، أما القبائل الأخرى فلا، هذا منكر، هذا ظلم وعمل جاهلي. ولكن إذا وجد الكفء؛ زوجها مطلقًا، ولو أنها رفضت بني عمها، وبني خالها، وأقاربها رفضتهم، وطلبت شخصًا آخر كفأً لها؛ فلا بأس عليه أن يزوجها من كفئها، ولو كان من غير أقاربها، هذا هو الواجب عليه؛ لأن الله -جل وعلا- قال: إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] وفي الحديث: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوا؛ تكن فتنة في الأرض، وفساد كبير. فإذا خطب إليها كفؤها من العرب، وهي عربية من الموالي، وهي مولاة من العجم، وهي أعجمية، لا بأس يزوجها، وليس له أن يمنعها إلا بعذر شرعي، إما لكونه كافرًا الخاطب، أو لكونه لا يناسب من جهة فساده الظاهر، ومعاصيه الظاهرة، أو من جهة أنه يكسب تزويجه فتنة بينه، وبين أهله؛ لأنه ليس من قبيلتهم، وليس من العرب الذين يزوج أمثالهم، ويحصل بتزويجها له فتنة بينهم، وفساد كبير، فإن هذا يتقى. أما لأجل الهوى، ولأجل طاعة زيد وعمرو من أقاربها هذا ظلم لا يجوز، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2487/حكم-ارغام-المراة-على-الزواج-ممن-لا-ترضاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1014.mp3","categories":["قضايا المرأة","شروط وأركان الزواج"]},{"id":6646,"question":"خطب البنت من أهلها، وقال: إنه سيوريها الشقة، وراحت معه، ويوم راحت معه قال: خلاص هم يعقدون لنا عقداً بعد يومين خلينا ندخل الحين دخلوا، وعقب ما دخلوا أراد الله أنها تحيض عقب الدخلة هذه، ما صار فيها حمل، ولا صار فيها شيء، وبعدين عقدوا العقد الشرعي، ما الحكم في هذا؟","title":"حكم من زنى بمخطوبته ثم عقد عليها بعد ما حاضت","answer":"الشيخ: زنا بها قبل؟ الطاب: نعم. الجواب: هذا منكر، أعوذ بالله، وليس له نكاحها إلا بعد التوبة، بعد ما تتوب إلى الله، ويتوب هو أيضًا. السؤال: يعقد عليها العقد الشرعي؟ الجواب: بعد التوبة إذا ندمت، وأظهرت الندم، والإقلاع .. إذا تابا، ورجعا إلى الله؛ يزوجا، وقبل هذا لا يزوجا. الطالب: أكتب لهم على هذا؟ الجواب: أعلمهم، نعم.","link":"https://binbaz.org.sa/fatwas/2483/حكم-من-زنى-بمخطوبته-ثم-عقد-عليها-بعد-ما-حاضت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1010.mp3","categories":["شروط وأركان الزواج"]},{"id":6758,"question":"هناك أمر شائع بين الناس عن الخضيري، والقبيلي، وأن القبيلي لا يتزوج من الخضيرية، والخضيري لا يتزوج من القبيلية، فهل هناك حديث يمحو هذا الذي أصبح الناس يشكون منه، أو مشغولون به وعلى بناتهم؟","title":"حكم التزاوج بين الخضيري والقبيلي","answer":"الجواب: هذا شيء لا أصل له، وليس من شروط النكاح، ولكن له أصل من جهة أن الناس أنواع، وأبيات، وقبائل، وأصناف، فكل قبيلة ترغب في أن يكون من قبيلتها إذا تيسر ذلك، وربما صاحوا بمن يزوج بنته من غير قبيلتهم، وربما أنكروا عليه، وربما تساهلوا في ذلك، وإلا فالأمر في هذا سواء، يقول -جل وعلا-: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى [الحجرات:13] يعني من آدم وحواء وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا [الحجرات:13] ما قال لتفاخروا، قال لتعارفوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13] فإذا تيسرت التقوى فهذا هو الأساس العظيم، فاظفر بذات الدين تربت يداك. المقصود: أن الناس في هذا سواسية، فالعربي، والمولى، والأعجمي لا بأس بتزاوجهم فيما بينهم، ويزوج بعضهم بعضًا، فينكح العربي الأعجمية، والمولى العتيقة، ولا بأس بذلك، ولا حرج في ذلك إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13]، وقد زوج النبي ﷺ أسامة بن زيد، وهو مولى عتيق، وأبوه عتيق وهو زيد، زوجهما جميعًا من قريش، وزوج زيدًا زينب، وهي أسدية، وأمها من بني هاشم، وزوج أسامة فاطمة بنت قيس، وهي قرشية، وهذا يدل على أن الأمر في هذا واسع، وكذلك زوج عبدالرحمن بن عوف بلالًا -وهو حبشي، وهي زهرية، قرشية.  المقصود: أن هذه الأمور فيها سعة بحمد الله، وليس فيها ما يوجب الامتناع، ولكن الجهل، والتكبر من بعض الناس، والأنفة القبلية من بعض الناس، وخوف بعض الناس من بعض الناس قد يحمل على أشياء من هذا النمط. فإذا تمكن العلم من الناس، وتمكن الدين من الناس؛ زالت هذه الأمور، واستقر الأمر الشرعي، ولكن بسبب الجهل تقع أمور كثيرة من هذا، وأكثر، وأن خضيري، وقبيلي ما له أصل، وأصله الأصل القديم أن يقال: قبلي، ومولى، أو أعجمي، أما خضيري هذه شيء جديد، حدث من جديد، لا نعلم متى حدث، وإنما المعروف قبلي، هذا من قبائل العرب، عجمي من الأعجام، مولى يعني عتيق، فهؤلاء الناس من حزب هذه الأصول المعروفة، ولا بأس أن يتزوج من هؤلاء، لا بأس أن ينكح العربي الأعجمية، والأعجمي العربية، والعربي المولاة، والمولاة العربي، كل هذا لا بأس به في الإسلام، ولا حرج فيه إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13].","link":"https://binbaz.org.sa/fatwas/2634/حكم-التزاوج-بين-الخضيري-والقبيلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1130.mp3","categories":["الآداب والأخلاق المحمودة","شروط وأركان الزواج"]},{"id":7003,"question":"هل تشترط الكفاءة في النسب؟ وهل لا بد منه، نرجو توضيح ذلك؟","title":"حكم اشتراط الكفاءة في النسب عند الزواج","answer":"الجواب:\n\nلا يشترط الكفاءة في النسب، يجوز للعربي أن ينكح من العجم، والعجم ينكح من العرب، وينكح من الموالي، كل هذا جائز، قال الله تعالى: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13].\n\nوقد زوج النبي ﷺ أسامة بن زيد فاطمة بنت قيس القرشية، وزوج أباه زيد بن حارثة زينب بنت جحش أم المؤمنين قبل النبي -عليه الصلاة والسلام- وهي أسدية، وزوج عبدالرحمن أخته لبلال الحبشي، إلى غير هذا، المقصود أن هذا ليس بشرط.\n\nلكن العرب من شأنهم، وطبيعة العرب من قديم أنهم لا يرضون أن يزوجوا العجم والموالي من بناتهم، ومن تساهل في هذا، وأخذ بما جاءت به الشريعة؛ زوج ولم يبال، لكن مادام امتنع؛ فلا حرج عليه، من امتنع أن يزوج إلا من قبائل العرب؛ فلا حرج عليه، الحمد لله الأمر في هذا واسع. \n\nلكن ليس بشرط لو زوج عربية عجميًا، أو عجمية عربية، أو مولى قد أعتق، أو ما يسمونه بالخضيري الآن، وهو الذي لا تعرف قبيلته، أو ما أشبه ذلك، كله لا بأس به، إنما رجل حر لا .. عنها إلا عند الضرورة، المملوكة فقط إلا عند عجزها عن .. أو عند حصول..، أما إذا كانت غير مملوكة؛ فلا بأس، عربية، أو أعجمية.","link":"https://binbaz.org.sa/fatwas/2939/حكم-اشتراط-الكفاءة-في-النسب-عند-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1387.mp3","categories":["شروط وأركان الزواج"]},{"id":7013,"question":"هل تشترط الكفاءة في النسب؟ وهل لا بد منه، نرجو توضيح ذلك؟","title":"حكم اشتراط الكفاءة في النسب عند الزواج","answer":"الجواب:\n\nلا يشترط الكفاءة في النسب، يجوز للعربي أن ينكح من العجم، والعجم ينكح من العرب، وينكح من الموالي، كل هذا جائز، قال الله تعالى: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13].\n\nوقد زوج النبي ﷺ أسامة بن زيد فاطمة بنت قيس القرشية، وزوج أباه زيد بن حارثة زينب بنت جحش أم المؤمنين قبل النبي -عليه الصلاة والسلام- وهي أسدية، وزوج عبدالرحمن أخته لبلال الحبشي، إلى غير هذا، المقصود أن هذا ليس بشرط.\n\nلكن العرب من شأنهم، وطبيعة العرب من قديم أنهم لا يرضون أن يزوجوا العجم والموالي من بناتهم، ومن تساهل في هذا، وأخذ بما جاءت به الشريعة؛ زوج ولم يبال، لكن مادام امتنع؛ فلا حرج عليه، من امتنع أن يزوج إلا من قبائل العرب؛ فلا حرج عليه، الحمد لله الأمر في هذا واسع. \n\nلكن ليس بشرط لو زوج عربية عجميًا، أو عجمية عربية، أو مولى قد أعتق، أو ما يسمونه بالخضيري الآن، وهو الذي لا تعرف قبيلته، أو ما أشبه ذلك، كله لا بأس به، إنما رجل حر لا .. عنها إلا عند الضرورة، المملوكة فقط إلا عند عجزها عن .. أو عند حصول..، أما إذا كانت غير مملوكة؛ فلا بأس، عربية، أو أعجمية.","link":"https://binbaz.org.sa/fatwas/2939/حكم-اشتراط-الكفاءة-في-النسب-عند-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1387.mp3","categories":["شروط وأركان الزواج"]},{"id":7108,"question":"رجل له بنت عمرها سنتان، وهو دائمًا مغترب، فعقد بابنته لأحد الجيران ليكون هذا الرجل محرمًا لزوجته، ويقوم هذا الرجل نيابة عن الرجل بما يلزم أثناء غياب الرجل، فهل هذا جائز؟ علمًا بأن ذلك الرجل طلق بعد العقد مباشرة؟","title":"العقد على البنت فيما دون التسع للمصلحة","answer":"الجواب:\n\nعلى كل حال الجواز يجوز، ما دام دون التسع يجوز أن يعقد عليها لمصلحة إذا رأى المصلحة الشرعية في ذلك، كما زوج الصديق ابنته عائشة على النبي ﷺ وهي بنت ست سنين، أو سبع سنين، هذا مستثنى.\n\nأما إذا بلغت تسعًا فليس له أن يزوجها إلا بإذنها، أو كانت أكبر من التسع، لا بد من إذنها، أما من دونها إذا رأى المصلحة، ما هو لأجل المال، بل لأجل المصلحة الشرعية، مثل إنسان طيب، وأحب أن يحصله، ويلزمه قبل أن يفوت، قصده الصلاح لبنته؛ هذا لا حرج فيه إذا كانت دون التسع.","link":"https://binbaz.org.sa/fatwas/3137/العقد-على-البنت-فيما-دون-التسع-للمصلحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1495.mp3","categories":["شروط وأركان الزواج"]},{"id":7130,"question":"هل يصح للرجل أن يتزوج بنت امرأة أبيه من رجل آخر قبل زواج أبيه بها، أو بعده أفتونا جزاكم الله خيرًا؟","title":"حكم زواج الرجل بربيبة أبيه","answer":"الجواب:\n\nنعم، يجوز للرجل أن يتزوج بنت زوجة أبيه من زوج غير أبيه قبله أو بعده، فللرجل أن يأخذ امرأة، ويأخذ ولده بنتها، والعكس، لا بأس بذلك. \n\nالسؤال: ربيبة أبيه يعني؟\n\nالجواب: ربيبة أبيه تحرم على أبيه، أما هو لا تحرم عليه، على الولد لا تحرم عليه.","link":"https://binbaz.org.sa/fatwas/3149/حكم-زواج-الرجل-بربيبة-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1507.mp3","categories":["شروط وأركان الزواج"]},{"id":7131,"question":"هل يصح للرجل أن يتزوج بنت امرأة أبيه من رجل آخر قبل زواج أبيه بها، أو بعده أفتونا جزاكم الله خيرًا؟","title":"حكم زواج الرجل بربيبة أبيه","answer":"الجواب:\n\nنعم، يجوز للرجل أن يتزوج بنت زوجة أبيه من زوج غير أبيه قبله أو بعده، فللرجل أن يأخذ امرأة، ويأخذ ولده بنتها، والعكس، لا بأس بذلك. \n\nالسؤال: ربيبة أبيه يعني؟\n\nالجواب: ربيبة أبيه تحرم على أبيه، أما هو لا تحرم عليه، على الولد لا تحرم عليه.","link":"https://binbaz.org.sa/fatwas/3149/حكم-زواج-الرجل-بربيبة-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1507.mp3","categories":["شروط وأركان الزواج"]},{"id":7180,"question":"والدي يريد أن يزوج إحدى أخواتي لولد صغير يبلغ من العمر ثلاثة عشرة سنة بدون رضاها، وهذا الولد غير مستقيم، وقد سبق أن زوج أختي الكبرى بدون رضاها أيضًا، وطلقت، وزوج التي بعدها بدون رضاها، وعرف المتزوج ذلك وطلقها، فهل يجوز لي أن أعارضه، وأن أرفض هذا الزوج؟","title":"حكم تزويج البكر بدون رضاها","answer":"الجواب:\n\nالواجب على والدك هداه الله أنه لا يزوج إلا بإذن، إذا كانت البنت قد بلغت تسعًا فأكثر؛ ليس له أن يزوجها إلا بالإذن.\n\nيقول النبي ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن قالوا: يا رسول الله إنها تستحي، قال: إذنها سكوتها وفي اللفظ الآخر قال: والبكر يستأذنها أبوها، وإذنها صماتها.\n\nفالواجب عليه أن يستأذنها، وإذا سكتت؛ كفى، ولا يحتاج إلى أن تقول: نعم، متى سكتت؛ كفى، أما أنه يجبرها، ويلزمها، وهي تقول: لا؛ فلا يجوز له، في الصحيح في أصح قولي العلماء، لا يجوز له، فيه من يقول: إن له الجبر، وهو قول جماعة من أهل العلم، لكنه قول مرجوح، جماعة من أهل العلم قالوا: إن الأب يجبر بنته البكر، وهذا غلط، وهو مخالف للأحاديث الصحيحة.\n\nفالصحيح: أنه لا يجبرها إذا كانت أهلًا للاستئذان، بنت تسع فأكثر، ولا يجوز له تزويجها وهي دون تسع إلا إذا كان لمصلحة يراها هو، مصلحة إسلامية دينية، كأن يخطبها كفؤ في دينه وعلمه، فيخشى أن يفوت، فيزوجها عليه قبل أن تكون أهلاً للاستئذان قبل التسع، كما تزوج النبي ﷺ عائشة على يد أبيها أبي بكر وهي بنت ست سنين، أو سبع سنين؛ لأنها هذه غنيمة لها، إذا زوجها الصديق على النبي ﷺ هذه غنيمة عظيمة، فالصديق محسن في ذلك، فهكذا أبوها الطيب الذي يريد بها الخير إذا زوجها قبل التسع برجل صالح، ذي علم، وذي دين وغبطة، فتزويجه لا بأس.\n\nأما إذا بلغت تسعًا فلا يجوز تزويجها إلا بإذنها، وهكذا بنت اثنا عشر وثلاثة عشر وأربعة عشر من باب أولى، وهكذا من فوق ذلك من باب أولى.\n\nالمقصود: أن هذا هو الصواب، وأنت أيها الابن إذا لم يطعك الوالد؛ ترفع الأمر إلى المحكمة، والمحكمة تنظر في الأمر، أما أنت فلا تقل لوالدك إلا خيرًا، عليك بالكلام الطيب، والتأدب مع والدكن والنصيحة، فإذا أبى؛ تقول: يا والدي، ارفع أمره إلى المحكمة، أنت تبرئ ذمتك، استشهد أهل العلم حتى يوجهوك بالكلام الطيب، وإذا كان ما يقبل منك تنظر الإخوان الطيبين من أخوالك، أو أعمامك، أو جيرانك الطيبين؛ حتى ينصحوه؛ حتى يتكلموا معه، ولا يجوز له ظلم هؤلاء البنات.","link":"https://binbaz.org.sa/fatwas/3223/حكم-تزويج-البكر-بدون-رضاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1567.mp3","categories":["شروط وأركان الزواج"]},{"id":7200,"question":"تقدم ابن عمي لطلب الزواج من ابنتي، وهو متزوج، وله سبعة أولاد، وعمره أربعون سنة، وزوجته أم أولاده ابنة عمي، أي أنهما هو وزوجته أبناء عمومتي، وزوجتي رافضة الموافقة على زواجه، وكذلك بنتي، علمًا بأنه رجل كفء في دينه وأخلاقه.أفتوني هل أجبر زوجتي وابنتي على الموافقة على تزويجه؟ علمًا بأن رفضهما تزويجه هو بسبب أخلاق زوجته السيئة جدًا مما يخشى منها عمل السحر، والفتن بشتى صورها، كما أني إذا لم أوافق عليه تزويجه سوف يكون هناك قطيعة رحم، أفتونا مأجورين بالتفصيل حول هذا الموضوع؟","title":"حكم إرغام البنت على الزواج ممن ترفضه","answer":"الجواب:\n\nليس لك أن تزوجها إلا بإذنها، ليس لك أن تجبر ابنتك عليه، ولو أنه من أحسن الناس، ولو ما معه زوجة، ليس لك أن تجبرها عليه، يقول النبي ﷺ: لا تنكح الأيم حتى تستأمر ولا تنكح البكر حتى تستأذن قالوا: يا رسول الله كيف إذنها؟ قال: أن تسكت. قال: والبكر يستأذنها أبوها وإذنها صماتها. \n\nفإذا قالت: نعم، أو سكتت؛ زوجها، أما بالجبر لا تجبرها، ولو زعل عليك ابن عمك، ولو قاطعك، يكون هو الآثم، هو إذا قاطعك بسبب أنك لم تزوجه ابنتك بالإكراه، يكون هو الآثم، أنت ما عليك إثم، هو الذي يعصي، معناه يريدك تجبر بنتك عليه لا، هذا ما يجوز، زوجها من ترضى به من الطيبين، سواء معه زوجات، أو ما معه زوجات، سواء كبار السن، أو صغار السن.\n\nإذا رضيت البنت، ووافقت؛ فهذا هو المقصود، وإذا هدى الله أمها، ووافقت؛ كان أفضل وأفضل، تشاور أمها، تعمل الأسباب التي تجعل أمها ترضى؛ لأنها إذا كانت أمها غير راضية قد تفسد عليكم نكاحكم، وقد تشوش عليها، وقد لا يتم النكاح بعد ذلك، لأن البنت في الغالب تتبع أمها، فلو رضيت اليوم قد لا ترضى غدًا بسبب أمها.\n\nلكن احرص ألا تزوجها حتى تكون راضية، وأمها راضية، أما رضاها هي فلا بد منه، أما رضا أمها فهو الأفضل إذا تيسر؛ حتى لا تشوش عليهم بعد الزواج، ولا قبل الزواج.","link":"https://binbaz.org.sa/fatwas/3247/حكم-ارغام-البنت-على-الزواج-ممن-ترفضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1581.mp3","categories":["شروط وأركان الزواج"]},{"id":7205,"question":"إذا رجل تملك على امرأة ولم يحضر سوى ولي أمره، وشاهد واحد عند مأذون، وهي راضية، هل تكتفى، أو باطلة؟","title":"حكم الاكتفاء بشاهد واحد عند عقد الزواج","answer":"الجواب:\n\nلا يكتفى إلا بشاهدين، لا بد من شاهدين مع الزوج، ومع الولي، يحضره أربعة في النكاح: الولي والزوج والشاهدان.","link":"https://binbaz.org.sa/fatwas/3249/حكم-الاكتفاء-بشاهد-واحد-عند-عقد-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1582.mp3","categories":["شروط وأركان الزواج"]},{"id":7206,"question":"إذا رجل تملك على امرأة ولم يحضر سوى ولي أمره، وشاهد واحد عند مأذون، وهي راضية، هل تكتفى، أو باطلة؟","title":"حكم الاكتفاء بشاهد واحد عند عقد الزواج","answer":"الجواب:\n\nلا يكتفى إلا بشاهدين، لا بد من شاهدين مع الزوج، ومع الولي، يحضره أربعة في النكاح: الولي والزوج والشاهدان.","link":"https://binbaz.org.sa/fatwas/3249/حكم-الاكتفاء-بشاهد-واحد-عند-عقد-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1582.mp3","categories":["شروط وأركان الزواج"]},{"id":7259,"question":"ما هي صفة كتابة عقود النكاح؟ وماذا يقول الذي يملكهم؟ وماذا يقرأ ونحن الشهود لم نسأل البنت هل هي موافقة أم لا، ولكن حسب كلام أبيها وضح لنا أنها موافقة؟","title":"ما يقال عند عقد النكاح وبماذا يشهد الشهود","answer":"الجواب:\n\nالسنة يقرأ المأذون، أو الولي، أو الزوج يقرأ خطبة الحاجة، هذه السنة، إن الحمد لله نحمده ونستعينه ونستغفره، ونعوذ بالله من شرور أنفسنا ومن سيئات أعمالنا، من يهده الله فلا مضل له ومن يضلل فلا هادي له، وأشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبدالله ورسوله، ثم يقرأ الآيات الثلاث المعروفة، ثم يقول للولي: قل زوجتك بنتي، أو أختي، فلانة، أو بنت أخي فلانة، ويقول الزوج: قبلت هذا النكاح. \n\nهذا هو الزواج، والشهود يسمعون حتى يشهدوا بما حصل، شاهدان، أو أكثر يشهدون على ما وقع بأن فلان ابن فلان زوج فلان ابن فلان بنته فلانة، أو أخته فلانة، والمأذون هو الذي يتولى ما يتعلق بالرضا وعدم الرضا، المأذون هو الذي يسأل الولي، أو يطلب الشهود، وإن كان عنده علم فاحتاج إلى ذلك والشهود يشهدون على الواقع، يشهدون أن المأذون الفلاني، أو القاضي الفلاني، أو الشخص الفلاني جرى عنده كذا، زوج فلانًا فلانة بحضور وليها فلان أو الزوج فلان، ويكفي هذا.\n\nالسؤال: يعني ما يذهبون لأخذ موافقتها؟\n\nالجواب: لا، هذا إلى المأذون، هو الذي يتولى هذه الأمور، أو القاضي.","link":"https://binbaz.org.sa/fatwas/3328/ما-يقال-عند-عقد-النكاح-وبماذا-يشهد-الشهود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1649.mp3","categories":["شروط وأركان الزواج"]},{"id":7269,"question":"ما هي صفة كتابة عقود النكاح؟ وماذا يقول الذي يملكهم؟ وماذا يقرأ ونحن الشهود لم نسأل البنت هل هي موافقة أم لا، ولكن حسب كلام أبيها وضح لنا أنها موافقة؟","title":"ما يقال عند عقد النكاح وبماذا يشهد الشهود","answer":"الجواب:\n\nالسنة يقرأ المأذون، أو الولي، أو الزوج يقرأ خطبة الحاجة، هذه السنة، إن الحمد لله نحمده ونستعينه ونستغفره، ونعوذ بالله من شرور أنفسنا ومن سيئات أعمالنا، من يهده الله فلا مضل له ومن يضلل فلا هادي له، وأشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبدالله ورسوله، ثم يقرأ الآيات الثلاث المعروفة، ثم يقول للولي: قل زوجتك بنتي، أو أختي، فلانة، أو بنت أخي فلانة، ويقول الزوج: قبلت هذا النكاح. \n\nهذا هو الزواج، والشهود يسمعون حتى يشهدوا بما حصل، شاهدان، أو أكثر يشهدون على ما وقع بأن فلان ابن فلان زوج فلان ابن فلان بنته فلانة، أو أخته فلانة، والمأذون هو الذي يتولى ما يتعلق بالرضا وعدم الرضا، المأذون هو الذي يسأل الولي، أو يطلب الشهود، وإن كان عنده علم فاحتاج إلى ذلك والشهود يشهدون على الواقع، يشهدون أن المأذون الفلاني، أو القاضي الفلاني، أو الشخص الفلاني جرى عنده كذا، زوج فلانًا فلانة بحضور وليها فلان أو الزوج فلان، ويكفي هذا.\n\nالسؤال: يعني ما يذهبون لأخذ موافقتها؟\n\nالجواب: لا، هذا إلى المأذون، هو الذي يتولى هذه الأمور، أو القاضي.","link":"https://binbaz.org.sa/fatwas/3328/ما-يقال-عند-عقد-النكاح-وبماذا-يشهد-الشهود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1649.mp3","categories":["شروط وأركان الزواج"]},{"id":7470,"question":"هذه رسالة أو ثلاث رسائل، وقد وافق أيضاً السائل (ع. ت. س) مع الأخوين محمد عقلان من الرياض وعبده علي من الخبر، تقول الرسالة: هناك امرأة طلبت من رئيس كتابة العدل أن يسجل لها وكالة لأخيها من أبيها ليتولى عقد زواج لها على الزوج الذي ترضاه مع أنها تركت أبناءها وهم الأقربون للولاية، وليس فيهم نقص، ومن بعدهم أخ شقيق، وفعلاً أخرج صك من كتابة العدل حسب رغبتها، ثم اتصلت هي والوكيل والزوج بإمام مسجد وليس موظفاً وظيفة رسمية، فتم العقد والزواج بهذه الصفة، فما رأيكم فيمن كتب هذه الوكالة ومن عمل بها، وأيضاً من وقوع الزواج، أفتونا مشكورين جزاكم الله خيراً؟","title":"وجوب تولي الأقرب فالأقرب نكاح المرأة","answer":"الجواب: أولاً: الواجب أن يتولى النكاح الأقرب فالأقرب، هذا هو الأرجح من أقوال العلماء، يتولاه الأقرب فالأقرب، فالأقرب: الأب، ثم يليه الجد، ثم الأبناء، ثم الإخوة الأشقاء، ثم الإخوة لأب، ثم من دونهم، كابن الأخ الشقيق وابن الأخ لأب، والعم الشقيق، والعم لأب، كالمواريث، هذا هو الأرجح؛ لأن هذه قرابة يترتب عليها حنو على المرأة وحرصاً على ما ينفعها، فكان الأقرب فالأقرب أولى؛ ولأن الرسول ﷺ قال: لا نكاح إلا بولي كل ما كان الولي أقرب صار أكثر عناية بها وحرصاً على مصلحتها، فلا ينبغي لها ولا لغيرها أن يعمل خلاف ذلك، فلا تُكتب الوكالة باسم الأبعد ويترك الأقرب، مثل هذه التي كتبت الولاية لأخيها وموجود لها أبناء، والأبناء مقدمون على الراجح على الإخوة.\nولكن إذا تم العقد بذلك.. فينبغي أن يُجدّد العقد بالولي الأقرب حتى يخرج من خلاف العلماء، بعض أهل العلم يرى أن جميع الأقارب العصبة يكفون سواء كان أخ أو ابن أو عم، ولكن الأولى والذي ينبغي هو تقديم الأقرب فالأقرب، فالذي عقد لها أخوها لأبيها مع وجود أبنائها ينبغي أن يجدد عقدها بنفس ابنها أو وكيل ابنها، إلا إذا كان ابنها قد وافق على توكيل الأخ لأب فلا بأس، إذا وافق الأقرب على توكيل الأبعد فلا حرج، إذا قال الأقرب: نوكل الأبعد، فإن وكل ابنها أخاها فلا بأس، أما إذا كان بغير إذنهم وبغير موافقتهم فلا، فلابد أن يكون الأقرب هو الذي يتولى عقد النكاح، وإذا تم العقد بولاية غير الأقرب فينبغي أن يجدد بولاية الأقرب خروجاً من خلاف العلماء واحتياطاً للفروج؛ لأن الفروج أمرها عظيم، الفروج لها شأن، فينبغي أن يحتاط لها في كل شيء، ومن ذلك: أن يكون العقد من الأقرب لا من الأبعد، إذا تولاه الأبعد ينبغي أن يجدد من الأقرب حتى تكون المرأة حلاً للزوج ليس فيه شبهة. نعم.","link":"https://binbaz.org.sa/fatwas/4202/وجوب-تولي-الاقرب-فالاقرب-نكاح-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_002/00207.mp3","categories":["شروط وأركان الزواج"]},{"id":7471,"question":"هناك رجل عنده أربع بنات، الكبرى عمرها خمس وثلاثون سنة والصغرى عشرون سنة وقد طلبن للزواج وأبى وليهن أن يزوجهن، وهو أيضًا إمام جامع، هل يجوز أن يصلي بنا وهو على هذه الحالة؟","title":"حكم منع الولي تزويج النساء وحكم الصلاة خلفه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلاشك أن الواجب على ولي البنات والأخوات ونحوهن أن يتقي الله ، وأن يحرص على تزويجهن بالكفء إذا حصل، وألا يعضلهن لحظ من الحظوظ؛ كالرغبة في خدمتهن، أو موتهن؛ لأن لهن مالاً حتى لا يشاركه أحد في المال، أو ما أشبه ذلك من المقاصد الخبيثة، بل الواجب على الولي أن يبادر بتزويج المرأة إذا خطبها الكفء؛ لأنه روي عن النبي ﷺ أنه قال: إذا خطب إليكم من ترضون دينه وأمانته فزوجوه، إلا تفعلوه تكن فتنة في الأرض وفساد كبير أو كما قال عليه الصلاة والسلام. والحاصل: أن الأمانة يجب أن يعتنى بها، والبنت والأخت ونحوهما أمانة عند الولي، فالواجب عليه أن لا يضر هذه الأمانة، وأن لا يسيء إليها، بل يجب عليه أن يحسن إليها وأن يزوجها على الكفء من دون تعطيل ولا عضل ولا إيذاء. وهذا الرجل الذي سئل عنه عنده أربع بنات؛ الكبرى منهن تبلغ خمس وثلاثين سنة، هذا لاشك أنه قد غلط غلطاً كبيراً إذا تأخر في تزويجهن من دون عذر شرعي، والواجب عليه أن يبادر بالتزويج إذا جاء الكفء وألا يتأخر، فيجب أن ينصح وأن يوجه إلى الخير، ويجب على من يعرفه من جيرانه وأقاربه وأهل بلده أن ينصحوه وأن يحذروه من مغبة هذا الأمر، وكذلك ينبغي أن يبلغ الحاكم، حاكم البلد، القاضي حتى يحضره، وحتى يعظه ويذكره ويحذره من مغبة هذا العمل، والدين النصيحة، والمسلم أخو المسلم ينصحه ولا يهمله، هكذا يجب على المسلمين فيما بينهم إذا رأوا مثل هذا أن ينصحوه وألا يهملوه؛ لأن هذا يضر المجتمع، وربما أفضى بالبنات إلى ما لا تحمد عقباه. أما الصلاة خلفه فالصلاة خلفه صحيحة على الراجح؛ لأن الراجح أن الصلاة خلف الفاسق صحيحة، وإنما تبطل إذا كان الإمام كافراً، أما إذا كان مسلم لكنه عاصي، مثل هذا، أو مثل إنسان عنده معاصي معروفة أخرى؛ .. كشرب المسكر في بعض الأحيان، أو كالتدخين، أو كحلق اللحى، مثل هذه المعاصي كلها لا تمنع من الإمامة؛ لكن ينبغي أن يلتمس الإمام الأفضل، وينبغي أن يعزل إذا كان مصراً على العمل ينبغي أن يعزل ويؤتى بمن هو أسلم منه، لكن لو صلى خلفه صحت الصلاة، ولكنها خلف السليم أفضل وأولى. ومثل هذا وأشباهه ما ينبغي أن يقر بل ينبغي أن ينصح، فإن استقام وإلا يعزل عن الإمامة، يعني معصية كبيرة وظلم فلا ينبغي أن يترك على هذه المعصية، بل ينبغي أن يعزل عن عمله هذا تأديباً له، ورعاية لحال المأمومين حتى لا يتولى إمامتهم إلا من هو معروف بالاستقامة والديانة والبعد عن المعاصي. وبكل حال: ينبغي أن يحذر هذا من هذا العمل السيئ، وأن يؤمر بتزويج بناته إذا خطبهن الأكفاء، وليس له أن يتأخر في ذلك أبداً. نعم.   المقدم: أيضاً يقول: ما هو المخرج لهؤلاء الفتيات اللاتي وقعن في هذا المأزق الحرج؟ الشيخ: لهن مخارج، منها: أن يتكلمن مع والدهن بالكلام الطيب والأسلوب الحسن ويقلن: ما يخفى عليك أن الزواج فيه مصالح كثيرة، والبنت بدون زواج على خطر تريد العفة وتريد الأولاد، فنرجو من والدنا أن لا يتأخر عن الكفء إذا خطب، بالأسلوب الحسن لعله يلين، ولعله ينفع فيه الكلام. فإن لم يستطعن ذلك أو فعلنه ولم يجد يستعن أيضاً بمن يرين فيه الخير من الأقارب، كأعمامه وأقاربه الذين يقدرهم ويحترمهم لعلهم يشفعون ولعلهم ينصحونه. فإن لم يتيسر لهن من يقوم بذلك ولم يجد فيه مثل هذا، فلا مانع من رفع الشكوى إلى المحكمة، إلى القاضي، أو إلى ولي الأمر من الأمير، ولي أمر البلاد، أمير، أو قاضي، حتى يحصل التعاون على إزالة هذا الشر. لكن البداءة بالأسلوب الحسن أولى، البداءة بالكلام معه منهن بالأسلوب الحسن قد يكون هذا أقرب إلى عطفه عليهن وإلى تركه هذا الظلم، وإذا لم يتيسر هذا لأنهن يخشينه، يخشين شره وضربه لهن، أو لأنه لم يمتثل فإنهن يطلبن من الأقارب الجيدين يعني من الكبار الذين يقدرهم ويحترمهم أن يتوسطوا وأن يشفعوا إليه حتى يدع هذا الظلم، فإن لم يجد هذا ولا هذا أو لم يتيسر هذا ولا هذا، فلا مانع من الشكوى إلى القاضي أو إلى الأمير أو إليهما جميعاً لحل هذا المشكل. نعم.","link":"https://binbaz.org.sa/fatwas/4226/حكم-منع-الولي-تزويج-النساء-وحكم-الصلاة-خلفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_003/00301.mp3","categories":["شروط وأركان الزواج"]},{"id":7491,"question":"هذه أيضاً رسالة يا سماحة الشيخ موجهة لكم شخصياً، المرسلة من المهد عويدة عايد المطيري تقول: فضيلة الشيخ عبد العزيز بن عبد الله بن باز ! أرجو من فضيلتكم إفادتنا في الموضوع الآتي: أفيدكم أن ابنتي ومحيلها -أخوها- قال.. رسالة طويلة في الحقيقة وملخصها: تعرض حالتها مع ابنتها وأخ ابنتها، سواء كان هذا الأخ لابنتها من رجل غير زوجها، تقول: إن هذا الأخ أراد تزويج أخته من رجل لم ترض به، وأن هذه الأم تبعت خاطره، أي: تريد إرضاء أخو البنت، فزوجت ابنتها من رجل لم ترض به، هل على الأم ذنب في ذلك؟","title":"حكم إجبار المرأة على الزواج","answer":"الجواب: هذا السؤال فيه تفصيل: إن كانت البنت لم ترض فإنه لا يجوز تزويجها مطلقاً..\nالمقدم: هي تقول: إن البنت لم ترض.\nالشيخ: لا يزوجها لا أبوها ولا غيره، ولا أمها ولا أخوها ولا غيرهم، النبي صلى الله عليه وسلم نهى عن تزويج النساء إلا بإذنهن، وقال: لا تزوجوا البكر حتى تستأذن، ولا تزوجوا الأيم حتى تستأمر، قالوا: يا رسول الله! في البكر إنها تستحي، قال: إذنها سكوتها.\nفالحاصل: أن المرأة لا تزوج إلا بإذنها، فكون أمها أو أخيها يجبرانها على الزواج لا يجوز لهما ذلك، كما أنه لا يجوز لأبيها إجبارها على الصحيح أيضاً، إذا كانت بكراً مكلفة أو بنت تسع على الأقل، إذا كانت بنت تسع فأكثر فإنها لابد أن تستشار، فإن أذنت وإلا لم تزوج، وإذنها يكفي فيه السكوت، لأبيها وغير أبيها، لأبيها ولغير أبيها من باب أولى، فأخوها هذا إن كان لأمها فليس ولياً لها، إن كان أخاً من الأم فليس ولياً لها، وإنما أولياؤها العصبة؛ إخوتها الأشقاء، وإخوتها من الأب، هؤلاء هم أولياؤها، أما إن كان أخاً لها من أبيها أو من أبيها وأمها فهو عصبة، لكن ليس له أن يزوجها إلا بإذنها، تزويجها بغير إذنها يكون فاسداً ليس بصحيح، فلابد من أخذ إذنها في الزواج مطلقاً، لكن إذنها صماتها إذا كانت بكراً، أما الثيب التي قد تزوجت فلابد من تصريحها بالإذن، لابد أن تنطق بالإذن. نعم.","link":"https://binbaz.org.sa/fatwas/4452/حكم-اجبار-المراة-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_006/00602.mp3","categories":["شروط وأركان الزواج"]},{"id":7542,"question":"في الحقيقة لدي يا سماحة الشيخ كثير من الأسئلة عن الحج، ولكن هذه رسالة وجدتها ضمن الرسائل من السائل (س. م. ش)، يقول: هل يجوز للرجل أن يجبر ابنته البكر على الزواج، وكذلك الثيب؟","title":"إجبار الولي البكر والثيب على الزواج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فليس للرجل أن يجبر ابنته البكر أو الثيب على الزواج، وكثير من الناس يقع منه التساهل في هذا الأمر، ولا سيما مع الأبكار، فيقع بذلك نزاع كثير بين الزوجين، وفساد عظيم، ودعاوى وخصومات كثيرة، كل هذا بأسباب مخالفة الحق وعدم القيام بما يجب من الاستئذان، وقد صرح النبي ﷺ في الحديث الصحيح بالنهي عن ذلك، ففي الصحيحين عن النبي ﷺ أنه قال: لا تنكح البكر حتى تستأذن، ولا تنكح الثيب حتى تستأمر، قالوا: يا رسول الله! إن البكر تستحي فكيف إذنها؟ قال: أن تسكت فالبكر إذنها سكوتها، فلا يجوز لإنسان أن يجبر ابنته الثيب ولا البكر، بل يجب أن يستأذنهما، ويشاورهما في أنفسهما، فالزواج ليس بالشيء السهل، بل هو شيء عظيم، فهو شريكها والذي يجتمع معها، ويسكن إليها وتسكن إليه، فالأمر في شأنهما ذو أهمية، فليس للأب أن يجبر ابنته على الزواج، سواء كانت بكراً أو ثيباً، بل لابد أن يشاورها، ويأخذ رأيها في ذلك، ويبين لها الزوج وحاله وأنه كذا وكذا، وأنه ابن فلان وفلان، وأن صفته كذا، وعمله كذا، يوضح لها الأمر، فإن أجابت ووافقت فالحمد لله ولو بالسكوت إذا كانت بكراً، يكفي السكوت، أما الثيب فلابد من النطق، لابد أن تقول: نعم أو نحوه مما يدل على رضاها، وأما البكر فلأنه قد يغلب عليها الحياء قد تستحي، فلا بأس أن يكتفى بالسكوت، إذا سكتت أو بكت كفى، هذا هو الواجب، ولا يجوز أبداً إجبارها على الزواج من دون إذنها، وإن كان بعض أهل العلم قد قال ذلك، واستحسن أن يزوج ابنته البكر من غير إذنها؛ لأنها لا تعرف مصلحتها على التمام، ولكن هذا قول مصادم للسنة، ومخالف لها، فلا ينبغي أن يعول عليه، فالله يقول جل وعلا: وَأَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [المائدة:92]، ويقول سبحانه: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ [النور:63]، ويقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59] فلا يجوز للمؤمن أن يخالف أمر الله وأمر رسوله عليه الصلاة والسلام لقول أحد من الناس كائناً من كان.\nهذا هو الواجب على الآباء، أما بقية الأولياء فمن باب أولى؛ الأخ، والابن، والعم، من باب أولى، ليس لهم تزويج أي امرأة إلا بإذنها، سواء كانت بكراً أو ثيباً، وإنما الخلاف في الأب هل يزوج بغير إذن -يعني: البكر- وهكذا الجد؟\nالجواب: نعم، ليس له أن يزوج إلا بإذن، ليس للأب ولا للجد أن يزوج البنت البكر إلا بإذنها، وإذا أبت فليس له إجبارها، سواء كان أباها وهو أقرب الناس إليها، أو كان جدها، من باب أولى.\nوهكذا الإخوة والأبناء ليس للابن أن يجبر أمه على الزواج، ولا الأخ أن يجبر أخته على الزواج، لا، كل هذا لا يجوز.\nفالواجب على المسلمين اتباع السنة وتعظيمها، والحذر من مخالفة السنة في تزويج الأبكار بغير إذنهن، فإن فساده كبير، وخطره عظيم، وعواقبه وخيمة في الغالب، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/4528/اجبار-الولي-البكر-والثيب-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_012/01201.mp3","categories":["شروط وأركان الزواج"]},{"id":7543,"question":"ما دمنا تحدثنا عن الولي للزواج، هذه رسالة من المرسل (ص. ع) العقل من الرياض، يقول: ما هو السن المعتبر لكي يكون الشخص ولي المرأة ويجوز له أن يزوجها؟","title":"السن المعتبرة في ولي المرأة","answer":"الجواب: هو البلوغ، إذا بلغ وكان رشيداً يعرف يعني يقيم الرجال، ويعرف الأكفأ من غير الأكفأ، هذا السن، إذا كان يعني قد بلغ الحلم بأن أكمل خمسة عشر سنة، أو احتلم، بإنزال المني بالاحتلام أو باليقظة، أو أنبت الشعر الخشن حول الفرج، يعني: الشعرة، بهذا يكون مكلفاً مع التمييز، كونه يعني: يميز الرجال يعرف، عنده رشد، يعرف مقامات الرجال، ومنازل الرجال، هذا يسمى: ولي، وله التزويج، أما إذا كان دون البلوغ، أو كان ضعيف البصيرة ما يحسن ، ما عنده رشد، فيزوج غيره، نعم، يزوج من هو أولى منه ومتصف بالصفات التي تنبغي في الولي، وإن كان أبعد منه.\nفإذا كان أخوها بهذه الصفة، يعني: ما بلغ الحلم، أو بلغ لكن ما عنده بصيرة، ما عنده رشد، فإنه يزوجها عمها إن كان لها عم بعد أخيها، إذا كان هو أقرب الناس إليها بعد الأخ، أو ابن أخيها إن كان لها ابن وهو رشيد جيد، تكون الولاية له دون أبيه الذي ليس بمرشد لضعف عقله.\nفالحاصل أنه يزوجها وليها الرشيد الذي يعرف الرجال، الرشد هنا يعني معرفة الأكفاء. نعم.","link":"https://binbaz.org.sa/fatwas/4529/السن-المعتبرة-في-ولي-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_012/01202.mp3","categories":["شروط وأركان الزواج"]},{"id":7705,"question":"سؤالها الأخير تقول فيه: والدي يريد أن يزوجني رجلاً لا أريده، ويقول لي: يجب ألا تخالفي أوامري، فهل لأبي تعاستي على رضا وسعادة الآخرين؟ أفيدوني وأرشدوني جزاكم الله عنا خيراً، وشكر الله لكم.","title":"حكم إرغام الأب ابنته على الزواج","answer":"الجواب: ليس للأب ولا غيره من الأولياء إجبار المرأة على الزواج، ليس له ذلك، لا الأب ولا غيره؛ لأن النبي صلى الله عليه وسلم نهى عن تزويج المرأة إلا بإذنها قال: والبكر يستأذنها أبوها، وإذنها سكوتها فليس للأب ولا غيره أن يجبر المرأة على النكاح، بل الواجب أنه يشاورها، فإن رضيت زوجها وإلا تركها، أما الإجبار فلا يجوز لا للبكر ولا للثيب، الواجب أن تشاور، فإن قبلت ورضيت فالحمد لله، وهذا لها، ومصلحتها ليس للأب ولا لغير الأب، هذا لها هي، وإن أبت وقالت: لا أريد هذا الرجل، لا تجبر، ولا يجوز لأبيها إجبارها أبداً، هذا منكر، وقد ثبت عنه ﷺ أنه نهى عن ذلك، وجاءته جارية تذكر له أن أباها زوجها وهي كارهة، فخيرها النبي ﷺ، إن شاءت بقيت وإن شاءت فسخت. \nفالحاصل: أنه لا يجوز للأب ولا غيره من الأولياء إجبار النساء على النكاح، بل الواجب تخييرهن سواء كن أبكاراً أو ثيبات، فإن رضين زوجهن وإلا ترك ذلك، عملاً بأمر النبي ﷺ، وحذراً من نهيه عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/4904/حكم-ارغام-الاب-ابنته-على-الزواج ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_029/02907.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":7750,"question":"سماحة الشيخ! لدينا مجموعة كبيرة من الأسئلة ونأخذ منها حسب ترتيب الوصول رسالة أمة الله نبيلة بنت عبد العزيز ورسالة المستمع أو المرسل (م. م. م) من الرس. تقول أمة الله نبيلة بنت عبد العزيز السلام عليكم ورحمة الله وبركاته وبعد:أكتب إليكم هذه الرسالة؛ لعل الله يقدر لنا خيراً وأجد عندكم الفتوى التي تشفي وتقطع الشبه في هذا الأمر:تقدم لي شاب علمت أنه يتقي الله كثيراً -ولا نزكي على الله أحداً- ولما تقدم للوالد رفضه الوالد لأسباب دنيوية هي أنه لا يستطيع أن يباهي به أمام الناس؛ لأن مظهره لا يعجب أناس هذا الزمان، لأنه يلبس القميص ولا يطيل ثيابه تأسياً بالرسول ﷺ، هذا بجانب أنه لم يعجبه أسلوب عيشته، وهي -ولله الحمد- اعتبار الدنيا معبر إلى دار القرار، المهم أنه رفضه لدينه هداه الله سواء السبيل.ولما كنت قد علمت بدين هذا الأخ وأعلم أن رفض إنسان بهذه الصفات هي فتنة في الأرض وفساد كبير، فهل إذا تكاسلت عن إسقاط الولاية عن الوالد والتقدم للقاضي أو لعالم يتصف بالتقوى ليتولى أمر تزويجي؛ هل في ذلك شيء علي أم لا؟ وفقكم الله.","title":"حكم مطالبة المرأة بنقل ولاية أبيها العاضل إلى القاضي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله والصلاة السلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nلا ريب أن على الوالد وعلى سائر الأولياء أن يعتنوا بأماناتهم، وهن مولياته من النساء من بنات وأخوات، وأن يحرصوا على تزويجهن وعدم تعطيلهن وعضلهن، وأن ينظروا إلى الأزواج من جهة الدين والاستقامة والأمانة وصلاح الحال، لا من جهة الدنيا والمظاهر؛ فإن هذا المظهر قد يضر صاحبه، قد يضر مصاهريه، فالواجب على ولي المرأة أن ينظر إلى الدين والاستقامة، فإذا كان الرسول ﷺقال في المرأة: فاظفر بذات الدين تربت يداك، فهكذا ينبغي أن يقال من جهة الزوج، يقال للأولياء: فاظفروا بأصحاب الدين في تزويج بناتكم وأخواتكم ونحو ذلك.\nفيجب العناية بذات الدين من النساء، وهكذا العناية بصاحب الدين من الرجال، فكونه لا يطيل ثيابه هذه منقبة، هذه منقبة وفضل ينبغي أن يكون سبباً لتقريبه لا لإبعاده؛ لأن الرسول ﷺ نهى عن الإسبال وقال: ما أسفل من الكعبين من الإزار فهو في النار فلا يجوز للرجال أن يسبلوا ثيابهم تحت الكعب مطلقاً وإذا كان عن كبر صار أعظم وأكبر، كذلك كونه مثلاً يلبس القميص العادي المعروف أو كون راتبه ليس بالكثير أو كان لا يحلق لحيته بل يوفرها ويعتني بها، كل هذه مناقب ومكارم وفضائل لا ينبغي أن تكون سبباً لمنع الزواج والذي يعتبرها سبباً هذا يدل على نقص في دينه ونقص في إيمانه ونقص في تصوره ونقص في أدائه الأمانة.\nوهكذا كون معيشته ليست بالكاملة من جهة الرفاهية ومن جهة ما يحتاجه الناس اليوم من مزيد التفكه، هذا ليس بعيب، فينبغي للمؤمن أن يعتني بالدين والاستقامة، ولا يكون تعلقه بالمال أو بالمظاهر هو المطلوب بل هذا غلط ولا يجوز للوالد ولا لغير الوالد من الأولياء، أما المرأة فإن تقدمت للحاكم لطلب عزل الولي الذي يتساهل حتى يزوجها الحاكم فلا بأس لها حق في ذلك أن تتقدم للمحاكم وتطلب أن تزوج بهذا الخاطب الجيد وأن يمنع وليها من التحكم فيها لهواه ولمقاصد منحرفة أو لقصد المباهاة بالأزواج والأموال كل هذه مقاصد رديئة وصاحبها يستحق أن يعزل ويعتبر عاضلاً لامرأته ، وإن صبرت ولم تتقدم إلى المحاكم وقالت: لعل ولعل إكراماً لأبيها وإكراماً لوليها وحذراً من أشياء قد تسوء عاقبتها فلا بأس، على كل حال هذا إلى المرأة هي المخيرة إن شاءت تقدمت إلى المحاكم ليزوجوها من الخاطب الجيد من المستحق، وإن شاءت صبرت حتى يفتح الله، ولعل الله يهدي الولي فيزوج هذا أو غيره. نعم.","link":"https://binbaz.org.sa/fatwas/4949/حكم-مطالبة-المراة-بنقل-ولاية-ابيها-العاضل-الى-القاضي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_043/04301.mp3","categories":["شروط وأركان الزواج"]},{"id":7766,"question":"أيضاً يقول: إذا تزوج والدي امرأةً ثم طلقها وأنجبت بنات من غيره، هل لي أن أتزوج منهن؟هذه رسالة مشابهة للأولى، هذه وردت من الخرج؟","title":"حكم الزواج من بنات زوجة الأب من رجل آخر","answer":"الجواب: تقدم، لا بأس ، لا حرج في ذلك، لا حرج على الإنسان أن يتزوج من بنات زوجة أبيه المطلقة والتي مات عنها أبوه؛ إذا كان ما هناك رضاعة ولا قرابة تحرمها عليه. نعم.","link":"https://binbaz.org.sa/fatwas/4966/حكم-الزواج-من-بنات-زوجة-الاب-من-رجل-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_045/04502.mp3","categories":["شروط وأركان الزواج"]},{"id":7767,"question":"أيضاً يقول سلمان محمد السلمي من الخرج: هل يجوز أن يتزوج خالي زوجتي إذا طلقتها؟","title":"هل يجوز أن يتزوج خالي زوجتي إذا طلقتها؟","answer":"الجواب: كما يتزوج أخوك زوجتك إذا طلقتها أو مت عنها، كذلك خالك من باب أولى، الخال أبعد من الأخ، فزوجة الخال وزوجة ابن الأخت وابن الأخ كلها حلال، فإذا مات الإنسان جاز لخاله ولعمه ولأخيه أن يتزوج زوجته، وهكذا إذا طلقها واعتدت، جاز لخاله وعمه وأخيه أن يتزوجها إذا لم يكن هناك بينه وبينها ما يحرم من رضاع أو غيره.","link":"https://binbaz.org.sa/fatwas/4968/هل-يجوز-ان-يتزوج-خالي-زوجتي-اذا-طلقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_045/04503.mp3","categories":["شروط وأركان الزواج"]},{"id":7771,"question":"هذه رسالة يقول مرسلها من حائل (م. ق. س): تزوج أبي امرأة ثم فارقها، وأخذها شخص آخر فأنجبت منه بنتاً، فهل تصلح لي أن أتزوجها؟ وفقكم الله.","title":"حكم الزواج من ابنة زوجة الأب من رجل آخر","answer":"الجواب: نعم، بنت زوجة أبيه لا حرج فيها، إذا كان ما في رضاع يحرمها، إذا كان زوجة أبيه ليس بينه وبينها رضاع، ومجرد كونها زوجة أبيه لا يحرم بنتها عليه، لو كان معها بنت من قديم -قبل أبيه- من زوج سابق وتزوجها هو وأبوه تزوج الأم لا بأس، وهكذا البنت الجديدة من زوج جديد له أن يتزوجها. نعم.","link":"https://binbaz.org.sa/fatwas/4983/حكم-الزواج-من-ابنة-زوجة-الاب-من-رجل-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_046/04606.mp3","categories":["شروط وأركان الزواج"]},{"id":7793,"question":"المقدم: هذه رسالة وردتنا من المرسل سعود عبد الله، العنوان: الخفجي شركة الزيت العربية، يقول: السلام عليكم ورحمة الله وبركاته وبعد: أرجو من أخي مقدم البرنامج أن يعرض سؤالي هذا على فضيلة الشيخ عبد العزيز بن باز، والجواب في غاية الأهمية أرجو أن تكون سريعاً في الرد عليه، يقول في سؤاله: إن لأبي امرأة وله منها أولاد.الشيخ: إن ..المقدم: إن لأبي امرأة وله منها أولاد، ولزوجته هذه أخت، فهل يجوز أن أتزوج أخت زوجة أبي، علماً أن إخواني من زوجة أبي ينادونها يا خالة، وطبعاً هي محرمة عليهم؛ لأنها خالتهم أخت أمهم، فهل تحرم عليَّ؛ لأني أخوهم؟ وهل يصبح تقديرها بالنسبة لي يعادل تقدير الخالة الأصلية أم لا؟","title":"حكم زواج الرجل من أخت زوجة أبيه أو بنتها","answer":"الجواب: لا بالنسبة لك، السائل لا، ليست خالة لك، لك أيها السائل أن تتزوج هذه المرأة التي هي خالة أخوتك من أمك لا بأس، أنت أجنبي منها وهي أجنبية منك، فلك أن تتزوجها وإن كانت خالة إخوتك من أمك، بل لك أن تتزوج أخت أخوتك من أمك، لو كان لزوجة أبيك ابنة من زوج سابق فإن لك أن تتزوجها وليس لإخوتك أن يتزوجوها؛ لأنها أختهم، أما أنت فأجنبي فلك أن تنكح بنت زوجة أبيك ولك أن تنكح أختها؛ لأنك أجنبي منها، أما إخوتك فلا، إخوتك بنت أمهم أختهم وإن كانت من غير أبيهم، وأختها خالتهم فلا ينكحونها وليس لهم ذلك، ولكن أنت أجنبي من البنت ومن الأخت، فزوجة أبيك حرمت عليك؛ لأنها زوجة أبيك، أما بنتها من غير أبيك من زوج سابق فلك أن تنكحها إذا لم يكن بينك وبينها رضاعة، وهكذا أخواتها لك أن تنكح إحدى أخواتها؛ لأنك أجنبي منها إن لم يكن بينكما رضاعة، أما إخوتك فلا؛ لأنها خالتهم، والله سبحانه وتعالى أعلم.\nالمقدم: شكراً لسماحة الشيخ!","link":"https://binbaz.org.sa/fatwas/5141/حكم-زواج-الرجل-من-اخت-زوجة-ابيه-او-بنتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_049/04905.mp3","categories":["شروط وأركان الزواج"]},{"id":7868,"question":"هذه الرسالة وردتنا من جيزان يقول أخوكم جابر صالح النوراي أو النوراني: أنا جابر صالح نوراي أتقدم إليكم طالب حل مشكلتي من سماحة الشيخ عبد العزيز حيث تتعلق بالرضاعة، يقول: لي بنت عم أريد أن أتجوزها ولكن والدتي أخبرتني أنها قد أرضعت أختاً لها قد ماتت، وأنا أريد أن أتجوز البنت التي لم ترضعها أمي فهل تجوز لي أم لا؟ أفيدوني جزاكم الله خيراً في الدنيا والآخرة؟","title":"حكم الزواج من أخت الأخت من الرضاع","answer":"الجواب: نعم، لا حرج عليك في زواج البنت الموجودة؛ لأن الرضاعة تتعلق بالميتة والميتة ذهبت، ورضاعها لا يسري على أختها، فالذي أرضعتها أمك توفيت وهذه لم ترضعها أمك، وأنت لم ترضع من أمها ولا من أخواتها حتى تكون خالة لك، مادام ما بينك وبينها رضاع فلا حرج في زواجها. نعم.","link":"https://binbaz.org.sa/fatwas/5325/حكم-الزواج-من-اخت-الاخت-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05612.mp3","categories":["شروط وأركان الزواج","الرضاع"]},{"id":7900,"question":"هذه رسالة وافتنا من عبادي الهباش من جدة الجامعة، يقول فيها: محمد سافر إلى الخارج لعدة شهور، وخوفاً من الوقوع في الحرام تزوج بامرأة وفي نيته تطليقها إذا أراد العودة إلى بلده، ما هو الحكم في ذلك، وما هو الحكم إذا لم تكن لديه نية مسبقة بطلاقها وأنجبت له طفل أو طفلة ثم طلقها؟","title":"حكم الزواج بنية جازمة للطلاق","answer":"الجواب: إذا نوى المسافر بزواجه أنه يطلق إذا عزم على الرحيل، هذا فيه اختلاف بين أهل العلم، من أهل العلم من ألحق هذا بالمتعة بنكاح المتعة، ومنهم من قال: لا يلحق بنكاح المتعة وليس منها في شيء؛ لأنه قد ينوي ولا يعزم، ليس بشرط، بخلاف المتعة فإنها مشارطة أنه يطلقها بعد شهر بعد شهرين يفارقها، أما هذا فليس بينه وبينهم مشارطة، إنما في قلبه ونيته أنه إذا أراد الرحيل مثلاً من أمريكا من لندن من كذا من كذا من المغرب من الجزائر طلق، وقد يفسخ هذه النية ويرغب فيها ويرتحل بها.\nفالأقرب والله أعلم أن هذا لا يكون من المتعة، قد يكون جائزاً ولكن الأولى ألا ينوي هذه النية، عليه أن يتزوج ناوياً إن ناسبته ارتحل بها وإلا طلقها.\nأما ينوي نية جازمة أنه يطلقها فالأولى ترك ذلك، خروجاً من خلاف العلماء، هذا هو الأولى، لكن لا يبطل النكاح ولا يكون متعة بهذه النية، هذا هو الصواب، إنما يكون نكاحاً ناقصاً؛ لأن في هذه النية والذي ينبغي أن يكون عليه الرغبة مطلقة، فإذا نوى أنه إذا أراد الرحيل طلق، فالصحيح أنه لا يبطل نكاحه لكنه ترك الذي ينبغي وهو أن ينوي نية مطلقة في الرغبة، إن ناسبته أبقاها وإلا طلقها، هذا هو الذي ينبغي للمؤمن.\nوأما إذا وقع الواقع ونكح مسلمة أو كتابية -يعني- محصنة بعيدة عن الفواحش، فإن الله إنما أباح لنا الكتابيات المحصنات، فإذا نكح كتابية محصنة جاز ذلك، والأولى البعد عن ذلك وترك ذلك؛ لأنها قد تجر عليه بلاء وقد تنجب له أولاداً وتنصرهم؛ فينبغي له الحذر من ذلك، وألا يتزوج إلا مسلمة.\nهذا هو الذي ينبغي حرصاً على سلامة دين أولاده بل على سلامته هو، فقد تجره إلى دينها وتنصره هي، فينبغي له الحذر، وقد يسلم هو ولكن لا تسلم ذريته؛ فينبغي له الحذر وألا يتزوج إلا مسلمة معروفة بالخير من بيئة صالحة؛ لأن هذا هو الذي يرجى فيه الخير، وترجى معه السلامة والإحصان. نعم.","link":"https://binbaz.org.sa/fatwas/5381/حكم-الزواج-بنية-جازمة-للطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_061/06102.mp3","categories":["الطلاق","شروط وأركان الزواج","نكاح الكفار","فتاوى متنوعة"]},{"id":7968,"question":"هذه رسالة وردتنا من عمان (س. ب) المملكة الأردنية الهاشمية عبد الله لفى البصيص ، إذاعة نداء الإسلام من مكة المكرمة، برنامج نور على الدرب أرجو التكرم علينا بحل السؤالين التاليين ولكم منا جزيل الشكر، يقول في سؤاله الأول: يوجد لي أخ رضع من امرأة ويوجد لها فتاة، هل يجوز لي أن أتقدم بطلب يد هذه الفتاة لزواجها أم لا؟","title":"حكم الزواج من أخت الأخ من الرضاع","answer":"الجواب: إذا كان أخوك ارتضع من أمها وأنت لم ترتضع من أمها فلا بأس، إنما تحرم على أخيك، إذا كان ارتضع من أمها حرمت عليه هو، إذا كان الرضاع خمس رضعات أو أكثر في الحولين حرمت عليه، أما أنت فلست منها في شيء، فلا حرج عليك أن تتزوجها إذا كانت أجنبية رضع منها أخوك فبناتها حرم على أخيك إذا كان الرضاع كاملاً، خمس رضعات فأكثر وكان رضاعه منها في الحولين فإنه يكون ولداً لها وتكون بناتها أخوات له، أما أنت فأجنبي، فلا حرج عليك أن تتزوج إحدى بناتها. نعم.","link":"https://binbaz.org.sa/fatwas/5517/حكم-الزواج-من-اخت-الاخ-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_070/07002.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":8131,"question":"هنا سؤال يسأله أخونا ويقول: ما هو السن الشرعي الذي يجوز للمرأة أن تتزوج فيه هل هو محدد أم لا؟","title":"السن المعتبر في تزويج المرأة","answer":"الجواب: ليس للسن الذي تتزوج فيه المرأة حد بالنسبة إلى أبيها، أبوها له أن يزوجها وإن كانت صغيرة كما زوج الصديق  عائشة وهي بنت ست سنين أو سبع سنين، إذا رأى المصلحة في ذلك، إذا رأى أن الخاطب كفء لها وأنه يغتنم ولا ينبغي أن يؤجل بل يغتنم فلا بأس، والأب ينظر في مصالح أولاده.\nأما الأولياء الآخرون فليس لهم أن يزوجوا إلا بعد بلوغها سناً تكون أهلاً للاستئذان؛ لأنهم مأمورون بأن يستأذنوها، أما الأب فله أن يزوجها بغير إذنها إذا كانت دون التسع السنين اقتداءً بما فعله الصديق وأقره النبي ﷺ عليه، قالوا: هذا يدل على أن البنت ولو كانت صغيرة يزوجها أبوها خاصة بغير إذنها ولو كانت غير أهل للإذن كبنت الخمس وأربع إذا رأى المصلحة في ذلك لا لأجل المال بل لأجل المصلحة مصلحة البنت كما زوج الصديق عائشة لأجل مصلحة عائشة فمن يدرك النبي عليه الصلاة والسلام ومن يحصل النبي عليه الصلاة والسلام، فلهذا بادر إلى تزويجه عليه الصلاة والسلام، فإذا خطب منه الرجل الصالح من أهل الخير من أهل العلم والفضل والاستقامة وخشي أن يفوت هذا الرجل الصالح فعقد له عليها فلا بأس، لكن ليس له أن يقربها بالجماع حتى تكون أهلاً لذلك، ليس للزوج أن يتصل بها حتى تكون أهلاً للجماع يحرم عليه ما يضرها.\nأما الأولياء الآخرون فليس لهم أن يزوجوا إلا عند بلوغها التسع، فإذا بلغت تسعاً زوجوها بإذنها، لقوله ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن، قالوا: يا رسول الله! كيف إذنها؟ قال: أن تسكت.\nوهكذا الأب إذا بلغت تسعاً يستأذنها أيضاً، أما ما دون التسع فلا يلزم الأب استئذانها، لأنها ليست من أهل الإذن، أما إذا بلغت تسعاً فأكثر فإن أباها يستأذنها ولا يجبرها أيضاً هذا الصواب، ليس له جبر البنت البالغة تسعاً فأكثر، وإنما يزوج من دونها بغير إذنها للمصلحة المصلحة الشرعية للبنت كما تقدم، أما بقية الأولياء كأخيها وعمها وابن عمها ونحو ذلك فليس لهم أن يزوجوا إلا بعد بلوغ التسع وإلا بالإذن أيضاً، لابد من أمرين: بلوغ التسع حتى تكون أهلاً كما قالت عائشة رضي الله عنها: إذا بلغت الجارية تسعاً فهي امرأة ولأن التسع مقاربة، فلا مانع من التزويج بالإذن، تستأذن وإذنها سكوتها، إذا سكتت كفى، هذا في حق البكر، فالسن حينئذ فيها تفصيل، ففي حق الأب ليس لها حد محدود إذا رأى المصلحة ولكن ليس له أن يزوج إلا بإذن بعد بلوغها التسع، والأولياء إنما يزوجوا بعد بلوغ التسع حتى يستأذنوا حتى يتمكنوا من الاستئذان؛ إذ من دونها ليس محل إذن، فلهذا حدد لهم هذا ليستأذنوا لتكون محلاً للإذن حتى لا تجبر.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/5927/السن-المعتبر-في-تزويج-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_103/10306.mp3","categories":["شروط وأركان الزواج"]},{"id":8163,"question":"وردتنا رسالة من خميس مشيط من مرسلها المستمع (س. ب. ش) يقول فيها: السلام عليكم ورحمة الله وبعد: يقول إنني أعتبر الرابع من إخواني، وقد أردت الزواج من واحدة من بنات عمي، ولكن والدتي قالت: إنها قد أرضعت عمي الصغير، أصغر أولاد جدي مع أخي الأكبر، وقد رضعته أكثر من خمس مرات، ويعتبر عمي الذي أرضعته والدتي هو أخو الوالد من أبيه، وأعمامي كثيرون من إخوان الوالد من أبيه ومن أمه، فهل يجوز لي الزواج من بنات عمي، أرجو أن أجد عندكم جواب استفساري هذا؟","title":"مشروعية التزوج من بنات العم إذا لم يظهر رضاع","answer":"الجواب: إذا كان عمك الذي ارتضع من أمك عنده بنات، فليس لك أن تنكح بناته؛ لأنه كان أخاً لكم، لما كانت أمك أرضعت عمك الصغير، فإنه يكون بالرضاع أخاً لأولادها، ويكون أولادها الذكور أعماماً لأولاد هذا العم الصغير، والبنات عمات لأولاده، فليس لك نكاح بنات عمك هذا الذي ارتضع من أمك، أما أعمامك الآخرون فلك أن تنكح من بناتهم، مادامت أمك لم ترضعهم، وأنت لم ترضع منهم من زوجاتهم ولا من جدك فلا بأس أن تنكح من بنات عمك الآخرين، بنات أعمامك الآخرين لا بأس أن تتزوج منهم؛ لأنهم ليس هناك مانع، بنت العم مما أباح الله، إذا لم يكن هناك رضاعة، يعني: إذا لم يكن بينك وبينهن رضاعة، إما بكونك رضعت من زوجات أعمامك، أو ارتضعت من جدك، هذا الرضاع يمنع، أما مادمت لم ترضع من زوجات أعمامك ولا من زوجة جدك، ولم ترضع أمك بنات أعمامك، فإنك لا حرج عليك في النكاح منهن، إلا بنات عمك الصغير الذي ارتضع من أمك، فإنك لا يحل لك أن تتزوج منهن أحداً. نعم.","link":"https://binbaz.org.sa/fatwas/5971/مشروعية-التزوج-من-بنات-العم-اذا-لم-يظهر-رضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_091/09103.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":8331,"question":"نعود في هذه الحلقة سماحة الشيخ إلى رسالة وصلت إلى البرنامج من الجمهورية العربية اليمنية لواء إب، باعث الرسالة أحد الإخوة من هناك يقول محمد عبد الحميد محمد حاتم الحذيفي ، قرية المجدورة ، أخونا في حلقة مضت عرضنا له سؤالين وفي هذه الحلقة يسأل ويقول: ما هو الحكم في رجل استعقد عقد النكاح عن ولده بدون وكالة من ولده وبدون إذنه، علماً بأن الولد يبلغ العشرين من عمره، وأيضاً كان الولد حاضراً أثناء العقد، فهل العقد صحيح، أم أنه باطل شرعاً، أفيدونا ولكم جزيل الشكر؟","title":"حكم عقد النكاح من الوالد لولده البالغ دون رضاه","answer":"الجواب: ليس للأب ولا غير الأب أن يعقد عن ولده أو أخيه أو غير ذلك إلا بإذنه إلا بالوكالة، إذا كان قد بلغ الحلم، وهذا كما بين في السؤال قد بلغ العشرين، فليس لأبيه أن يتزوج عنه إلا بإذنه، فإذا كان الولد لم يأذن له في ذلك فالنكاح غير صحيح، والواجب أن يجدد؛ لأن الزوج هو صاحب العقد فإذا لم يباشر ولم يوكل فلا عقد. نعم.","link":"https://binbaz.org.sa/fatwas/6144/حكم-عقد-النكاح-من-الوالد-لولده-البالغ-دون-رضاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_111/11102.mp3","categories":["شروط وأركان الزواج"]},{"id":8335,"question":"سماحة الشيخ! إذا تفضلت تعرجون على أولئك الذين لا يأخذون رأي البنات عند الزواج، أو يرغمونهن ويحتجون بأعذار وأعذار؟","title":"حكم تزويج البنات دون رضاهن","answer":"الجواب: على كل حال ليس للأب ولا غير الأب أن يرغم وليته على الزواج، بل لا بد من إذنها؛ لقول النبي ﷺ: لا تنكح الأيم حتى تستأمر ولا تنكح البكر حتى تستأذن، قالوا: يا رسول الله! كيف إذنها؟ قال: أن تسكت، وفي اللفظ الآخر قال: إذنها صماتها، وفي اللفظ الثالث: والبكر يستأذنها أبوها وإذنها سكوتها، فالواجب على الأب أن يستأذن إذا بلغت تسعاً فأكثر، وهكذا أولياؤها لا يزوجون إلا بإذن، هذا هو الواجب على الجميع، ومن زوج بغير إذن فالنكاح غير صحيح.\nالمقدم: فالنكاح غير صحيح؟\nالشيخ: غير صحيح.\nالمقدم: جزاكم الله خيراً.\nالشيخ: لأن من شرط النكاح ومن شرط الصحة الرضا من الزوجين، إذا زوجها بغير رضاها وقهرها بالوعيد الشديد أو بالضرب فالزواج غير صحيح، إلا الأب فيما دون التسع، من زوجها وهي صغيرة أقل من التسع فلا حرج على الصحيح؛ لأن الرسول ﷺ تزوج عائشة بغير إذنها وهي دون التسع كما جاء به الحديث الصحيح، أما متى بلغت تسعاً فأكثر فإنه لا يزوجها إلا بإذنها، ولو أنه أبوها. نعم.\nالمقدم: بارك الله فيكم، إذاً كلمة للائي يردن الزواج سماحة الشيخ؟\nالشيخ: الواجب على الزوج إذا عرف أنها لا تريده أنه لا يقدم على ذلك، ولو تساهل معه الأب، الواجب عليه أن يتقي الله وأن لا يقدم على امرأة لا تريده، ولو زعم أبوها أنه أجبرها، الواجب عليه أن يحذر ما حرم الله عليه؛ لأن الرسول أمر بالاستئذان عليه الصلاة والسلام.\nالمقدم: وهل من كلمة للمخطوبة؟\nالشيخ: المخطوبة نوصيها بتقوى الله ونوصيها بالموافقة، إذا رأى والدها أن يزوجها على إنسان ولا شيء في دينه والحمد لله، فنوصيها بالموافقة إذا كان الزوج الخاطب طيباً في دينه وفي أخلاقه، فإنا نوصيها وننصحها بأن توافق ولا ترد الخاطب، ولو كان المزوج غير الأب فإذا عرفت أنه صالح فإنها ينبغي لها أن توافق؛ لما في النكاح من الخير الكثير والمصالح الكثيرة، ولأن العزوبة فيها خطر، فالذي نوصي جميع بناتنا جميع الفتيات نوصيهن جميعاً بالموافقة، متى جاء الكفء فنوصيهن جميعاً بالموافقة وعدم الاعتذار بالدراسة أو بالتدريس أو بغير ذلك.","link":"https://binbaz.org.sa/fatwas/6150/حكم-تزويج-البنات-دون-رضاهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_111/11107.mp3","categories":["شروط وأركان الزواج"]},{"id":8343,"question":"ما هو الحكم في رجل استعقد عقد النكاح عن ولده بدون وكالة من ولده وبدون إذنه، علماً بأن الولد يبلغ عشرين من عمره، وأيضاً كان الولد حاضراً أثناء العقد، فهل العقد صحيح أم أنه باطل شرعاً، أفيدوني ولكم جزيل الشكر؟","title":"حكم من عقد له والده وهو حاضر بالغ دون رضاه","answer":"الجواب: لا يصح العقد إلا بإذن الزوج أو بمباشرته إما بتوكيله وإلا مباشرته، ولو أنه والده، إذا كان الزوج مكلفاً فإن الوالد لا يعقد له إلا بإذنه، كما أنه لا يعقد على البنت البالغة تسعاً إلا بإذنها على الصحيح، فالرجل من باب أولى لا يزوجه إلا بإذنه إذا كان قد بلغ الحلم، وهذا قد بلغ الحلم ولم يأذن فلا يكون الزواج صحيحاً، إلا إذا كان قد أمضاه بأن قال: أتزوج؛ لأنه حاضر، فهذا يدل على أنه قد رضي بهذا وقد أمضى والده في ذلك الزواج جعله يتزوج عنه، فإذا كان قد فعل مع والده شيئاً يدل على أنه سامح بذلك من كلمة مناسبة، أو شيء يدل على أنه موافق وأنه يرضى بأن يزوجه والده فالنكاح صحيح؛ لأن حضوره يدل على أنه راض بذلك، لم يتكلم ولم يمنع، فالحاصل أنه إذا وجد من الولد ما يدل على إذنه لوالده وسماحه لوالده بالتزوج عنه فإنه صحيح، أما إذا كان الولد لم يتكلم ولم يقل شيئاً يدل على الوكالة والإذن، ولم يسأله أبوه عن شيء يدل على ذلك، فإن هذا الزواج تجب إعادته إذا كانت الزوجة ترغب وهو يرغب، إذا كان الرجل يرغب والمرأة ترغب، فإنه يجدد النكاح؛ لأنه صدر من غير زوج ولا وكيل. نعم.","link":"https://binbaz.org.sa/fatwas/6161/حكم-من-عقد-له-والده-وهو-حاضر-بالغ-دون-رضاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_112/11207.mp3","categories":["شروط وأركان الزواج"]},{"id":8431,"question":"رسالة مطولة باعثها أحد الإخوة من العراق يقول علي حسين محسن العامري ، محافظة واسط مدينة الكرامة العراق، أخونا مشكلته كالتالي: يقول: أنا شاب في الثالثة والعشرين من عمري متزوج ولي طفل، قمت خلال عملي في إحدى الدوائر من خلال المخالطة اليومية مع الناس، تعلقت بإحدى الفتيات، وهي كذلك، المهم تقدمت إلى أهلها للزواج منها فرفضوا بحجة أنني متزوج وكذلك أسكن المنطقة الريفية، وكررت الحالة أكثر من مرة فلم تتم موافقتهم على الزواج، فلما يئست منهم قررت ترك تلك الفتاة، وفعلاً قلت لها: إننا سوف نفترق؛ لأن الأمور تأزمت إلى حيث الأصعب، ومن المستحيل أن أطلق زوجتي الأولى وأترك ولدي إنني أخاف من الله، إخوتي في الدين: لما عرفت هي بذلك قررت الانتحار، والله يعلم بذلك، وفعلاً تناولت السم، ونقلت إلى المستشفى على إثرها، ثم فرجت بعد أسبوع، فكررت الخطبة للمرة الثالثة فلم يوافقوا، فحاولت الانتحار ثانية، ونقلت إلى المستشفى ثانية، ويستمر على هذا المنوال سماحة الشيخ إلى أن يقول في نهاية الرسالة: ماذا أفعل للمشكلة؟ أريد حلاً يرضي الله ورسوله والناس، هل يجوز لي أن أتزوج وأهرب بها معي؟ أم ماذا أفعل أرشدوني للطريق الشرعي وفقكم الله، ويبدو أن للموضوع صلة بالاختلاط سماحة الشيخ؟","title":"حكم محاولة الانتحار لعدم موافقة الولي على الزواج","answer":"الجواب: لا ريب أن الانتحار جريمة عظيمة، ومن كبائر الذنوب، يقول النبي ﷺ: من قتل نفسه بشيء عذب به يوم القيامة، والله يقول: وَلا تَقْتُلُوا أَنفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا [النساء:29].\nفهذه الفتاة حرام عليها الانتحار، والواجب عليها الصبر والاقتناع بما قسم الله لها، والتماس زوج آخر.\nوأما الأهل فالواجب عليهم أن ينظروا في الأمر، أهل الفتاة، الواجب عليهم أن ينظروا في الأمر، فإذا كان الرجل صالحاً للزواج فينبغي أن يزوجوه، ولو كان معه زوجة، والحمد لله قد أباح الله للمسلم أربعاً من النساء، فالواجب على أهل الفتاة أن يخافوا الله، وأن يراقبوا الله، وأن يزوجوها إذا خطبها الكفء، وإن كان عنده زوجة أو زوجتان أو ثلاث وهي رابعة لا يضر؛ فقد جاء عنه ﷺ أنه قال: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه - في لفظ: وأمانته- إلا تفعلوه تكن فتنة في الأرض وفساد كبير، فالمشروع لهم أن يزوجوا من خطب منهم إذا كان أهلاً لذلك، ولو كانت عنده زوجة، إذا كان ديناً مسلماً، الله يقول جل وعلا: يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ [الحجرات:13].\nوالنبي صلى الله عليه وسلم زوج فاطمة بنت قيس القرشية ، زوجها من أسامة بن زيد وهو مولى عتيق أعتقه النبي عليه الصلاة والسلام، وزوج عبد الرحمن بن عوف القرشي الزهري بلال بن رباح الحبشي أخته أخت عبد الرحمن وهي زهرية قرشية ، فالأمر في هذا واسع بحمد الله، وزيد بن حارثة تزوج زينب بنت جحش بنت عمة النبي عليه الصلاة والسلام.\nفالأمر في هذا بحمد الله واسع المهم الدين، فإذا كانت المرأة ترغبه فهي ترغب هذا وهو دين وهو معروف بالدين فالحمد لله، الواجب أن لا يلجئوها إلى الانتحار وإلى هذا الشر العظيم.\nوالواجب عليها هي أن تحذر الانتحار، وأن تتقي الله، وأن تبتعد عن هذا الشر العظيم.\nوعليك أيها الخاطب! أن تقنعها، وأن تخوفها من الله، وأن ترغبها في الخير، وأن تقول لها: لا، إذا تيسر الزواج بالطريقة الشرعية فالحمد لله، وإلا فالواجب علي وعليك طاعة الله ورسوله، والحذر مما نهى الله عنه ورسوله من الانتحار وغيره، هذا هو نصيحتي لجميع أهلها نصيحتي لهم أن يزوجوها، ونصيحتي لك أيضاً أن تقنعها أنت، وأن تنصحها وتوصيها بالخير والصبر حتى يقنع أهلها بالزواج، وعليك أن تنصحها أيضاً من جهة الانتحار وأنه محرم، كبيرة من كبائر الذنوب، ومن أسباب دخول النار، فالواجب عليها الحذر من ذلك، نسأل الله للجميع الهداية.\nأما أخذها بالقوة والهروب فهذا منكر لا يجوز، هذا لا يجوز لك ولا لها أيضاً، بل عليكما مراعاة الأمور الشرعية والحذر مما حرم الله عليكما جميعاً، والله المستعان. نعم.\nالمقدم: جزاكم الله خيراً، نتج هذا سماحة الشيخ عن الاختلاط كما ........ ؟\nالشيخ: الاختلاط شره عظيم، الواجب على المرأة أن تبتعد عن الاختلاط بالرجال، والواجب على الرجل أن يبتعد عن الاختلاط بالنساء، والواجب على المرأة أن تتستر، وأن تبتعد عن أسباب الفتنة، يكون عليها الستر والحجاب وعدم التبرج هذا هو الواجب، الله ما شرع لنا هذا إلا لمصلحة الجميع، ولهذا قال سبحانه: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33]، فلولا أن التبرج يضر الجميع لما نهى عنه سبحانه وتعالى، والتبرج هو إظهار المحاسن، هو إظهار الزينة، فالواجب على النساء التستر، والحجاب، والبعد عن مخالطة الرجال إلا بالحشمة، والحجاب، والكلام الطيب، والأسلوب الحسن البعيد عن الفتنة، وهكذا الرجل يجب عليه أن يبتعد عن الاختلاط بالنساء الكاشفات العاريات أو شبه العاريات، يجب عليه أن يبتعد عن ذلك، وأن يبتعد عن كل أسباب الفتنة، يخاف الله ويراقبه سبحانه وتعالى، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/6315/حكم-محاولة-الانتحار-لعدم-موافقة-الولي-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11908.mp3","categories":["النظر والخلوة والاختلاط","شروط وأركان الزواج"]},{"id":8501,"question":"نعود في بداية هذا اللقاء سماحة الشيخ إلى رسالة الأخت صابرين الصغيرة من ليبيا، أختنا عرضنا أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: هل المرأة مكان للتجارة، حيث يتعنت الآباء في تكاليف الزواج؟","title":"حكم استئذان المرأة عند الزواج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفلا شك أن هذه المسألة التي تقدمت بها الأخت في الله صابرين مسألة جديرة بالعناية، فإن الواجب على الآباء أن يعنوا بأمر البنات، وأن يجتهدوا في تزويجهن على الأكفاء، وأن يسهلوا في التزويج وأن لا يتكلفوا، فليست المرأة سلعة تباع وتشترى، وليست محلاً للتجارة، ولكن المقصود التماس الكفء الصالح الدين الذي يتولاها ويحسن إليها، فإن ناسبته أحسن إليها وأحسن عشرتها، وإن لم تناسبه لم يظلمها بل وسع لها.\nهذا هو الواجب على الآباء وعلى الأولياء جميعاً، أن يتقوا الله في النساء، وأن يجتهدوا في التماس الأكفاء، وعدم رد الخاطب الطيب، وأن لا يجبروهن على من لا يرضين، لابد من استئذانها، ولابد من أخذ رضاها إذا بلغت تسعاً فأكثر؛ لقول النبي صلى الله عليه وسلم في الحديث الصحيح: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن، قالوا: يا رسول الله!وكيف إذنها؟ قال: أن تسكت وفي اللفظ الآخر: قالوا: يا رسول الله! إنها تستحي، قال: إذنها صماتها، وفي اللفظ الآخر: واليتيمة تستأذن وإذنها السكوت واللفظ الآخر: والبكر يستأذنها أبوها وإذنها السكوت فصرح بالأب وأن الأب ليس له الجبر، وهو الأب الذي هو أقرب ولي، فإذا كان الأب لا يجبر، فالبقية من باب أولى، وهذا هو المختار، وذهب بعض أهل العلم إلى أن الأب يجبر البكر، ذهب بعض أهل العلم إلى أن الأب يجبر البكر الذي لم تتزوج، وهذا قول مرجوح.\nوالصواب: أنه ليس له الإجبار بل عليه أن يسترضيها وأن ينصحها ويشير عليها وليس له جبرها ما دامت بلغت تسعاً فأكثر، أما إن كانت دون التسع فلا بأس أن يزوجها بغير إذنها؛ لأنه أعلم بمصالحها والدليل على ذلك أن النبي ﷺ تزوج عائشة ولم تستأذن؛ لأنها كانت صغيرة بنت ست أو سبع كما جاء في الحديث الصحيح، زوجها الصديق وهي بنت ست أو سبع، ودخل عليها النبي وهي بنت تسع عليه الصلاة والسلام.\nفالحاصل إذا كانت دون تسع ورأى من المصلحة أن يزوجها؛ لئلا يفوت الكفء الطيب لا من أجل المال، بل من أجل المصلحة الدينية، إذا رأى وليها يعني: أباها أن يزوجها وهي دون التسع؛ لأنه خطبها رجل كفء طيب صاحب دين وخير وخشي أن يفوت فلا بأس.\nأما بقية الأولياء فليس لهم تزويجها إلا بإذنها بعد التسع، ليس لهم أن يزوجوها وهي صغيرة قبل التسع لا، إنما هذا خاص بالأب لقصة عائشة رضي الله عنها، أما بقية الأولياء كالإخوة والأعمام ونحوهم فليس لهم تزويج البنت حتى تكمل تسعاً وحتى تصلح للزواج ثم لابد من استئذانها، فإن أذنت وإلا لم يجز لهم تزويجها، وليس لهم التعنت بالتماس أصحاب المال وأصحاب التجارة أو الوزارة والوظائف لا، الواجب عليهم أن لا يردوا الخاطب الكفء وإن كان من غير ذوي المناصب.\nولهذا جاء عنه ﷺ أنه قال: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إن لا تفعلوه؛ تكن فتنة في الأرض وفساد كبيروفي لفظ: وفساد عريض وفي الصحيحين عن النبي ﷺ أنه قال: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها،، فاظفر بذات الدين تربت يداك فإذا كان الرجل يؤمر بأن يظفر بذات الدين فهكذا ولي المرأة وهكذا المرأة عليهم الحرص أن يظفروا.. على الظفر بذي الدين وصاحب الدين، فعليها أن تسعى لذلك وتجتهد في ذلك وتقول لأوليائها أن يلتمسوا ذلك، وعلى وليها أن يجتهد في ذلك حتى يلتمس الكفء الطيب، فإن صاحب الدين ينفعها ولا يضرها، بخلاف الفجرة فإنهم يضرونها، وقد يجرونها إلى فجورهم، أصحاب الخمور وأصحاب الفساد شرهم عظيم، فينبغي التحرز منهم حتى لا يضروها، أما الذي لا يصلي فلا يزوج، الذي لا يصلي لا يزوج بالمرأة المسلمة؛ لأن ترك الصلاة كفر أكبر -نسأل الله العافية- في أصح قولي العلماء.\nفالحاصل والخلاصة: أن الواجب على الآباء والأولياء أن يعنوا بالأكفاء وأن يحرصوا على تزويج البنات بالرجل الطيب ولو كان فقيراً، ولو كان بمهر قليل، فالمطلوب عفتها وصيانتها، ليس المطلوب المكاثرة بالمال، قال تعالى: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32] فالمال يأتي به الله سبحانه وتعالى، وقال النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء ولم يقل: إذا خطب منكم ذو المال الكثير، بل أمر الجميع بالزواج هذا عام للرجال والنساء، يا معشر الشباب! من استطاع منكم الباءةة فليتزوج، فإنه أغض للبصر، وأحصن للفرج فإذا كان الشاب مأموراً بالزواج فهي كذلك مأمورة، إذا خطب إليها الكفء فعليها أن تتزوج، وعليها أن تبادر وعليها أن ترضى وأن تقبل، ولا يجوز لأوليائها منع الزواج من أجل المال والمكاثرة بالمال، أو لأسباب لا وجه لها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6569/حكم-استىذان-المراة-عند-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_127/12701.mp3","categories":["شروط وأركان الزواج"]},{"id":8514,"question":"هذه رسالة وردتنا من المرسل عبد الباسط عبد العال آدم مصري مقيم بجدة، يقول: إنني تزوجت من بنت خالي، وعقدت قراني ولم أدخل بها، وهذه الزوجة أخت أخ لي من الرضاع، أي: هو رضع من والدتي وأنا لم أرضع من والدته، والزوجة أخته من والده فقط من امرأة أخرى، فهل هذا الزواج حلال أم حرام؟","title":"حكم الزواج من أخت الأخ من الرضاعة","answer":"الجواب: نعم، هذا الزواج لا بأس به، مادام لم ترضع من أمك وأنت لم ترضع من أمها ولا ممن ارتضعت منه فلا بأس، أما كون أخيك رضع من المرأة التي رضعت منها لا يضر، المقصود أنه لا حرج عليك في هذا أيها السائل. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6589/حكم-الزواج-من-اخت-الاخ-من-الرضاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20306.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":8592,"question":"سماحة الشيخ أخونا من جمهورية مصر العربية أحمد عبد الله أحمد علي يقول: إن عندهم في قرى مصر 50% لا يصلون قبل الزواج وخاصة البنات، نسبة كبيرة سماحة الشيخ، ولاسيما أنه يقول إنهن مسلمات.","title":"ما الحكم إذا كان أحد الزوجين لا يصلي أو كلاهما؟","answer":"","link":"https://binbaz.org.sa/fatwas/6698/ما-الحكم-اذا-كان-احد-الزوجين-لا-يصلي-او-كلاهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_128/12803.mp3","categories":["حكم الصلاة وأهميتها","شروط وأركان الزواج"]},{"id":8757,"question":"الرسالة الرابعة في هذه الحلقة وردتنا من السائل أبكر جمعة طنبل من مدينة الأبيض من شرق السودان يقول: هناك شخص تزوج من حلال وحرام من المال، وبعد أن أخذ فترة من السنين انتبه قلبه وعرف أنه تزوج بحرام فما حكمه؟ وماذا عليه أن يفعل؟","title":"حكم الزواج إذا كان من المال الحلال والحرام","answer":"الجواب: الزواج صحيح لا يضره ذلك ما دام استوفى الشروط: بأن تزوجها برضاها، وبالولي الشرعي، والشاهدين، وهي في حالة ليس فيها مانع من الزواج، فكون المهر فيه حرام لا يضر الزواج، إذا كانت الشروط متوفرة في النكاح وإنما اختل بعض المال فصار في المال بعض الحرام فهذا لا يخل بالزواج، وعليه التوبة إلى الله  مما أخذ من الحرام، وعليه أن يؤدي المال إلى أهله إن كان سرقه من أحد أو غصبه من أحد يرده إلى أهله، فإن كان لا يتمكن من ذلك تصدق به عن أهله في وجوه البر كالفقراء والمساكين وإصلاح الطرقات ودورات المياه حول المساجد وأشباه ذلك، أما النكاح فصحيح. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6912/حكم-الزواج-اذا-كان-من-المال-الحلال-والحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_217/21709.mp3","categories":["شروط وأركان الزواج"]},{"id":8783,"question":"يسأل أيضاً ويقول: هناك رجل تزوج امرأة ثم غاب فترة طويلة استمرت سنين، فلما طال غيابه عنها تزوجت المرأة من رجل آخر فأنجبت منه طفلين وبعد ذلك حضر الزوج الأول، فما الحكم في هذه الحالة؟ وإذا كان طلاق المرأة من الرجل الثاني وزواجها من الأول باطل فلمن يكون الأبناء، للرجل أم للمرأة، أفيدونا بارك الله فيكم؟","title":"حكم الزواج من زوجة رجل غائب دون فسخ من القاضي","answer":"الجواب: هذه المرأة التي تزوجت إن كانت تزوجت من غير فسخ من الحاكم ولا طلاق من زوجها فنكاحها باطل، وأولادها أولاد شبهة يلحقون بزوجها الذي تزوجها بغير وجه شرعي؛ لأنهم ولدوا على شبهة، الزوج الثاني الذي نكحته أولاده تابعون له؛ لأنه نكاح شبهة، ولكنه باطل لأنه حصل من دون طلاق من الزوج ولا فسخ من المحكمة، بل هذا جرأة منها وتساهل منها فبطل، ولكن الأولاد حصلوا عن شبهة وعن ظن الزوج أن هذا الزواج صحيح فينسبون إليه ويحكم له بهم إذا كان الأمر هكذا عن شبهة وعن ظن أن زواجه بها صحيح، أما إن كان قد تعمد وطأها باسم النكاح وهو يعرف أنه نكاح باطل وأنها غير مطلقة وأن الحاكم ما فسخها، بيعلم هذا كله هذا زنا، يقام عليه حد الزنا وأولاده ينسبون إلى المرأة، لا ينسبون إليه، أما إذا كان تزوجها ظناً أنها مخلوعة أو أنها مطلقة ما درى أنها مع الزوج، فهذا نكاحه باطل ولكن أولاده يلحقون به لأجل الشبهة.\nوأما الزوج الذي قدم بعد ذلك وهي لم تفسخ منه ولم تطلق منه فهذا باق على النكاح هي زوجته تفسخ من هذا الزوج الذي أخذها بغير حق وتعتد، فإذا اعتدت من هذا الزوج الذي نكحها بشبهة تعود إلى زوجها الأول؛ لأن نكاحه باقي لم يفسخ ولم يحصل منه طلاق.\nفالحاصل المسألة هذه مسألة كبيرة، والواجب أن تحل من جهة المحكمة حتى يؤدب هذا الزوج الذي أخذها بغير حق إذا كان الأمر كما قاله السائل، فإنه يستحق أن يؤدب بكل حال لأنه ما تثبت في الأمر، وإن كان يعلم أنها مزوجة وأنها ذات زوج ثم أقدم على نكاحها باسم نكاح باطل فهذا يستحق أن يقام عليه الحد حد الزنا، إن كان محصناً يرجم، وإن كان بكراًَ يجلد مائة جلدة ويغرب عاماً.\nفالحاصل: أن هذه مسألة مهمة يجب أن تحال إلى المحكمة حتى تنظر فيها المحكمة وحتى تحقق فيها وحتى تعمل ما يقتضيه الشرع المطهر. والله المستعان.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6935/حكم-الزواج-من-زوجة-رجل-غاىب-دون-فسخ-من-القاضي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21908.mp3","categories":["شروط وأركان الزواج","المحرمات من النساء"]},{"id":9194,"question":"هنا رسالة وصلت إلى البرنامج من الأخ عبد الغني صالح علي الصلاحي من الجمهورية العربية اليمنية، أخونا يقول: لي أخت من الرضاع وأنا أصغر إخواني ولي أخ أكبر ويريد أن يتزوج هذه الفتاة، هل يصح أن يتزوجها أم لا؟ أفتونا جزاكم الله خيرا.","title":"حكم زواج الأخ من أخت أخيه من الرضاع","answer":"الجواب: إذا كانت هذه الفتاة أرضعتها أمكم رضاعًا كافيًا وهو خمس رضعات فأكثر فهي حرام عليكم جميعًا؛ لأنها أختكم جميعًا، إذا كان الرضاع خمس رضعات أو أكثر حال كون الرضيعة في الحولين لم تفطم.\nأما إن كانت الرضاعة أنت رضعت من أمها ولم ترضع هي من أمكم إنما أنت رضعت من أمها فقط ولم يرضع أخوك من أمها فإنها حرام عليك أنت، هي أختك أنت وليست أختًا له هو؛ لأنه لم يرضع من أمها، وإنما أنت رضعت من أمها، فتحرم عليك؛ لأنها أختك من الرضاعة إذا كان الرضاع خمس رضعات أو أكثر، ولكن لا تحرم على أخيك؛ لأنه لم يرضع من أمها، والله أعلم. نعم.","link":"https://binbaz.org.sa/fatwas/7354/حكم-زواج-الاخ-من-اخت-اخيه-من-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18104.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":9198,"question":"تزوج رجل وعندما جاء وقت العقد راح والده وعمه وعقدا دون حضور الزوج، علمًا بأنه موجود بنفس القرية التي تم فيها العقد، فهل الزواج صحيح أم لا؟","title":"حكم عقد الزواج دون حضور الزوج","answer":"الجواب: إذا كان تم العقد له على البنت بالوكالة لأبيه أو لعمه فلا بأس، أما أن يعقد أبوه أو عمه له بدون وكالة فهذا لا يصح، الواجب أن يكون العقد على يده هو فيقول: قبلت، يقول له الولي: (زوجت) وهو يقول: قبلت، أما أن يتولى عنه أبوه أو عمه أو غيرهما من دون وكالة شرعية فلا يصح إذا كان مكلفًا، أما إذا كان صغيرًا لم يبلغ الحِنْث فلأبيه أن يتزوج له على الصحيح. نعم.","link":"https://binbaz.org.sa/fatwas/7357/حكم-عقد-الزواج-دون-حضور-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18107.mp3","categories":["شروط وأركان الزواج"]},{"id":9328,"question":"أخيراً يسأل ويقول: هل يصح لي نكاح بنت ابن خالتي أم لا؟","title":"حكم نكاح بنت ابن الخالة","answer":"الجواب: نكاح بنت الخالة وبنت الخال وبنت ابن الخال وبنت ابن الخالة كله جائز، المحرم نكاح الخالة نفسها، أو العمة نفسها، أما بنت الخالة وبنت العمة، وبنت العم وبنت الخال، لا حرج في نكاحها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7499/حكم-نكاح-بنت-ابن-الخالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23714.mp3","categories":["شروط وأركان الزواج"]},{"id":9398,"question":"الرسالة التالية وصلت من أحد الإخوة المستمعين يقول ابن العلا (س. م. ع. م) أخونا رسالته مطولة بعض الشيء، يقول فيها: من المعروف أن العقد شريعة المتعاقدين، وهذا أمر مسلم به ولا جدال فيه، وأن من شروط صحة العقد أيًا كان هو الرضا من الطرفين المتعاقدين، والشهود العيان، ومحل نشأة العقد، لكن ماذا عن عقد الزواج الذي يتم عن طريق المأذون الشرعي أو القاضي بحضور طرف واحد من أطراف العقد، في حين أن هذا الطرف هو الزوج، والطرف الآخر هو ولي الزوجة، حيث أنه يتم عادة الزواج بهذه الكيفية للعقد دون حضور الزوجة الطرف الثاني الأصلي وصاحبة الشأن، بالرغم من أن الزوجة لم يؤخذ رأيها وقت تقديم الزوج لطلب يدها، وهذه عادة يسير عليها أهالي مدينة كذا -يذكرها شيخ عبد العزيز - بعدم أخذ رأي الفتاة أو التي ترغب في الزواج عندما يتقدم لها أحد حتى ولو فرض أن هذا المتقدم قريب لها، ويستمر على هذا الأسلوب -شيخ عبدالعزيز - ليخلص أن المخطوبة لا يؤخذ رأيها، وعند كتابة العقد لا تكون حاضرة، ويسأل عن الحكم؟","title":"حكم نكاح المرأة دون أخذ إذنها","answer":"الجواب: العقود أنواع: فعقد النكاح له شأن، وعقد البيع والإجارة ونحوهما له شأن آخر، فعقد البيع يستحب فيه الإشهاد؛ لأن الله قال: وَأَشْهِدُوا إِذَا تَبَايَعْتُمْ [البقرة:282]، فإذا تبايعا وأشهدا شاهدين، فهذا هو الأفضل، وهذا هو السنة، وإن كان دينًا شرع مع ذلك الكتابة أن يكتبا العقد بينهما، كما قال الله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُمْ بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ [البقرة:282].\nفالسنة الكتابة مع الإشهاد، أما إذا كانت تجارة حاضرة كفى الإشهاد، فإن تبايعا من دون إشهاد صح البيع، وفاتتهم السنة؛ لأنه ثبت عن النبي ﷺ ما يدل على صحة البيع ولو من دون إشهاد، وإنما هو مستحب.\nأما عقد النكاح فله شأن آخر، فلابد من رضا المرأة إذا كانت ثيبًا وقد تزوجت أو بكرًا على الصحيح من أقوال العلماء ولابد مع هذا من الشاهدين يحضران العقد بحضرة الزوج والولي، أما المرأة فلا يشترط حضورها ولا لازم لحضورها، ما دامت راضية بالعقد فلا يحتاج إلى حضورها، وإنما المطلوب أربعة: الزوج، والولي، والشاهدان، هؤلاء هم الذين يحضرون العقد أربعة: الزوج والولي والشاهدان، فإذا حضر الشاهدان كفى؛ لقوله ﷺ: لا نكاح إلا بولي، وشاهدي عدل.\nفالمقصود: أنه يزوج المأذون الزوج من جهة الولي بحضرة الشاهدين، فيقول الولي: زوجتك ابنتي، أو أختي، أو ابنة أخي -على حسب حال المنكوحة- ويقول الزوج: قبلت هذا الزواج، والشاهدان يسمعان، هذا إذا كانت راضية الزوجة شاهدين يشهدان برضاها، أو المأذون قد حضرت عنده وعرف رضاها، أو أبوها أخبر بذلك وهو ممن يوثق به ويطمئن إليه كفى ذلك.\nأما ما يتعلق بالبكر ففيها خلاف مثل ما تقدم، لكن الصحيح أنه لابد من رضاها، وليس لأبيها أن يزوجها بغير رضاها؛ لقول النبي ﷺ: والبكر يستأذنها أبوها وإذنها صماتها، ولقوله ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن، قالوا: يا رسول الله كيف إذنها؟ قال: أن تسكت فلابد من إذنهما جميعًا، الثيب والبكر، ولو كان الولي هو الأب على الصحيح من قولي العلماء، وقال بعض أهل العلم: إن لأبيها خاصة أن يزوجها بغير إذنها؛ لأنه أعلم بمصالحها، لما جاء في بعض الروايات قال ﷺ: واليتيمة تستأمر قالوا: مفهومه أن غير اليتيمة لا تستأمر، والصواب: أن هذا لا مفهوم له، وأن الاستئذان لليتيمة وغير اليتيمة، ولكن نص النبي على اليتيمة لشدة الحاجة إلى استئذانها، وإلا فالجميع يستأذن، فجميع النساء يستأذن البكر والثيب، اليتيمة وغير اليتيمة، كل يستأمر، هذا هو الصواب.\nوإذا زوجها أبوها بغير إذنها وهي بكر وأجازه الحاكم الشرعي مضى؛ لأن الحاكم حكمه يرفع الخلاف، فإذا أجازه بعض الحكام من القضاة أخذًا بقول من قال: إن البكر لا يستأذنها أبوها وأنه أعلم بمصالحها، هذا قول معروف لأهل العلم، وإذا أجازه الحاكم وأمضاه الحاكم ارتفع الخلاف، ولكن لا يجوز لأبيها أن يتساهل في هذا، ولا أن يتعلق ببعض الخلاف في ذلك؛ لأن الرسول ﷺ قد حكم في الموضوع وهو المشرع عليه الصلاة والسلام، وهو الذي يجب على الأمة أن تأخذ بقوله وتستقيم على شرعه عليه الصلاة والسلام؛ ولأن الأب لا يؤمن قد يتساهل في هذا؛ إما لكونه ابن أخيه أو لأنه أعطاه مالًا كثيرًا أو لغير هذا من الأسباب، فلا يبالي بالبنت ولا يرحمها ولا يعطف عليها، ولا يبالي برضاها وعدمه؛ فلهذا جاء الشرع بالاستئذان مطلقًا ولو كان أباها ولو كانت بكر.\nلابد من الاستئذان على الصحيح دفعًا للمضرة عن البنت، وحرصًا على سلامة مطلوبها؛ ولأن الزوج له شأن عظيم فلابد من رضاها به. نعم.\nالمقدم: تتفضلون بإعادة صيغة العقد حتى تبتعد الشبهة عن أخينا لو تكرمت؟\nالشيخ: نعم، فالعقد يحضره أربعة: الولي وهو أبوها إن كان موجودًا، أو وكيله إن كان غائبًا، فإن كان مفقودًا فابنها إن كان لها ابن كبير مرشد، فإن كانت ليس لها ابن ولا أب أخوها الشقيق ثم أخوها لأب، ثم أقرب العصبة، هكذا يتولى العقد أقربهم وأولاهم الأب إن كان موجودًا ثم الجد إن كان موجودًا بعد الأب بأنفسهما أو بوكيليهما، فإذا عدم الأب والجد مطلقًا صارت إلى الابن ثم ابن الابن، فإن لم يوجد ابن ولا ابن ابن لأنها بنت صغيرة ما لها أولاد زوجها أخوها الشقيق إن كان لها أخ شقيق، فإن عدم فأخوها لأب، فإن عدما فابن أخيها الشقيق فإن عدم فـابن أخيها لأب، وهكذا الأقرب فالأقرب، وليس لهم جبرها على أحد، بل لابد من رضاها، إلا إذا كانت صغيرة دون التسع فلأبيها أن ينظر في مصلحتها للأب خاصة، أن ينظر في مصلحتها إذا كانت دون التسع، ولا تحتاج إلى إذن في هذه الحالة؛ لأن الرسول ﷺ تزوج عائشة من أبيها بغير إذنها؛ لأنها كانت صغيرة دون التسع زوجها وهي بنت سبع أو ست سنين .\nأما إذا بلغت تسعًا فإنها لا تزوج إلا بإذنها من أبيها وغير أبيها، نعم، ويحضره أربعة كما تقدم: الأب الولي مطلقا، الزوج، الشاهدان، هؤلاء الأربعة يحضرون النكاح، الولي سواء كان أبًا أو غيره، الزوج، الشاهدان، أما المرأة لا يشترط حضورها.\nالمقدم: لا يشترط حضورها؟\nالشيخ: نعم.\nالمقدم: وهل تشترط الوكالة بالنسبة للمرأة؟\nالشيخ: لا ما يحتاج وكالة، متى شهد الشاهدان برضاها كفى.\nالمقدم: بارك الله فيكم، إذًا المهم في الموضوع أن يؤخذ رأيها.\nالشيخ: نعم.\nالمقدم: وهذا ما يركز عليه أخونا في رسالته.\nالشيخ: لابد من هذا. نعم. ولو كانت بكرًا على الصحيح، إلا أن تكون دون التسع فلأبيها خاصة أن ينظر في مصلحتها وأن يزوجها بمن يراه أهلًا لذلك لوجه مصلحة لا للطمع بل لمصلحة للبنت نفسها. نعم.","link":"https://binbaz.org.sa/fatwas/7563/حكم-نكاح-المراة-دون-اخذ-اذنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_188/18804.mp3","categories":["شروط وأركان الزواج"]},{"id":9410,"question":"رسالة وصلت إلى البرنامج من الدمام وباعثتها إحدى الأخوات المستمعات، تقول: البندري هلال أختنا تسأل وتقول: سمعت وقرأت عن زواج في إحدى الدول العربية الإسلامية تقول: إن هناك زواج يسمى بالزواج العرفي، وآخر يسمى بالزواج الشرعي، وتخشى أن يكون الناس يقعون في هذا وتسأل عن الحكم لعل الناس يتنبهون؟","title":"الزواج العرفي","answer":"الجواب: تقدم ما يبين الزواج الشرعي، أما الزواج العرفي لا يلتفت إليه، يجب أن تكون العناية بالزواج الشرعي الذي ليس فيه محذور مما حرمه الله، فعلى آل الزوج وعلى آل الزوجة وعلى أقاربهما أن يتعاونوا حتى يكون الزواج شرعيًا بعيدًا عما حرم الله حريصين جميعًا على أن يستوفي المقام ما ينبغي فيه من الحكمة والأسلوب الحسن، وتعاطي ما ينبغي من الأمور الطيبة من عدم التكلف في الولائم، وعدم إيجاد ما حرم الله فيه من أغاني أو ملاهي أوتار أو ما أشبه ذلك.\nيعني: يجب أن يتعاونوا على توافر الخير وعدم الشر في هذا الزواج حتى يكون المطلوب حاصلًا من دون ما حرم الله، إذ المقصود هو عفة الرجل والمرأة وحصول الزواج لهما، فليكن ذلك على الطريقة الشرعية التي شرعها الله لعباده وأباحها لهم، وليبتعدوا جميعًا عما حرم الله في الأقوال والأعمال. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7575/الزواج-العرفي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_189/18906.mp3","categories":["شروط وأركان الزواج"]},{"id":9443,"question":"السؤال الثاني في رسالة الأخ (ف. ر. ع) من جمهورية اليمن، يقول فيه: هل يجوز للمسلم أن يتزوج بفتاة لم تصل؟ حيث أنه يعيش في بلاد أكثر أهلها لا يصلون، وأنه مضطر للزواج خوفًا من الفتنة، وسوف يشترط على أهل الفتاة أن تؤدي الصلاة أثناء عقد الزواج، وفي حالة عدم صلاتها يطلقها، فما الحكم في ذلك؟","title":"حكم الزواج بامرأة تاركة للصلاة","answer":"الجواب: ترك الصلاة من الرجال والنساء كفر أكبر في أصح قولي العلماء، وعلى هذا لا يجوز للمسلم أن ينكح امرأة لا تصلي، بل يجب عليه أن يتحرى في الزوجة أن تكون ذات دين، وأن تكون من المصليات، ومن الذين يحترمون الدين ولا يأتون بشيء إلا فيه، هذا هو الواجب على المسلم، ولهذا قال عليه الصلاة والسلام: تنكح المرأة لأربع: لمالها ولحسبها ولجمالها ولدينها، فاظفر بذات الدين تربت يداك متفق على صحته.\nفالمؤمن يتحرى في الزوجة أن تكون طيبة في دينها وأخلاقها وسيرتها، ومن أسرة طيبة، فإذا كانت لا تصلي فهذا من أعظم الكفر بالله في أصح قولي العلماء، وقد خالف في هذا من خالف من أهل العلم وقالوا: إن ترك الصلاة ليس بكفر أكبر إذا كان لا يجحد الرجل وجوبها ولا تجحد المرأة وجوبها ولكن ذلك عن كسل، هذا قول جماعة من أهل العلم، ويحكى قول الأكثرين.\nولكن الصواب الذي عليه الأدلة الشرعية: أن ترك الصلاة كفر أكبر وإن لم يجحد التارك وجوبها، لما ثبت عنه ﷺ أنه قال: رأس الأمر الإسلام، وعموده الصلاة فشيء ترك عموده وذهب عموده كيف يبقى؟!\nأيضًا ثبت عنه ﷺ وهو أصرح في هذا الباب قوله ﷺ: إن بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه، والتعبير بالرجل لا يخصه على طريقة الرسول ﷺ في الأحكام، فإنه إذا عبر بالحكم الشرعي باسم الرجل أو باسم المرأة فالحكم عام، وهكذا ما جاء في كتاب الله من الأحكام بأسماء الرجال أو بأسماء النساء الحكم عام، إلا ما جاء الدليل بالتخصيص، كتخصيص المرأة بنصف ميراث الذكر من الأولاد والإخوة، وغير ذلك مما جاء به التخصيص، وإلا فالأصل أنهما سواء في الأحكام وهذا منها.\nفإذا كفر بترك الصلاة الرجل فالمرأة كذلك، وإن كان ذلك عن تهاون وعن كسل، هذا هو الصواب.\nومن هذا الباب ما ثبت عنه أيضًا عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد في المسند وأهل السنن الأربع بإسناد صحيح عن بريدة ، وهذا عام للرجال والنساء.\nفنصيحتي للرجل السائل أن لا يتزوج إلا امرأة معروفة بالاستقامة والصلاة، والبعد عن كل ما يغضب الله عز وجل ولو بقي أعزب حتى يسهل الله له من يرضى دينها، والكتابية خير من هذه؛ لأن الكتابية أباح الله نكاحها إذا كانت محصنة، أما المشركة فهي محرمة علينا، كما قال الله جل وعلا: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221] وهذه يقال لها: مشركة، فالكتابية خير منها، وإن كان ترك نكاح الكتابية أولى وأفضل بكل حال، وأن يتزوج مسلمة حنيفية مؤمنة هذا هو الذي ينبغي له.\nلكن بكل حال إذا كان ولابد فتزوج كتابية محصنة أولى من كونك تتزوج امرأة لا تصلي، كافرة، نعم.\nلكن في الإمكان أن يشرط صلاتها وتوبتها قبل العقد، فإذا استقامت وهداها الله وتابت، وثبت لديه ذلك بأنها تركت عملها السيئ وأنابت إلى الله وصارت تصلي فليتزوجها والحمد لله.\nولعل رغبتها بالزواج تكون سببًا لتوبتها ورجوعها إلى الله، واستقامتها في الصلاة، فيكون قد أحسن إليها بهذا الزواج الذي جعله الله لها سببًا للتوبة والاستقامة وأداء الصلاة.","link":"https://binbaz.org.sa/fatwas/7604/حكم-الزواج-بامراة-تاركة-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19102.mp3","categories":["حكم الصلاة وأهميتها","شروط وأركان الزواج"]},{"id":9480,"question":"وهذه رسالة وردت إلى البرنامج من الجمهورية العربية اليمنية، من السائل يحيى محمد نصري، يقول: ما رأيكم في رجل أحب امرأة واتفقا على الزواج منها، فخطبها من والدها فرفض، وقال: إنه قد عاهد بالله أن يزوجها لابن أخته، لكن البنت لا تريد أن تتزوج بابن خالها أو بابن عمتها فرفضت بشدة هذا الزواج، لكن أبوها أجبرها فجلست مع ابن خالتها أو ابن عمتها ثلاثة أيام فقط ولم يدخل بها ورفضت الرجوع إليه، وهو رفض أن يطلقها، فبقيت عند والدها الآن خمس سنوات، ولا تريد أن تعود إلى زوجها المجبورة عليه، فهل يحق لها فسخ الزواج وكيف يكون ذلك؟","title":"حكم إكراه الوالد ابنته بالزواج من شخص ترفضه","answer":"الجواب: الواجب على والد البنت وعلى كل ولي أن لا يقهر الولية وأن لا يجبرها على الزواج بأحد، بل لابد من إذنها، يختار لها والدها، يختار لها وليها كأخيها وعمها يختارون الرجل الصالح الطيب، ولكن لا يجبرونها، يقول النبي ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن، قالوا: يا رسول الله! إنها تستحي -يعني: البكر- قال: إذنها صماتها، إذنها سكوتها، وقال ﷺ: والبكر يستأذنها أبوها وإذنها صماتها، وجاءت إليه امرأة بكر، قالت: يا رسول الله! إن أبي زوجني وأنا كارهة فخيرها النبي ﷺ، فالواجب على الآباء والأولياء جميعاً أن يتقوا الله، وأن لا يزوجوا مولياتهم إلا بالإذن بالموافقة، الحق لها والحاجة لها، لا تزوج إلا بإذنها، فإذا كرهت الزوج الخاطب لا تزوج عليه، بل يلتمس لها من ترضاه من الطيبين الأخيار، فإذا خطبها الكفء وجب تزويجها عليه، وإن كان بعيداً ليس من أقاربها، ولا يجوز جبرها على ابن خالتها أو ابن عمتها إذا كانت لا ترضاه، فالزواج هذا منكر وباطل ما يصح، إذا كانت مكرهة على ابن عمتها هو نكاح فاسد لا يصح، ويجب على والدها التوبة إلى الله، ويجب عليه أن يسعى في خلاصها من هذا الرجل من طريق المحكمة، أو من طريق إعطائه حقه وهو يسمح ويطلق حتى لا يكون النزاع بينهم، أو من طريق الأخيار يشيرون عليه وينصحونه حتى يطلق، المقصود أن الزوج عليه أن يطلق، يجب عليه أن يطلق ولا يحل له أن يأخذ امرأة تكرهه وتجبر عليه هذا لا يجوز له، بل يجب عليه أن يرجع عن هذا الرأي، وأن يرضى بحقه الذي دفع إليهم ثم يطلقها طلقة واحدة، حسماً لمادة التعلق بها وخروجاً من خلاف العلماء الذين يقولون: بجواز جبر الوالد لبنته البكر هو قول مرجوح، يقوله بعض العلماء: أن له أن يجبر بنته البكر، ولكنه قول ضعيف مرجوح مخالف لقول النبي ﷺ: لا تنكح البكر حتى تستأذن، وقوله ﷺ: والبكر يستأذنها أبوها وإذنها سكوتها، نسأل الله للجميع الهداية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7643/حكم-اكراه-الوالد-ابنته-بالزواج-من-شخص-ترفضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24106.mp3","categories":["شروط وأركان الزواج"]},{"id":9558,"question":"يسأل أيضاً ويقول: إذا كان رجل قد زنى بالمرأة لمدة طويلة حوالي سنة أو أكثر، وبعد هذه الفترة تقدم طالباً الزواج منها وفعلاًَ تزوجها، فما الحكم في ذلك؟ وهل زواجه بها صحيح؟ وإذا كان غير صحيح فماذا يعملون بعد الزواج وقد صار لهم أطفال؟ أفيدونا أفادكم الله.","title":"حكم من زنى بامرأة ثم تزوجها","answer":"الجواب: الزواج صحيح إذا كانت قد تابت من عملها السيئ فالزواج صحيح؛ لأنه مضى عليها مدة طويلة قد خرجت من عدة الزنا، فالزواج صحيح إذا كانت قد تابت وظهر منها الخير. نعم.\nالمقدم: بارك الله فيكم! والأطفال؟\nالشيخ: الأطفال .. صحيح يلحقون به، لأن الزواج صحيح يلحقه أولاده نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7723/حكم-من-زنى-بامراة-ثم-تزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_270/27007.mp3","categories":["شروط وأركان الزواج"]},{"id":9568,"question":"يسأل الأخ أيضاً عبد الله بن ناصر بن سيف من الدلم ويقول: شخص وهب بنته لشخص آخر، وكانا يتحدثان في مجلس بدون عقد رسمي، وعمر البنت آنذاك عشر سنوات، وبعد مضي سنتين تغير اتجاه الجميع، وتزوج البنت ابن الشخص الذي وهبت له، فما الحكم في هذه الحالة؟","title":"حكم قول الرجل لآخر: (وهبتك ابنتي) وزواجها من آخر","answer":"الجواب: أولاً: ينظر في الهبة إن كانت عن رضا من البنت وعن حضور شاهدين تم الزواج، فإن كانت البنت لم ترض أو لم يحصل شاهدان فإن الزواج لا يصح؛ لأن الواجب استشارة البنت إذا كان بلغت تسعاً لا يجوز تزويجها إلا بإذنها وإذنها سكوتها، فإذا كان والدها حين وهب لم يستأذنها أو استأذنها لكن لم يحضر شاهدان فالهبة والزواج غير صحيح، أما إن كان قد استأذنها ورضيت بالسكوت أو بالكلام وحضر شاهدان فالصواب: أنه يصح النكاح، وليس من شرطه أن يقول: زوجت أو أنكحت، بل إذا قال: وهبتك أو أعطيتك أو ملكتك صح إذا تمت الشروط الأخرى وانتفت الموانع. والله ولي التوفيق. نعم..\nالمقدم: لكن في هذه الحالة بعد سنتين تزوجها ابن الموهوبة له!\nالشيخ: إن كان الزواج الأول صح فالزواج الثاني باطل، فإن كان الزواج الأول ما صح صح الزواج الثاني. نعم..\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7736/حكم-قول-الرجل-لاخر-وهبتك-ابنتي-وزواجها-من-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_247/24708.mp3","categories":["شروط وأركان الزواج"]},{"id":9626,"question":"يقول ثانية: كثير ما يحصل عندنا في القرية عقد النكاح بين الخاطب أو بين الزوج ووكيل الفتاة مع إمام البلد بمفردهم، حيث يكون الشهود في غرفة أخرى، فهل يصح هذا العقد، أم لابد أن يحضر الشهود أثناء العقد بينهم؟ وما العمل فيما مضى من عقود؟","title":"حكم عقد النكاح بدون الشاهدين أو بدون ولي","answer":"الجواب: الصواب أنه لابد من إحضار الشاهدين والولي؛ لقول النبي ﷺ: لا نكاح إلا بولي وجاء في بعض الروايات: بولي وشاهدين ولأن ذلك من إعلان النكاح وقد أمر بإعلان النكاح، وهذا هو قول جمهور أهل العلم: إنه لابد من ولي وشاهدين.\nفالواجب على من يتولى عقد النكاح أن يطلب حضور الشاهدين وحضور الزوج وولي المرأة، ثم يجري عقد النكاح حتى يخرج من خلاف العلماء، وحتى يكون العقد صحيحاً عند جميع أهل العلم.\nوأما ما مضى من العقود فإذا كان عن فتيا عالم من العلماء أقر، أما إن كان عن تساهل فينبغي تجديده، يجدد النكاح من جديد بشروطه الشرعية بولي وشاهدين يحضران العقد الجديد، وأولادهم السابقون لاحقون بهم للشبهة، أولادهم لاحقون بهم، والماضي عليهم التوبة منه من التساهل، والأولاد لاحقون بأبيهم من أجل الشبهة، ولكن يجدد النكاح عملاً بالأدلة الشرعية، وعملاً بما رآه جمهور أهل العلم، وحرصاً على سلامة الذمة وبراءتها من الخطر، وهناك شيء أيضاً يقع في بعض البلاد وهو التساهل بعدم وجود الولي وأنها تزوج نفسها فقط وهذا غلط في أصح قولي العلماء، لقول النبي ﷺ: لا نكاح إلا بولي ولقوله ﷺ: لا تزوج المرأة نفسها ولا غيرها فليس لها أن تزوج نفسها ولا غيرها، بل يجب على الولي أن يتولى الزواج وهو أبوها ثم جدها الأقرب فالأقرب ثم ابنها وأبناء ابنها الأقرب فالأقرب، ثم إخوتها الأشقاء والإخوة لأب كالميراث، أما التساهل في هذا فهو غلط، ولا ينبغي أن يؤخذ بكل خلاف، الخلاف الذي لا يوافق الدليل لا ينبغي الأخذ به، معلوم أن هناك خلاف في اشتراط الولي والشاهدين لكن ليس كل خلاف يعتبر، بل ينبغي للمؤمن أن يتحرى ما قام عليه الدليل وأن يتحرى أيضاً البعد عن الخلاف، وأن تكون عقوده وأعماله بعيدة عن الخلاف، وأن يتحرى فيها موافقة الشرع المطهر، وقد صح عن رسول الله ﷺ أن قال: لا نكاح إلا بولي، ونهى أن تزوج المرأة المرأة أو تزوج نفسها فوجب على المؤمنين أن يمتثلوا، وأن يتولى الولي تزويج موليته وهو أبوها إن وجد أو جدها أبو أبيها إن وجد الأقرب فالأقرب، فإن لم يوجد فابنها فإن لم يوجد فابن ابنها، فإن لم يوجد لها آباء ولا أبناء فإخوتها وهكذا كالميراث، ولابد من إذنها سواء كانت بكراً أو ثيبا مع إحضار الشاهدين للعقد، نسأل الله للجميع الهداية والتوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/7804/حكم-عقد-النكاح-بدون-الشاهدين-او-بدون-ولي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25011.mp3","categories":["شروط وأركان الزواج"]},{"id":9656,"question":"السؤال الخامس يقول فيه: شاب مسلم يريد الزواج من فتاة مسلمة ولكن أباها دائمًا يتعاطى السكر وملحد، هل يجوز عقد ذلك الأب لابنته أفيدونا أفادكم الله؟","title":"حكم ولاية الأب الملحد على ابنته","answer":"الجواب: إذا كانت مسلمة فلا بأس أن يتزوجها الشاب المسلم، لكن لا يكون أبوها وليًا لها إذا كان ملحدًا كافرًا شيوعيًا أو إباحيًا كافرًا فإنه لا يكون وليًا لها ولكن يزوجها أخوها إن كان لها أخ طيب أو عمها أو ابن عمها أو ابن أخيها إذا كان لها أقارب طيبين مسلمين زوجها أقربهم إليها، فإن لم يوجد أحد غير الأب زوجها القاضي ، يرفع الأمر إلى القاضي والقاضي يزوجها إلا إذا وجد لها أقارب غير الأب مسلمون كأخ أو عم أو ابن أخ؛ الأقرب فالأقرب الأخ أقرب ثم ابن الأخ ثم العم يعني الأقرب بعد الأب يزوجها. نعم.","link":"https://binbaz.org.sa/fatwas/7822/حكم-ولاية-الاب-الملحد-على-ابنته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19412.mp3","categories":["شروط وأركان الزواج"]},{"id":9760,"question":"عرفونا صيغة عقد الزواج بالتفصيل؛ لأن الناس عندنا يسمونه الفاتحة، ولا يعرفون عنه شيئاً؟ جزاكم الله خيراً.","title":"صفة عقد النكاح","answer":"الجواب: عقد النكاح أن يقول الولي أبوها أو أخوها، الأقرب، أقرب عصبتها، وأقربهم الأب ثم الابن ثم الأخ الشقيق، ثم الأخ لأبي.. إلى آخره، يقول للزوج: زوجتك ابنتي إن كانت بنته، أو أختي إن كانت أخته، أو أمي إن كانت أمه، زوجتك فلانة، بنتي أو أمي أو أختي، وهو يقول: قبلت هذا الزواج، هذا هو صفة العقد، يقول: زوجت، أو ملكتك، أو وهبتك يجزي حتى قول وهبتك، المهم المعنى، أو ملكتك بأي لغة يفهمونها قالها الولي، ويقول الزوج: قبلت هذا الزواج، قبلت هذا النكاح ورضيته، إذا قال لك تم العقد، إذا كانت الزوجة خالية من الموانع، والزوج خالي من الموانع.\nفإن كانت هناك علة كأن تكون الزوجة محرمة أو الزوج محرم، ما يصح النكاح، حال الإحرام، أو كانت في العدة، ما بعد خرجت من عدة الزوج الذي طلقها أو مات عنها، فالنكاح غير صحيح، أو كان الزوج كافر وهي مسلمة لا يصح النكاح، لا بد من توافر الشروط و انتفاء الموانع، فإذا توافرت الشروط وانتفت الموانع فالولي يقول للزوج: زوجتك بنتي أو أختي أو أمي .. نحو ذلك، والزوج يقول: قبلت: بحضرة شاهدين عدلين، يشهدان هذا العقد.\nفالعقد يحضره أربعة الزوج والولي والشاهدان.\nوالأفضل أن يكون قبله خطبة خطبة النكاح هذا الأفضل وهي: (إن الحمد لله، نحمده ونستعينه ونستغفره، ونعوذ بالله من شرور أنفسنا ومن سيئات أعمالنا، من يهده الله فلا مضل له، ومن يضلل فلا هادي له، وأشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمد عبده ورسوله)، ثم يقرأ قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ [آل عمران:102]، يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا [النساء:1]، وقوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا ۝ يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا [الأحزاب:70-71]، بعد هذا يقول: زوجتك، يقوله الولي، والزوج يقول: قبلت، بعد هذه الخطبة، سنة هذه الخطبة مستحبة يقرؤها الولي، أو يقرؤها الزوج، أو يقرؤها من يحضرهما من الشاهدين أو غيرهما، أو يقرؤها المأذون الذي يتزوجون عنده المأذون أو القاضي الذي يتزوجون عنده، إذا قرأها واحد من الحاضرين، الزوج أو الولي، أو المأذون، أو أحد الشاهدين حصل المطلوب.\nوتسمى خطبة الحاجة لكن ليست شرطاً، لو قال: زوجت، وقال الزوج: قبلت، ولا أتى بالخطبة لا حرج الزواج صحيح، إذا كان بحضرة الشاهدين، وكانت الشروط متوفرة والموانع منتفية، فالحمد لله، لكن تركوا الأفضل، الأفضل أن يكون العقد بعد هذه الخطبة التي سمعتم، نعم.\nالمقدم: جزاكم الله خيراً، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/7935/صفة-عقد-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_257/25709.mp3","categories":["شروط وأركان الزواج"]},{"id":9806,"question":"وله استفسار ثان في رسالته، يقول فيه: خطبت فتاة في العشرين من عمرها، وقد قدمت لي مساعدة في أزمة مرضية حيث ساعدتني بدم من دمها قبل الخطوبة، فهل يصح لي أن أتزوجها، أفتونا جزاكم الله خيرًا؟","title":"حكم زواج الرجل ممن تبرعت له بدمها","answer":"الجواب: الدم لا يؤثر، ليس مثل الرضاع، كون المرأة تزود الرجل من دمها أو الرجل يزود المرأة من دمه عند الحاجة إلى ذلك ليس له حكم الرضاع، فلا تحرم عليه ولا يحرم عليها، بما يحصل من الانتفاع بالدم الذي يحتاج إليه المريض، هذا ليس له حكم الرضاع، بل هو أمر خارج عن ذلك، من باب الإحسان ولا يمنع الزواج. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7973/حكم-زواج-الرجل-ممن-تبرعت-له-بدمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_197/19705.mp3","categories":["شروط وأركان الزواج"]},{"id":9814,"question":"وهذه رسالة وردت إلى البرنامج من المرسل (ع. أ. ع) صومالي مقيم في مدينة الرياض يقول السائل في رسالته: هل يجوز لامرأة مسلمة أن تذهب مع رجل أجنبي وقد اتفقا على الزواج، سواء رفض والدها أم وافق، وفي حالة رفض الوالد لسبب ما فيذهب الاثنان إلى منطقة بعيدة مسافة القصر، وهناك يتم عقد النكاح، وكلنا نعلم أن الخلوة الأولى حرام أفيدونا أفادكم الله؟","title":"حكم سفر المرأة مع خطيبها والزواج بدون إذن الولي","answer":"الجواب: هذا العمل لا يجوز، ليس للرجل أن يسافر بامرأة ليست محرماً له، ولو كان خاطباً لها، وهذا السفر وهذه الخلوة متهمان فيها، فلا يجوز أبداً لا يخلو بها ولا يسافر معها، بل يجب عليه الحذر من ذلك وعليها الحذر من ذلك، وليس لها الزواج إلا بوليها، النبي عليه السلام قال: «لا نكاح إلا بولي» فليس لها أن تزوج بالشخص لا بعد ذهابها مسافة قصر ولا في غير ذلك إلا بالولي، وهو أبوها أو من يوكله أبوها ممن يصلح للوكالة، وأما سفرها مع خاطبها قبل الزواج قبل العقد فهذا لا يجوز، وليس لها أن تسافر معه إلا بإذن أهلها ولو بعد العقد، إلا بإذن أهلها حتى لا يكون هناك شيء مما تسوء عاقبته.\nفالحاصل: أن سفرها مع هذا الخاطب أمر منكر ولا يجوز، وهو من وسائل الفاحشة، وليس لها التزوج إلا بإذن وليها، فإذا أبى وليها أن يزوجها ففي إمكانها أن تطلب من المحكمة النظر في الأمر، أما أن تزوج نفسها فهذا ليس إليها، وليس للخاطب أن يسافر بها أو يخلو بها أو يلجئها إلى الزواج به من غير وليها، كل هذا منكر. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7981/حكم-سفر-المراة-مع-خطيبها-والزواج-بدون-اذن-الولي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26002.mp3","categories":["النظر والخلوة والاختلاط","شروط وأركان الزواج"]},{"id":9937,"question":"هذه رسالة من السودان من قرية الشنة من السائل عبدالقادر فضل محمد زين يقول: هل يجوز للولي أن يوكل من ينوب عنه في تزويج موليته إذا كان هو حاضر كالخال مثلًا؟","title":"حكم توكيل الولي من ينوب عنه في تزويج موليته","answer":"الجواب: لا بأس، يزوِّج، من ينوب عنه مثل أبي المرأة يوكِّل خالها، يوكل أحد أولاده المُرْشِدين ينوبون عنه في التزوج؛ لا بأس، لا بأس أن يوكل الولي من  ينوب عنه في تزويج ابنته أو أخته أو بنت أخيه، يوكل من هو صالح للزواج إن كان مرشدًا كخالها المرشد، كأخيها كعمها المرشد، لا بأس.\nوهكذا الزوج له أن يوكِّل، الزوج نفسه له أن يوكل من يقبل عنه النكاح، يوكل أباه يوكل أخاه، يتقبل تزوجه من فلانة فيقول: قبلت هذا الزواج لأخي فلان أو لعمي أو لابن أخي أو لولدي؛ لا بأس؛ فالوكالة جائزة من الولي ومن الزوج نفسه.\nالمقدم: مع حضوره يعني.\nالشيخ: مع حضوره وغيبته.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8103/حكم-توكيل-الولي-من-ينوب-عنه-في-تزويج-موليته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19910.mp3","categories":["شروط وأركان الزواج"]},{"id":10238,"question":"يقول فتاة في العقد الثاني من عمرها، تقدم لها رجل قد مضى من عمره خمسون عاماً، هل تتزوج من هذا الرجل أو لا؟","title":"حكم تزويج الفتاة بمن يكبرها سناً","answer":"","link":"https://binbaz.org.sa/fatwas/8408/حكم-تزويج-الفتاة-بمن-يكبرها-سنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27812.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":10350,"question":"الزواج بغير موافقة الوالد؟","title":"الزواج بغير موافقة الوالد","answer":"الجواب: المشروع للمؤمن أن يتحرى موافقة الوالد لأن بره من الواجبات، وكذلك الوالدة تشاورهم .... لأن الوالد ما بداله والد والمرأة بدالها مرأة النساء كثير والولد كذلك، فإذا وجد امرأة صالحة طيبة فلا مانع من أن يستشير الوالد ويكثر عليه في ذلك ويطلب من الإخوان الطيبين أن يشيروا عليه حتى يوافق؛ لأن المرأة الصالحة ما ينبغي ردها ولا ينبغي تركها، ولا ينبغي لوالده أن يمنعه من ذلك ولا حرج في الزواج بها ولو لم يرض الوالد لقوله ﷺ: إنما الطاعة في المعروف، والزوجة الصالحة من المعروف، لكن مهما استطاع أن يرضيه أو يلتمس امرأة صالحة غيرها حتى لا تفوت الفرصة فهذا هو الأولى جمعاً بين المصلحتين، بين بره وبين تحصيل المرأة الصالحة مهما أمكن فإن لم يتيسر ذلك وخاف فوتها وهي امرأة صالحة مشهود لها بالخير فلا حرج عليه إن شاء الله في الزواج بها وإن لم يرض والده، وفي إمكان والده بعد ذلك أن يرضى والغالب أن الوالد الطيب لا يكره المرأة الصالحة، فإذا كرهها فلا بد أن هناك شيئاً أوجب الكراهة.\nفلا ينبغي للولد أن يعجل بل ينبغي له أن يتريث ويعرف الأسباب ويستعين على رضا والديه إذا كان ما هناك أسباب تمنع من زواجها يستعين عليه بأعمامه وإخوانه وجيرانه الطيبين حتى يرضى إن شاء الله، لا يعجل في الزواج بغير رضاه مهما أمكن إلا بعد الطمأنينة إلى أنه ليس هناك ما يمنع الزواج وأنه تعنت من أبيه لأن أباه رجل غير صالح لا يريد الصالحات فهذا خطأ عظيم. نعم.","link":"https://binbaz.org.sa/fatwas/8534/الزواج-بغير-موافقة-الوالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_316/31613.mp3","categories":["الآداب والأخلاق المحمودة","شروط وأركان الزواج"]},{"id":10393,"question":"سوداني مقيم بالعراق هو (د. ح. ج. أ) بعث برسالة ضمنها سؤالين، في سؤاله الأول يقول: تقدمت إلى فتاة أريد أن أتزوجها ولكن والد الفتاة رجل لا يصلي، والأخطر من ذلك أنه رجل مدمن على شرب الخمر، ولذلك فإن الفتاة التي تقدمت إليها لا تصلي -أي: بنت هذا الرجل المدمن على الخمر- هل يجوز أن أتزوج بها أم لا؟","title":"هل يجوز الزواج بامرأة لا تصلي؟","answer":"الجواب: ليس لك أن تتزوج بها حتى تصلي؛ لأن ترك الصلاة كفر، كما قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة.\nفالمقصود: أن الصلاة عمود الإسلام، وهي الركن الثاني من أركان الإسلام الخمسة، وهي أعظم الأركان بعد الشهادتين، فمن تركها جاحدًا لها كفر بإجماع المسلمين، ومن تركها تهاونًا وتكاسلًا كفر في أصح قولي العلماء، سواء كان رجلًا أو امرأة.\nفلا ينبغي لك ولا يجوز لك أن تنكحها وهي بهذه الحال وأنت مسلم تصلي وتصوم وتخاف الله، ليس لك أن تزوجها، حتى تتوب إلى الله وحتى تستقيم على الصلاة.\nوهكذا المرأة ليس لها أن تزوج الرجل الذي لا يصلي إذا علمت أنه لا يصلي، فإنها لا يحل لها أن تقبله ولا أن ترضى بالعقد عليه، وإذا ترك الصلاة وجب عليها الامتناع منه حتى يتوب إلى الله، فإذا تاب إلى الله وهي في العدة فهو زوجها أو بعد العدة ولم تفسخ منه فهي زوجته على الصحيح، لكن بعد العدة لها أن تطالب بالفسخ منه وتأخذ حقها حتى تزوج من شاءت؛ لأن ترك الصلاة ردة عن الإسلام في أصح قولي العلماء، ولو لم يجحد وجوبها.\nوذهب جملة من أهل العلم: إلى أنه إذا لم يجحد وجوبها لم يكن كافرًا كفرًا أكبر بل يكون كفره كفرًا أصغر، ولكن هذا القول مرجوح، والصواب: أنه كفر أكبر لأنها عمود الإسلام، وقد أطلق النبي ﷺ كفر تاركها عليه الصلاة والسلام فقال: بين الرجل وبين الكفر والشرك ترك الصلاة والكفر المعرف بأل والشرك المعرف بأل يرجع إلى الكفر الأكبر.\nوقال أيضًا عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال في الأئمة الذين لا يصلون لما سئل ﷺ عن الأمراء الذين لا يصلون.. سئل عن الأمراء الذين يؤخرون الصلاة عن أوقاتها، أو تعرف منهم وتنكر من المعاصي، نهى عن قتالهم والخروج عليهم، قال: إلا أن تروا كفرًا بواحًا عندكم من الله فيه برهان وفي الرواية الأخرى قال: ما أقاموا فيكم الصلاة فدل على أنهم إذا لم يقيموا الصلاة فقد أتوا كفرًا بواحًا.\nوالمقصود من هذا: أن ترك الصلاة كفر بواح كما بينه النبي عليه الصلاة والسلام، فالواجب على المسلمين الحذر من هذا التهاون والحرص على المحافظة على الصلاة في أوقاتها، والرجل يحرص على أدائها في الجماعة في مساجد الله، والمرأة تصليها في بيتها، ولا يجوز أبدًا التأسي بمن تركها، أو الاقتداء به، بل يجب الحذر من ذلك، فهي عمود الإسلام من حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع.\nوكان عمر بن الخطاب  يكتب إلى عماله ويقول: «إن أهم أمركم عندي الصلاة، فمن حفظها فقد حفظ دينه ومن ضيعها فهو لما سواها أضيع » وذكر النبي ﷺ الصلاة يومًا بين أصحابه فقال: من حافظ عليها كانت له نورًا وبرهانًا ونجاة يوم القيامة، ومن لم يحافظ عليها لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف وهؤلاء الكفرة شغلتهم دنياهم عن طاعة الله وعبادته، فمن ترك الصلاة فقد شابه هؤلاء فيحشر معهم نعوذ بالله، فإن كان تركها لأجل الرياسة شابه فرعون فيحشر معه يوم القيامة، وإن كان تركها من أجل الوزارة شابه هامان وزير فرعون فيحشر معه يوم القيامة، إلى النار نسأل الله العافية، أما إن كان تركها من أجل المال والشهوات فإنه يشبه قارون الذي شغله ماله وشهواته عن اتباع الحق حتى خسف الله به وبداره الأرض نعوذ بالله من ذلك، أما إن كان تركها لأجل البيع والشراء وتصريف التجارة فإنه شبيهًا بـأبي بن خلف ، تاجر أهل مكة فإنه شغله البيع والشراء والتجارة عن طاعة الله ورسوله، وعن اتباع النبي محمد عليه الصلاة والسلام، فيكون من ترك الصلاة تشاغلًا بالتجارة شبيهًا بهذا نسأل الله العافية، فيحشر معه يوم القيامة نعوذ بالله من ذلك.\nفالواجب الحذر، ومن المصائب العظيمة كثرة من يتركها الآن ويتساهل بها، إما بالكلية وإما في المساجد، وهذا بلاء عظيم وشر كبير، ومنكر عظيم، فالواجب الحذر من ذلك، والواجب التواصي بفعلها والاستقامة عليها بين أهل البيت من الرجال والنساء يجب التواصي بذلك والتعاون في ذلك، حتى يقيم الرجل الصلاة هو وأهله وزوجته وأولاده وخدمه، لا يتساهل في هذا، بل يجب أن يكون قدوة صالحة لزوجته وأولاده وخادمه وسائقه ونحو ذلك، فالصلاة عمود الإسلام من حفظها حفظ دينه ومن ضيعها فهو لما سواها أضيع، والله يقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول : وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] والآيات فيها كثيرة وهكذا الأحاديث لعظم شأنها نسأل الله لنا ولجميع المسلمين الهداية.\nالسؤال: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8565/هل-يجوز-الزواج-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/339014.mp3","categories":["حكم الصلاة وأهميتها","شروط وأركان الزواج"]},{"id":10529,"question":"هذه سائلة من الأردن رمزت لاسمها بـ (ز. هـ. م) تقول في هذا السؤال سماحة الشيخ: تذكر بأنها طالبة تقدم لخطبتها رجل صاحب دين، وطلبت التأجيل ريثما تقدم الامتحانات النهائية، ثم تقدم آخر صاحب دين فرفض والدها وصمم على زواجها من قريب لها تارك للصلاة، فأجبرت واستخارت الله وفوضت أمرها إلى الله  طاعة لوالدها، وتزوجت هذا الرجل لكنه ثبت أنه لا يصلي، ولم يستجب لتوجيهها تقول: فانفصلت عنه؛ لأنها أصرت عليه أن يصلي فرفض أن يصلي.والآن تقول: كلما تقدم لخطبتها رجل ما لا يحصل نصيب، فقال لها أحد الإخوة: بأنك فتنت في دينك، حيث لم تستجب لقول الرسول ﷺ: إذا أتاكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوا تكن فتنة في الأرض وفساد كبير تقول: فالفتنة هنا هو عدم توفيقي بالزواج؛ لأنني رفضت صاحب الدين مرات متتالية، هل هذا هو مصيري؟ تقول: ماذا أفعل سماحة الشيخ؟ هل أنا حقاً مفتونة رغم أني عاهدت الله  أن لا أقبل إلا بصاحب دين ويصلي وذو خلق مهما كانت الضغوط، أرجو من سماحة الشيخ الإجابة؟","title":"حكم رفض ولي المرأة تزويج صاحب الخلق والدين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفلا شك أن الواجب على المؤمنة الاستجابة لله وللرسول فيما يتعلق بالزواج وغيره، أما الخاطبان السابقان اللذان يرضى دينهما وأمانتهما فلا شك أن الزواج من أحدهما كان هو المناسب هو الذي ينبغي، للحديث الذي ذكرته السائلة: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه لكن إذا كان عدم التزويج من أجل والدها وأنه أبى وامتنع من تزويجها عليهما فهذا الإثم على والدها لا عليها؛ لأنها لم تقصر هي، أما إن كانت هي التي رفضت فعليها التوبة، عليها التوبة والرجوع إلى الله والإنابة ومن تاب تاب الله عليه سبحانه وتعالى.\nوأما تزوجها بالذي لا يصلي فهو غلط من أبيها، وغلط منها؛ لأن الذي لا يصلي كافر نسأل الله العافية، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر والصواب أنه كفر أكبر، هذا هو الراجح من قولي العلماء أنه كفر أكبر.\nفإذا كانت قد تخلصت منه فالحمد لله، وإلا فالواجب عدم رجوعها إليه، وأن ترفع أمرها إلى المحكمة حتى تخلصها المحكمة منه بخلعها منه؛ لأنه لا يجوز لها العود إليه وهو تارك للصلاة، ونسأل الله أن يسهل لها الزوج الصالح، وأن يخلصها من هذا الذي يترك الصلاة إن كان لم يطلق. نعم.\nالمقدم: جزاكم الله خيراً سماحة الشيخ، سماحة الشيخ! هل هناك توجيه للآباء الذين يردون الأزواج الصالحين؟\nالشيخ: نعم، الواجب على الولي أن يختار لموليته الرجل الصالح، وأن لا يرد الرجل الصالح لأجل القرابة أو غيرها، بل يجب أن يختار من يرضى دينه وخلقه وإن كان ليس بقريب، هذا هو الواجب على الولي من أب وغيره، والواجب على المرأة أيضًا أن تجتهد في قبول الخاطب الطيب المعروف بدينه وخلقه الطيب، وأن لا تقبل الزواج على من لا يرضى دينه ولا خلقه وإن كان قريبًا، نعم.","link":"https://binbaz.org.sa/fatwas/8704/حكم-رفض-ولي-المراة-تزويج-صاحب-الخلق-والدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28401.mp3","categories":["شروط وأركان الزواج"]},{"id":10649,"question":"السائل: (أحمد . أ. أ) يقول: سمعنا يا سماحة الشيخ! بأن الزواج من الأقارب فيه محذور، وأنا أريد أن أزوج أحد أبنائي فهل ورد حديث بذلك؟ جزاكم الله خيرًا.","title":"حكم الزواج من الأقارب","answer":"الجواب: لا، ليس فيه محذور اللي قاله غلط، ليس في الزواج من الأقارب محذور بل طيب، النبي ﷺ تزوج من أقاربه، أم سلمة من أقاربه، عائشة من أقاربه أم حبيبة من أقاربه كلهم من قريش، كلهم من جماعته عليه الصلاة والسلام، لا حرج في ذلك، وعلي تزوج فاطمة بنت النبي ﷺ وهي بنت عمه عليه الصلاة والسلام، وعثمان تزوج بنت النبي ﷺ، تزوج بنتيه رقية وأم كلثوم ، وأبو العاص بن الربيع تزوج بنت النبي الرابعة عليه الصلاة والسلام زينب كلهم بنو عم، لا حرج في هذا، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8826/حكم-الزواج-من-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28511.mp3","categories":["شروط وأركان الزواج"]},{"id":10810,"question":"سؤال آخر يقول فيه: رجل تزوج من امرأة، وطلقها بعد أن دخل بها لعدم إنجاب الأطفال، ثم تزوجت من آخر وهو تزوج من أخرى، وكل منهما أنجب الأطفال، هل يجوز شرعًا لابنه الزواج من ابنة امرأته السابقة التي طلقها، ولم تنجب أو العكس؟ أجيبونا جزاكم الله خيرًا.","title":"حكم الزواج بين أبناء رجل وبنات مطلقته من رجل آخر","answer":"الجواب:  نعم لا بأس، كون أولاده من الزوجة الجديدة، يعني أبناؤه يتزوجون من بنات الزوجة -زوجة أبيهم سابقًا- من زوجها الأخير لا بأس بذلك، هذا لا يضر، لكن هو لا يأخذ من بناتها شيئًا؛ لأنهم ربائب، الزوج الذي طلقها لا يجوز أن يتزوج من بناتها؛ لأنهم ربائب، ولو من الزوج الأخير، أو من زوج سابق، أما أولاده فلا بأس، إذا لم يكن هناك رضاعة تمنع فإنه لا بأس أن يتزوج من بنات زوجة أبيه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8984/حكم-الزواج-بين-ابناء-رجل-وبنات-مطلقته-من-رجل-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35306.mp3","categories":["شروط وأركان الزواج"]},{"id":11137,"question":"بعد هذا رسالة يقول: رجل تزوج من فتاة ثم طلقها، وتزوجت بآخر ويريد أن يتزوج أختها، قال له بعض الناس: هذا حرام! فهل ما قيل صحيح، أو يجوز أن يتزوج بأخت مطلقته؟","title":"حكم الزواج بأخت الزوجة المطلقة","answer":"الجواب:  إذا طلق الإنسان امرأة واعتدت جاز له أن يتزوج أختها وعمتها وخالتها، بعد خروجها من العدة، وهذه قد اعتدت وتزوجت فلا حرج عليه أن يتزوج أختها، إذا لم يكن بينهما رضاع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9319/حكم-الزواج-باخت-الزوجة-المطلقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_369/36919.mp3","categories":["شروط وأركان الزواج"]},{"id":11295,"question":"بعد هذا رسالة وصلت إلى البرنامج من مستمع رمز إلى اسمه بالحروف (ف. ع. ح) مقيم في المملكة، يقول: هل يجوز الزواج من بنت عم والدي وما حكم الإسلام في ذلك، علمًا بأنني متزوج من بنت عم أبي من عشر سنوات وأكثر، ومنجب منها ثلاثة أولاد وبنت، هل زواجي صحيح أم باطل؟ جزاكم الله خيرًا. الشيخ: أعد.المقدم: يقول: هل يجوز الزواج من بنت عم والدي، وما حكم الإسلام في ذلك، علمًا بأنني متزوج من بنت عم أبي من عشر سنوات وأكثر ومنجب منها ثلاثة أولاد وبنت، هل زواجي صحيح أم باطل؟","title":"حكم الزواج من بنت عم الأب","answer":"الجواب:  نعم الزواج صحيح والحمد لله، الزواج ببنت العم، وبنت عم الأب، وبنت عم الجد، وبنت الخال، وبنت خال الأم وبنت خال الجدة أو الجد كله لا بأس به، كلهن مباحات، يباح الزواج منهن، بنت خالك، بنت عمك، بنت خال أمك، بنت عم أمك، بنت عم أبيك، بنت خال أبيك، كلهن حلال، الزواج منهن حلال. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9472/حكم-الزواج-من-بنت-عم-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37604.mp3","categories":["شروط وأركان الزواج"]},{"id":11316,"question":"يقول: هل من حق الفتى أن يختار شريكة حياته بنفسه أم والداه هما اللذان يجبرانه على أن يأخذ فتاة معينة، فمثلًا والدي يصر على أن يزوجني من ابنة عمي وليس لي رغبة فيها، هل عدم طاعة الوالدين في هذه الحالة تعتبر من العقوق؟ جزاكم الله خيرًا، وصاحب هذه الرسالة هو المستمع (ف. ع. ق) من مصر ... ؟","title":"حكم طاعة الولد والديه في الزواج ممن لا يرغب","answer":"الجواب:  لا يلزمك؛ لأن النكاح أمره عظيم، فإذا كانت المرأة لا تناسبك فإنه لا يلزمك إنما الطاعة في المعروف. لكن تستسمح والديك بالكلام الطيب والأسلوب الحسن حتى تلتمس أنت ووالداك امرأة تناسبك، فإن الزواج من امرأة لا تناسبك ولا تريدها يضر ولا ينفع خسارة. فالواجب على والديك ألا يجبراك على امرأة لا تريدها، والواجب عليك أن تستسمحهما وتستعمل معهما الرفق بالكلام الطيب حتى لا يقع بينك وبينهما شيء من العقوق والفرقة والاختلاف، نعم.  المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9495/حكم-طاعة-الولد-والديه-في-الزواج-ممن-لا-يرغب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37706.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":11590,"question":"بعد هذا رسالة وصلت إلى البرنامج من جمهورية مصر العربية، تقول المرسلة (م. م. أ) تقول: إنها شابة في منتصف العمر، أجبرها أهلها على الزواج من ابن عمها، وهي في الواقع قد أبدت لهم الرغبة في أنها لا تريد هذا الرجل، لكنهم اضطروها على ذلك، وأدخلوه عليها رغمًا عنها كما تقول، وحينئذ بدأت بالمعاناة، وبدأت تطلب الطلاق، فهل عليها من إثم في ذلك؟ جزاكم الله خيرًا.","title":"حكم من أجبرها أهلها على الزواج بابن عمها","answer":"الجواب:  الواجب عليها السمع والطاعة لوالديها في المعروف إذا استطاعت ذلك، فإذا لم تستطع؛ فهذا شيء يتعلق بها، هي أعلم بنفسها، ترفع أمرها إلى المحكمة، وفيما تراه المحكمة الكفاية، إن شاء الله. أما إن كانت دخلت برضاها لما شدد عليها؛ وافقت؛ فليس لها بعد ذلك أن تغير، بل عليها أن تصبر، وتحتسب، إلا إذا كان أمر لا تطيقه، هذا يعود إلى المحكمة، ترفع أمرها إلى المحكمة، والمحكمة فيها الكفاية -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9773/حكم-من-اجبرها-اهلها-على-الزواج-بابن-عمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38619.mp3","categories":["شروط وأركان الزواج"]},{"id":11849,"question":"رسالة بعثت بها إحدى الأخوات، تقول فيحاء: أختنا رسالتها من صفحة كاملة، ملخصها أن والدها يريد أن يزوجها برجل تقول: هو في عمر أبي، أو أكبر، وقد رفضت ذلك الزواج، ولا أريده، وتعقب على ذلك وتقول: لا تقل لي تزوجي ذلك الرجل يا سماحة الشيخ؛ لأن هذا مستحيل مستحيل، ولن أتزوجه مهما بقيت على قيد الحياة، فبماذا تنصحون والدي، ومن حذا حذوه؟ جزاكم الله خيرًا.","title":"حكم إجبار الوالد ابنته على الزواج","answer":"الجواب:  ننصح والدك وأعمامك وإخوانك بأن يتقوا الله، وأن يلتمسوا لك شابًا مناسبًا من أهل الخير والإيمان، أما إلزامك بالرجل الكبير أو بغيره؛ فلا يجوز، حتى ولو كان شابًا، ليس لهم أن يلزموك، لقول النبي ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن قالوا: يا رسول الله! كيف إذنها؟ قال: أن تسكت وفي الحديث الآخر يقول ﷺ: والبكر يستأذنها أبوها، وإذنها سكوتها. فالواجب على أبيك أن يتقي الله، وأن يرحمك، وألا يزوجك إلا بإذنك، سواءً كان الزوج كبيرًا، أو شابًا، ليس لأبيك، ولا لإخوانك، ولا لأعمامك أن يزوجوك إلا بمن ترضين من أهل الخير والاستقامة، هذا هو الواجب عليهم، وليس لهم جبرك على كبير، أو صغير، نسأل الله لنا ولهم الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم، سماحة الشيخ! بعض الناس تعمي بصائرهم المادة والفلوس، هل من كلمة؟ الشيخ: لا يجوز لهم، الواجب على المؤمن أن يتقي الله، وألا تغره المادة، وألا يكون حظه الطمع من أجل إضرار بنته، أو أخته، فالواجب أن يتقي الله، وأن يلتمس لبنته وأخته ونحوهما الرجل الطيب، الرجل المؤمن، الرجل الخير، قليل المشاكل، وألا يكون همه الطمع، أن يلتمس ذا المال حتى يعطيه مالًا، هذا لا يجوز، هذه أمانة، يجب أن يتقي الله في هذه الأمانة، وأن يلتمس لها الرجل الصالح الطيب، حسن السمعة، حسن الدين؛ حتى يزوجها برضاها، وموافقتها، ولو بمهر قليل، مهر قليل لرجل صالح خير من مهر كثير لرجل غير صالح. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10036/حكم-اجبار-الوالد-ابنته-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39616.mp3","categories":["شروط وأركان الزواج"]},{"id":11932,"question":"عرفونا صيغة عقد الزواج بالتفصيل؛ لأن الناس عندنا يسمونه الفاتحة ولا يعرفون عنه شيئاً جزاكم الله خيرا؟","title":"صيغة عقد النكاح الشرعي","answer":"الجواب: عقد النكاح أن يقول الولي -أبوها أو أخوها الأقرب أقرب عصبتها، وأقربهم الأب ثم الابن ثم الأخ الشقيق ثم الأخ لأب إلى آخره- يقول للزوج: زوجتك ابنتي، إن كانت بنته أو أخته إن كانت أخته أو أمه إن كانت أمه زوجتك فلانة بنتي أو أمي أو أختي، وهو يقول: قبلت هذا الزواج، هذا هو صفة العقد، يقول: زوجت أو ملكتك أو وهبتك يجزي حتى ... العقد المهم المعنى أو ملكتك بأي لغة يفهمونها قالها الولي و يقول الزوج: قبلت هذا الزواج قبلت هذا النكاح ورضيته، إذا قال لك تم العقد، إذا كانت الزوجة خالية من الموانع والزوج خالي من الموانع، فإن كانت هناك علة كأن تكون الزوجة محرمة أو الزوج محرم ما يصح النكاح حال الإحرام أو كانت في العدة ما بعد خرجت من عدة الزوج الذي طلقها أو مات عنها فالنكاح غير صحيح، أو كان الزوج كافر وهي مسلمة لا يصح النكاح لابد من توافر الشروط وانتفاء الموانع، فإذا توافرت الشروط وانتفت الموانع فالولي يقول للزوج: زوجتك بنتي أو أختي أو أمي أو نحو ذلك والزوج يقول: قبلت بحضرة شاهدين عدلين يشهدان على العقد، فالعقد يحضره أربعة الزوج والولي والشاهدان، والأفضل أن يكون قبله خطبة خطبة النكاح هذا الأفضل وهي: إن الحمد لله نحمده ونستعينه ونستغفره ونعوذ بالله من شرور أنفسنا ومن سيئات أعمالنا من يهده الله فلا مضل له ومن يضلل فلا هادي له، وأشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمد عبده ورسوله، ثم يقرأ قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ [آل عمران:102]، يَا أَيُّهَاا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالأَرْحَامََ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا [النساء:1]، وقوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا ۝ يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا [الأحزاب: 70 -71]، بعد هذا يقول: زوجتك يقول الولي، والزوج يقول: قبلت بعد هذه الخطبة، سنة هذه الخطبة مستحبة يقرؤها الولي أو يقرؤها الزوج أو يقرؤها من يحضرهما من الشاهدين أو غيرهما، أو يقرأها المأذون الذي يتزوجون عنده المأذون أو القاضي الذي يتزوجون عنده، إذا قرأها واحد من الحاضرين الزوج أو الولي أو المأذون أو أحد الشاهدين حصل المطلوب وتسمى خطبة الحاجة لكن ليست شرطًا لو قال: زوجتك وقال الزوج: قبلت ولا أتى بالخطبة لا حرج الزواج صحيح إذا كان بحضرة الشاهدين وكانت الشروط متوفرة والموانع منتفية فالحمد لله لكن تركوا الأفضل، الأفضل أن يكون العقد بعد هذه الخطبة التي سمعتم. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10116/صيغة-عقد-النكاح-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42709.mp3","categories":["شروط وأركان الزواج"]},{"id":12065,"question":"هل من بر الوالدين طاعتهم في الزواج من امرأة اختاروها لي، لا أرغب الاقتران بها؟","title":"حكم إجبار الوالدين ولدهما على الزواج بفتاة لا يرغبها","answer":"الجواب:  الزواج لابد فيه من الرغبة، الله يقول -جل وعلا-: وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُمْ مِنْ أَنفُسِكُمْ أَزْوَاجًا لِتَسْكُنُوا إِلَيْهَا وَجَعَلَ بَيْنَكُمْ مَوَدَّةً وَرَحْمَةً [الروم:21]، فإذا كانت المرأة المخطوبة لا تناسبك، ولا ترضاها، ولا ترغب فيها؛ لم يلزمك طاعة والديك في ذلك؛ لأن هذا شيء يخصك، وأنت أعلم بنفسك، ولا يجوز لهما إلزامك بامرأة تكرهها، هذا لا يجوز لهما، والله -جل وعلا- أوجب عليهما الإنصاف والعدل، فليس لهما إجبارك على ما يضرك، وأنت أيضًا لا يلزمك طاعة الوالدين في غير المعروف: إنما الطاعة في المعروف وليس من المعروف أن تطيعهما في امرأة لا ترضاها، ولا تناسبك. أما إذا كنت ترضاها وتناسبك، وأحبا أن تتزوجها؛ فهذا خير إلى خير؛ تطيعهما؛ لأنها مصلحة ظاهرة، أما امرأة لا ترضاها؛ إما لضعف دينها، وإما لعدم جمالها، وإما لأسباب أخرى تعلم من نفسك أنك لا ترغب فيها، وتخشى من أن تخسر بدون فائدة، فإنه لا يلزمك، ولا يجوز لهما إلزامك، ولكن تسترضيهما بالكلام الطيب، والأسلوب الحسن؛ حتى يخضعا لقولك، وحتى يرضيا بالمرأة المناسبة، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10250/حكم-اجبار-الوالدين-ولدهما-على-الزواج-بفتاة-لا-يرغبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43414.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":12076,"question":"من بالأحمر رسالة بعث بها المستمع: عيسى موسى جابر يقول: هل يجوز أن تزوج ابنتك برجل غير متوفر فيه الشروط كاملة من الناحية الدينية؟","title":"حكم نكاح العاصي ومن يحرم تزويجه","answer":"الجواب:  إذا كان مسلمًا، وإن كانت فيه بعض المعاصي يجوز، لكن التماس الطيب المستور أولى وأفضل للجميع، لكن لو كان إنسان عنده بعض المعاصي؛ فالنكاح صحيح، وإنما يحرم تزويج الكافر الذي لا يصلي، أو يسب الدين، أو يهودي، أو نصراني، لا تزوجه المسلمة، النكاح باطل لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10]، لابد أن يكون زوج المسلمة مسلمًا، ولابد أن تكون زوجة المسلم مسلمة، أو كتابية، وهي اليهودية أوالنصرانية المحصنة خاصة، فالمسلم ليس له أن ينكح كافرة إلا أن تكون كتابية محصنة من اليهود والنصارى، والمسلمة ليس لها أن تنكح كافراً أبداً ليس لها أن تنكح إلا مسلمًا، فإذا كان الزوج مسلمًا ولكن عنده بعض المعاصي، أو كانت الزوجة مسلمة، وعندها بعض المعاصي؛ فالنكاح صحيح، ولكن التماس الزوج الطيب المستور، والزوجة الطيبة ذات الدين؛ هذا هو الذي ينبغي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10261/حكم-نكاح-العاصي-ومن-يحرم-تزويجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43509.mp3","categories":["شروط وأركان الزواج"]},{"id":12293,"question":"المستمع (س. س. الحارثي) من الطائف بعث برسالة يقول فيها: تزوج والدي من والدتي بعد أن أنجبت ولدين من رجل قبله، ثم أنجبت منه ولدًا وبنتًا، بعد ذلك تزوج والدي من امرأة أخرى أنجبت منه عددًا من الأولاد والبنات، وسؤالي هنا يا سماحة الشيخ: هل إخواني من أمي يصح لهم أن يتزوجوا من إخواتي من والدي؟ نرجو الإجابة مأجورين.","title":"حكم تزوج الأبناء من ربائب والدهم","answer":"الجواب:  نعم، لا حرج في ذلك، ليس بينهم قرابة تمنع، إذا لم يكن بينهم رضاع؛ فليس بينهم قرابة تمنع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10493/حكم-تزوج-الابناء-من-رباىب-والدهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45213.mp3","categories":["شروط وأركان الزواج"]},{"id":12605,"question":"الأمر سماحة الشيخ الذي ترونه مانعًا؛ لأن يقع العقد بين المتخاطبين.","title":"الحال التي يبطل فيها النكاح","answer":"الجواب:  مثلما تقدم.  المقدم: وهو؟  الشيخ: اختلاف الدين.  المقدم: اختلاف الدين هذا أهم شيء؟ الشيخ: إذا اختلف الدين؛ بطل النكاح، إلا في مسألة واحدة وهي نكاح المسلم للكتابية المحصنة خاصة. نعم. المقدم: جزاكم الله خيرًا، واختلاف الدين في مثل ترك الصلاة مثلًا؟  الشيخ: نعم، ترك الصلاة يوجب الكفر، يكون الدين مختلف، أما المعصية فلا توجب بطلان النكاح، ما دام مسلمًا، هو مسلم وهي مسلمة. نعم. المقدم: نعم، وغير ذلك لو تكرمتم؟ الشيخ: نعم.  المقدم: غير ذلك هل هناك شيء آخر؟ الشيخ: ما فيه إلا هذا، ليس فيه إلا هذا، المعاصي لا تبطل النكاح، وإنما يبطله الكفر، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10815/الحال-التي-يبطل-فيها-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41403.mp3","categories":["شروط وأركان الزواج","الأنكحة المحرمة","مبطلات النكاح"]},{"id":12606,"question":"ما رأيكم فيمن يفضل الزواج من البعيدات عن القريبات؟","title":"الزواج من البعيدات دون القريبات","answer":"الجواب:  ليس بصحيح، الصواب: اختيار الأفضل فالأفضل، قريبة، أو بعيدة، والقريبات أفضل؛ لأنهن قريبات يحسن إليهن، ويصل رحمهن، وغالب أزواج النبي من قريباته -عليه الصلاة والسلام- غالب أزواجه كلهم من أقربائه، عائشة، وأم سلمة، وحفصة بنت عمر، وغيرهم، كلهم من أقربائه، ما عدا صفية بنت حيي فإنها ليست من أقربائه، وإلا فالأغلب فهم أقرباء، نعم. المقدم: وما هو قول سماحتكم في أقوال الأطباء حول هذا الموضوع؟ الشيخ: يقول بعض الأطباء، وبعض الفقهاء: إن الأجنبية أنجب، ولكن ليس بصحيح، بل يختلف في ذلك، قد تكون القريبة أنجب، وقد يكون البعيدة أنجب، هذا إلى الله -جل وعلا- لكن إذا ...... الأسباب، إذا تزوج من بيت معروفين بالديانة ومعروفين بالذكاء ومعروفين بالعقل السليم، معروفين بالأخلاق الفاضلة، كان هذا أفضل وأقرب إلى أن يكون ولده مثلهم، سواء كانوا من الأقرباء، أو من غير الأقرباء، أما أن البنت الأجنبية ولدها نجيب، والقريبة ............ هذا ليس بصحيح، كم لله من أجنبية ليست بنجيبة، وكم لله من قريب نجيب. المقدم: جزاكم الله خيرًا، إذًا هذه الأقوال مرفوضة سماحة الشيخ؟ الشيخ: نعم نعم، بل ينبغي أن يختار الفضلى فالفضلى من قريبات، أو من غير قريبات، وإذا كان في القريبات من هو أهل فهن أولى؛ لما في ذلك من صلة الرحم، والإحسان إليهن، هذا كله طيب، مثلما تقدم، أن الرسول ﷺ غالب نسائه من أقربائه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10831/الزواج-من-البعيدات-دون-القريبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41419.mp3","categories":["شروط وأركان الزواج"]},{"id":12620,"question":"الأمر سماحة الشيخ الذي ترونه مانعًا؛ لأن يقع العقد بين المتخاطبين.","title":"الحال التي يبطل فيها النكاح","answer":"الجواب:  مثلما تقدم.  المقدم: وهو؟  الشيخ: اختلاف الدين.  المقدم: اختلاف الدين هذا أهم شيء؟ الشيخ: إذا اختلف الدين؛ بطل النكاح، إلا في مسألة واحدة وهي نكاح المسلم للكتابية المحصنة خاصة. نعم. المقدم: جزاكم الله خيرًا، واختلاف الدين في مثل ترك الصلاة مثلًا؟  الشيخ: نعم، ترك الصلاة يوجب الكفر، يكون الدين مختلف، أما المعصية فلا توجب بطلان النكاح، ما دام مسلمًا، هو مسلم وهي مسلمة. نعم. المقدم: نعم، وغير ذلك لو تكرمتم؟ الشيخ: نعم.  المقدم: غير ذلك هل هناك شيء آخر؟ الشيخ: ما فيه إلا هذا، ليس فيه إلا هذا، المعاصي لا تبطل النكاح، وإنما يبطله الكفر، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10815/الحال-التي-يبطل-فيها-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41403.mp3","categories":["شروط وأركان الزواج","الأنكحة المحرمة","مبطلات النكاح"]},{"id":12621,"question":"ما رأيكم فيمن يفضل الزواج من البعيدات عن القريبات؟","title":"الزواج من البعيدات دون القريبات","answer":"الجواب:  ليس بصحيح، الصواب: اختيار الأفضل فالأفضل، قريبة، أو بعيدة، والقريبات أفضل؛ لأنهن قريبات يحسن إليهن، ويصل رحمهن، وغالب أزواج النبي من قريباته -عليه الصلاة والسلام- غالب أزواجه كلهم من أقربائه، عائشة، وأم سلمة، وحفصة بنت عمر، وغيرهم، كلهم من أقربائه، ما عدا صفية بنت حيي فإنها ليست من أقربائه، وإلا فالأغلب فهم أقرباء، نعم. المقدم: وما هو قول سماحتكم في أقوال الأطباء حول هذا الموضوع؟ الشيخ: يقول بعض الأطباء، وبعض الفقهاء: إن الأجنبية أنجب، ولكن ليس بصحيح، بل يختلف في ذلك، قد تكون القريبة أنجب، وقد يكون البعيدة أنجب، هذا إلى الله -جل وعلا- لكن إذا ...... الأسباب، إذا تزوج من بيت معروفين بالديانة ومعروفين بالذكاء ومعروفين بالعقل السليم، معروفين بالأخلاق الفاضلة، كان هذا أفضل وأقرب إلى أن يكون ولده مثلهم، سواء كانوا من الأقرباء، أو من غير الأقرباء، أما أن البنت الأجنبية ولدها نجيب، والقريبة ............ هذا ليس بصحيح، كم لله من أجنبية ليست بنجيبة، وكم لله من قريب نجيب. المقدم: جزاكم الله خيرًا، إذًا هذه الأقوال مرفوضة سماحة الشيخ؟ الشيخ: نعم نعم، بل ينبغي أن يختار الفضلى فالفضلى من قريبات، أو من غير قريبات، وإذا كان في القريبات من هو أهل فهن أولى؛ لما في ذلك من صلة الرحم، والإحسان إليهن، هذا كله طيب، مثلما تقدم، أن الرسول ﷺ غالب نسائه من أقربائه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10831/الزواج-من-البعيدات-دون-القريبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41419.mp3","categories":["شروط وأركان الزواج"]},{"id":12632,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من بغداد مدينة صدام، باعثها المستمع: (ح. ج. أ) سوداني مقيم بالعراق، يقول: تقدمت إلى فتاة أريد الزواج بها، ولكن والد الفتاة رجل مدمن على شرب الخمر، والفتاة أيضًا لا تصلي، فهل يجوز لي في هذه الحالة أن أكلم الفتاة على الصلاة، وبعد ذلك أتزوجها، وهل يجوز لوالدها الذي يدمن شرب الخمر أن يكون وليًا عنها في عقد النكاح، وجهونا حول هذا الموضوع، وجزاكم الله خيرًا؟","title":"حكم الزواج ممن لا تصلي، وحكم ولاية الفاسق","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فترك الصلاة من الجرائم العظيمة، بل من الكفر بالله -عز وجل- في أصح قولي العلماء، لقوله -عليه الصلاة والسلام- في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ولقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة. والحكم المناط بالرجل يعم المرأة والعكس كذلك؛ لأن الأحكام عامة إلا ما خصه الدليل، وقد جاء في هذا المعنى أحاديث كثيرة، كلها تدل على كفر تارك الصلاة، فليس لك يا أخي! أن تتزوج فتاة لا تصلي، ومتى تابت، ورجعت إلى الحق، وثبت ذلك؛ جاز تزوجها بواسطة أوليائها، وأبوها هو وليها، إذا كان مسلمًا، وإن كان عنده بعض المعاصي كشرب المسكر. أما إن كان غير مسلم، كأن يكون لا يصلي، أو ممن يتعلق بالقبور، ويدعوها من دون الله، أو من الملاحدة كـالشيوعيين وأشباههم، فإن الولاية تنتقل إلى غيره، تنتقل الولاية إلى أقرب العصبة بعده، كإخوته إن كان لها إخوة من أبويها، أو من أبيها يزوجها أقربهم إليها، وهو الشقيق إذا كان مسلمًا، فإن لم يكن لها إخوة؛ فأقرب العصبة من أقاربها الذكور كبني الأخ، أو الأعمام إذا لم يكن هناك بنو أخ يصلحون للولاية.  والواجب على ولي الأمر، وتنوب عنه المحكمة أن ينظر في الأمر، فالقاضي الشرعي يقوم مقام الولي إذا فقد، أو وجد ولكن لم تتوافر فيه الشروط، فإن الحاكم الشرعي ينظر في ذلك، فإن وجد عاصبًا يزوجها وإلا قام القاضي الشرعي ولو في الأحوال الشخصية مقام الولي لقوله ﷺ: السلطان ولي لمن لا ولي له والقاضي نائب السلطان، ولكن بعد ثبوت إسلامها، وسلامتها من نواقض الإسلام، نعم. المقدم: جزاكم الله خيرًا، إذًا يكلمها على ما قال، ويفاوضها في أمر الصلاة، ثم يتقدم لخطبتها؟  الشيخ: لا مانع أن ينصحها بطريقة ليس فيها ريبة، من طريق الهاتف، أو من طريق اللقاء بدون خلوة، بحضرة أبيها، أو بحضرة إخوانها، فهذا من باب النصيحة، من باب التعاون على البر والتقوى، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10837/حكم-الزواج-ممن-لا-تصلي-وحكم-ولاية-الفاسق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41501.mp3","categories":["شروط وأركان الزواج"]},{"id":12652,"question":"تقول: جارتي لها أربع بنات، وعندما يتقدم أشخاص لبناتها يطلبون البنات الصغيرات، ويتركون الكبيرة، وهي ترفض هذا، وتقول: لنبدأ بالكبيرة أولًا، ما هو توجيهكم؟","title":"حكم رفض تزويج الصغرى حتى تتزوج الكبرى","answer":"الجواب:  لا يجوز هذا العمل، الواجب من جاءها النصيب تتزوج، سواء كانت الوسطى، أو الصغيرة، أو الكبرى، كل له نصيبه، فلا تمنع الصغرى من أجل الكبرى، قد تكون الكبرى ليست بالصفات التي في الصغرى من الجمال، أو الديانة، أو العلم، أو غير ذلك، كل امرأة لها أوصاف، فمن خطبت؛ وجب على وليها، وعلى أمها تزويجها، ولا يقال: نبدأ بالكبرى، كل له نصيبه نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10862/حكم-رفض-تزويج-الصغرى-حتى-تتزوج-الكبرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45804.mp3","categories":["شروط وأركان الزواج"]},{"id":12856,"question":"المستمع عبدالله عبيد الفنجري بعث بسؤال ملخصه كالتالي، يقول: تزوجت بدون رضا والدتي، وأشعر بعد هذه الحالة أنني غير موفق، فهل ذلكم هو السبب؟","title":"حكم من تزوج دون رضا والدته","answer":"الجواب:  لا شك أن مشاورة الوالدة من أهم المهمات، وحقها عظيم، ومشاورتها مهمة، وهكذا الوالد، ولكن إذا وقع الواقع فنرجو لك التوفيق، وعليك أن تستسمحها، وتطلب منها الإباحة والدعاء لك بالتوفيق، وهي -إن شاء الله- من كل خير قريب، الوالدة تحب لولدها كل خير. فعليك أن تستسمحها، وتقبل رأسها، وتطلب منها العفو والمسامحة، والدعاء لك بالتوفيق، وهي -إن شاء الله- تسمح، وفي المستقبل لا تتزوج إلا بمشاورة الوالدة والوالد ورضاهما، هذا هو الذي ينبغي لك؛ لأن حقهما عظيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11071/حكم-من-تزوج-دون-رضا-والدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46504.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":12859,"question":"رسالة مطولة جدًا وصلت إلى البرنامج من أحد الإخوة المستمعين، يسأل فيها عن حكم النكاح بدون ولي، ولا سيما إذا كانت المخطوبة ثيبًا، ولا سيما إذا كان الخاطب والمخطوبة في بلد غير بلد الولي؟","title":"حكم النكاح بدون ولي إذا كان في بلد غير بلد الولي","answer":"الجواب:  الولي لا بد منه، يقول النبي ﷺ: لا نكاح إلا بولي فلا بد من كون المرأة تخبر وليها وهو الذي يتولى عقد النكاح، المرأة لا تنكح نفسها، ولا تنكح غيرها، هذا هو الزنا، فرق ما بين الزنا والنكاح الولي، الشروط التي شرطها الله في ذلك؛ فلابد من ولي، ولابد من شاهدين، ولابد من إيجاب وقبول. فلا يجوز للمرأة أن تزوج نفسها، سواء كانت ثيبًا، أو بكرًا، بل الواجب عليها أن ترفع الأمر إلى وليها، ووليها هو الذي يتولى ذلك، والواجب على الولي أن يتقي الله، وألا يعضلها، وأن يجتهد في تيسير الزواج لها إذا خطبها الكفء، فينبغي، بل الواجب على الولي أن يسهل في ذلك، وأن يجتهد في إحصان موليته، وتسهيل زواجها، وعدم التعنت، والتكلف لا في المهر، ولا في الولائم، ولا في غير ذلك، هذا هو الواجب عليه، وإذا عضلها، أو تكلف في هذه الأمور في إمكانها أن ترفع الأمر للمحكمة إذا كانت في بلاد فيها محكمة؛ حتى تنظر المحكمة في الأمر، وتأخذ على يد الولي. أما إذا كانت المرأة في بلاد ليس فيها ولي، ليس فيها لا أخ ولا أب ولا ابن عم؛ فإن الحاكم يقوم مقام الولي، وليها الحاكم، لقول النبي ﷺ: السلطان ولي من لا ولي له فالحاكم يقوم مقام وليها، ويكون هو وليها، يزوجها، أو يوكل من يزوجها. فإذا كانت في بلاد ليس فيها حاكم، ليس فيها قاضي، ولا ولي، كالأقليات الإسلامية في بلاد الكفر، فليزوجها رئيس المركز الإسلامي إذا كان عندهم مركز إسلامي؛ لأنه بمثابة الأمير، بمثابة السلطان عندهم، ورئيس المركز الإسلامي ينظر لها، ويزوجها بالكفء إذا كان ليس لها أولياء، وليس هناك قاضٍ، نعم. المقدم: جزاكم الله خيرًا وإذا كان الولي بعيدًا، هل يقوم ولي الأمر في هذه الحالة بـ...... ؟ الشيخ: إذا كان بعيدًا يخاطب، يكاتب حتى يرسل وكالة الوكالة، نعم.  المقدم: حتى يرسل وكالة. الشيخ: إذا كان بعيدًا، ويعرف محله؛ فإنه يكاتب، أما إذا كان لا يعرف محله؛ فالولي الذي بعده يقوم مقامه، الذي أدنى منه يقوم مقامه، فإذا كان ماله ولي سوى الغائب الذي يجهل مكانه؛ فالسلطان يقوم مقامه، يعني: الحاكم، أو الأمير إذا ما له حاكم يقوم مقامه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11074/حكم-النكاح-بدون-ولي-اذا-كان-في-بلد-غير-بلد-الولي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_465/46509.mp3","categories":["شروط وأركان الزواج"]},{"id":12998,"question":"هذه السائلة مريم ( م . أ . ) جمهورية مصر العربية كتبت هذا السؤال بأسلوبها الخاص، تقول: سماحة الشيخ! لي مشكلة ألا وهي: بأنها تبلغ من العمر السابعة والعشرين، تقول السائلة: قبل عشر سنوات أجبروني أهلي على الزواج من ابن عمي، وقد كنت لا أرغب به، ولما هددوني بالضرب رجعوني إليه، ولم أجلس في بيته سوى خمسة أيام، ورجعت إلى بيت أهلي، وبعد ثلاث سنوات أجبروني رجوعي إليه مرة أخرى، ولم أبق معه إلا ثلاثة أيام، بعدها تزوج هذا الرجل، وأهلي يعاندونني ولم يطلقوني منه منذ عشر سنوات، وهو في حياته لم يصل لله ركعة، وأنا فتاة ملتزمة بأوامر الدين، وملتزمة بالفرائض، ولا أرضى أن أبق مع هذا الإنسان، أفتونا ووجهونا في هذا السؤال، جزاكم الله عنا وعن المسلمين خير الجزاء؟","title":"حكم تزويج المرأة دون رضاها","answer":"الجواب: ليس لأبيك ولا غيره إجبارك على زوج، لا ترضينه، هذا ما يجوز، حرام عليه، والنكاح غير صحيح؛ لقول النبي ﷺ: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن قالوا: يا رسول الله! كيف إذنها؟ قال: أن تسكت وقال ﷺ: البكر يستأذنها أبوها، وإذنها سكوتها. فالواجب على أبيك أن يتقي الله، وألا يجبرك على أحد أبدًا، لا يزوجك إلا بإذنك، وإذا كان لا يصلي هذا الرجل؛ فالنكاح باطل أيضًا من جهتين: من جهة كونه لا يصلي، ومن جهة كونك مجبرة، فالنكاح باطل غير صحيح، وليس له حق عليك؛ لأنك لم ترض بالنكاح؛ ولأنه لا يصلي، وأنت ملتزمة، فالنكاح باطل، ولا يجوز تزويج المسلمة المصلية على شخص لا يصلي؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء، وإن لم يجحد وجوبها؛ لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة أخرجه مسلم في صحيحه، وقوله ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. فالواجب أن يرفع الأمر للمحكمة؛ حتى يفسخ العقد، على أبيك أن يرفع أمره للمحكمة؛ حتى يفسخ العقد، وحتى تخلصي من هذا الرجل، أما إن هداه الله، وطلق؛ فالحمد لله، لكن إذا أبى؛ رفع الأمر إلى المحكمة، فالنكاح غير صحيح، لكن الطلاق لقطع التعلقات، والخروج من الخلاف، نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11215/حكم-تزويج-المراة-دون-رضاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50411.mp3","categories":["شروط وأركان الزواج"]},{"id":13007,"question":"هل يجوز عقد القران -النكاح- بين عيد الفطر، وعيد الأضحى؟ حيث أنه عندنا قول في تركيا: أنه لا يجوز عقد النكاح بين العيدين؟","title":"حكم عقد النكاح بين العيدين","answer":"الجواب: هذا قول باطل لا أساس له، يجوز عقد النكاح في كل وقت، في شوال، وذي القعدة، وذي الحجة، والمحرم، وصفر، وبقية السنة، ولا يجوز هذا الظن السيئ.  فالحاصل: أن القول بأنه لا يعقد بين العيدين، أو في صفر، أو في يوم الأربعاء، أو في كذا كله باطل، الله وسع هذا، والحمد لله، والموفق من وفقه الله، سواء عقد في شوال، أو في صفر أو في غيرهما، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11224/حكم-عقد-النكاح-بين-العيدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47103.mp3","categories":["شروط وأركان الزواج"]},{"id":13486,"question":"هنا رسالة مطولة ومكتوبة باللهجة العامية وصلت إلى البرنامج من جدة، وباعثتها إحدى الأخوات رمزت إلى اسمها بالحروف (ف. أ. ح. ن) أختنا لها قضية ملأت بها صفحة كاملة، لخصت هذه القضية في النقاط التالية:أولًا: زوج أمها هو الذي تولى ولايتها عند كتابة العقد مع وجود أخيها لأمها عند الزواج.ثانيًا: أن زوج أمها..الشيخ: واحدة واحدة.. الأول..المقدم: زوج أمها هو الذي تولى ولايتها عند كتابة العقد عند زواجها، وأخوها لأمها كان موجودًا؟","title":"حكم نكاح من زوَّجَها زوجُ أمها أو أخوها لأمها","answer":"الجواب: كلاهما ليس بولي، لا زوج أمها، ولا أخوها من أمها، كلاهما ليس بولي في النكاح، وإنما وليها في النكاح العصبة، أبوها إذا وجد، ثم ابنها إن كان لها بنون، ثم أخوها الشقيق، ثم أخوها لأب، ثم ابن أخيها الشقيق، ثم ابن أخيها لأب، ثم عمها الشقيق، ثم عمها لأب، وهكذا الأقرب فالأقرب، فإذا كان ما لها أقارب عصبة؛ فوليها الحاكم، القاضي يزوجها؛ لأنه نائب السلطان، والنبي  يقول: السلطان ولي من لا ولي له. أما زوج أمها إذا كان ليس بابن عم لها، زوج أمها ليس ابن عم لها ليس بولي، وهكذا أخوها لأمها إذا كان ليس ابن عم لها ليس بولي. أما إذا كان زوج أمها ابن عم لها، وليس هناك من هو أقرب منه؛ فلا بأس أن يزوجها؛ لأنه ابن عم؛ لأنه عصبة، لا لأنه زوج أمها، وهكذا أخوها لأمها إذا كان ابن عمها، وليس هناك عصبة أقرب منه يزوجها؛ لأنه ابن عم، لا لأنه أخ لأم، وإذا لم يوجد أحد من ذلك؛ فإنها ترجع إلى الحاكم، إلى المحكمة الشرعية، والمحكمة الشرعية تتولى ذلك، إما أن يتولاها القاضي، وإما أن يوكل القاضي من يقوم بذلك من الثقات. نعم. المقدم: وفي حالة وقوع العقد وهو لم يتصف بأي صفة صحيحة؟ الشيخ: يفسخ العقد، ويجدد من جديد على الوجه الشرعي، يفسخ ويجدد، ويمتنع الزوج من قربانها حتى يجدد العقد إذا كان له رغبة، وهي لها رغبة إذا اتفقا، يجدد العقد. المقدم: تقول أيضًا: إن زوج أمها عمل ليطلقها من زوجها، وقد أنكر غالب المهر، وقد تطلقت بسببه؟ الشيخ: هذا إلى المحكمة، هذا إلى المحكمة. نعم. المقدم: زوجها مرة ثانية، وهو الذي تولى ولايتها مع وجود أخيها لأمها؟ الشيخ: تقدم الكلام في هذا، وأنه لا يصح لا منه، ولا من.. إلا إذا كانا ابني عم لها، وليس هناك من هو أقرب منهما؛ جاز أن يتولى زوج الأم تزويجها إذا كان ابن عم لها ليس هناك من هو أقرب منه. وهكذا الأخ لأم يجوز أن يتولى تزويج الأخت لأم إذا كان ابن عمها، وليس هناك من هو أقرب منه، وإذا تم العقد من زوج الأم، وليس ابن عم، أو من أخ لأم، وليس ابن عم، أو هو ابن عم، لكن يوجد من هو أقرب منه؛ فإنه يفسخ، ويجدد من جديد إذا رغبا في تجديده .. إذا رغب الزوج والزوجة في تجديده. المقدم: بارك الله فيكم، وجزاكم الله خيرًا، إذًا يعتبر العقد والحال ما ذكر إذا لم يتصف بالصفات الصحيحة، يعتبر باطلًا؟ الشيخ: نعم. المقدم: وعليها أن تعيد كتابة العقد من جديد. الشيخ: نعم مع وليها الأقرب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11789/حكم-نكاح-من-زوجها-زوج-امها-او-اخوها-لامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47815.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":13798,"question":"يقول السائل: ما صحة زواجي من زوجة عمي بعد وفاته ونهاية عدتها؟","title":"حكم الزواج بأرملة العم","answer":"الجواب: لا حرج... زوجة عمك لا حرج، زوجة عمك وزوجة أخيك إذا مات عنها أو طلقها واعتدت لك أن تتزوجها، اللي المحرمة زوجة أبيك أو جدك أو ولدك أو ولد ولدك لا تنكحها محرم، أما زوجة أخيك إذا طلقها أو مات عنها، أو زوجة عمك أو خالك إذا طلقها أو مات عنها واعتدت لك أن تتزوجها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12169/حكم-الزواج-بارملة-العم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53618.mp3","categories":["شروط وأركان الزواج"]},{"id":13837,"question":"يقول هذا السائل من ليبيا: ما هو سن الزواج بالنسبة للفتاة المسلمة، هل هناك سن محدد للفتاة لكي تتزوج؟","title":"ما السن المحدد لتزويج الفتاة؟","answer":"الجواب: ما أعلم في هذا حدًا محدودًا، المقصود تحملها إذا كانت تتحمل الزواج ما لها حد محدود، النبي ﷺ تزوج عائشة وهي بنت سبع ودخل بها وهي بنت تسع، فإذا كانت الفتاة تتحمل زوجها وليها، وأما إذا كانت لا تتحمل لصغر جسمها أو ضعفها فلا يعجل عليها حتى تكون أهلاً للزواج، وأما السن فيختلف قد تكون بنت عشر تتحمل وقد تكون بنت خمسة عشر ما تتحمل لضعفها وضعف جسمها أو لمرض عرض لها أو نحو ذلك.\nفالمقصود: أن ولي المرأة وأمها وقريباتها ينظرون في حالها فلا يزوجونها إلا إذا كانت تتحمل الزواج. نعم.","link":"https://binbaz.org.sa/fatwas/12204/ما-السن-المحدد-لتزويج-الفتاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53009.mp3","categories":["شروط وأركان الزواج"]},{"id":13874,"question":"ننتقل إلى رسالة بعثت بها السائلة من السودان رمزت لاسمها بـ ( ك . ع . م . أ ) تقول في السؤال الأول: إذا عقد النكاح على الفتاة دون موافقتها أو دون علمها هل هذا النكاح يعتبر شرعيًا، خصوصًا إذا كانت الفتاة يتيمة، وما هو الجزاء المترتب على الوكيل الذي شهد بموافقتها زورًا؟ أفيدونا بذلك.","title":"حكم تزويج المرأة بدون إذنها","answer":"الجواب: لا يصح النكاح إلا بإذنها، وإذا كانت بكرًا إذنها السكوت سواءً كانت يتيمة أو غير يتيمة، يقول النبي ﷺ: لا تنكح البكر حتى تستأذن، ولا تنكح الأيم حتى تستأمر، قالوا: فالبكر يا رسول الله كيف إذنها؟ قال:  أن تسكت. فالواجب على وليها أن يستأذنها، وأن لا يزوجها إلا ... حتى ولو كان أبوها، الواجب أن يستأذنها، البكر يكفي سكوتها والأيم لابد أن تنطق تقول: لا بأس، فإذا زوجها بغير إذنها مكرهة بطل الزواج لا يصح يجب أن يجدد إذا رضيت، لابد من إذنها إما سكوتًا في حق البكر أو صراحة، سواء كانت يتيمة أو غير يتيمة.\nوالذي يكذب يقول: إنها رضيت. وهو يكذب يستحق أن يعزر يؤدب من جهة المحكمة على كذبه وظلمه، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12293/حكم-تزويج-المراة-بدون-اذنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50621.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":13888,"question":"ننتقل إلى رسالة بعثت بها السائلة من السودان رمزت لاسمها بـ ( ك . ع . م . أ ) تقول في السؤال الأول: إذا عقد النكاح على الفتاة دون موافقتها أو دون علمها هل هذا النكاح يعتبر شرعيًا، خصوصًا إذا كانت الفتاة يتيمة، وما هو الجزاء المترتب على الوكيل الذي شهد بموافقتها زورًا؟ أفيدونا بذلك.","title":"حكم تزويج المرأة بدون إذنها","answer":"الجواب: لا يصح النكاح إلا بإذنها، وإذا كانت بكرًا إذنها السكوت سواءً كانت يتيمة أو غير يتيمة، يقول النبي ﷺ: لا تنكح البكر حتى تستأذن، ولا تنكح الأيم حتى تستأمر، قالوا: فالبكر يا رسول الله كيف إذنها؟ قال:  أن تسكت. فالواجب على وليها أن يستأذنها، وأن لا يزوجها إلا ... حتى ولو كان أبوها، الواجب أن يستأذنها، البكر يكفي سكوتها والأيم لابد أن تنطق تقول: لا بأس، فإذا زوجها بغير إذنها مكرهة بطل الزواج لا يصح يجب أن يجدد إذا رضيت، لابد من إذنها إما سكوتًا في حق البكر أو صراحة، سواء كانت يتيمة أو غير يتيمة.\nوالذي يكذب يقول: إنها رضيت. وهو يكذب يستحق أن يعزر يؤدب من جهة المحكمة على كذبه وظلمه، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12293/حكم-تزويج-المراة-بدون-اذنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50621.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":13966,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الإمارات العربية المتحدة وباعثها أحد الإخوة من هناك يقول: المرسل (م. س. س) من رأس الخيمة، أخونا تكلف كثيرًا حينما بعث رسالته بالبريد الممتاز، ويبدو أن الموضوع عاجل فبدأه يقول: بسم الله الرحمن الرحيم.إلى سماحة الشيخ عبد العزيز بن عبد الله بن باز .السلام عليكم ورحمة الله وبركاته.يا حضرة الشيخ! أنا أب لفتاة تقدم لخطبتها شاب أرتضي دينه وخلقه، وقد وافقت أمها وابنتي المخطوبة وإخوانها وجدها وجدتها من قبل الأم، وجميع الأهل إلا والدتي، وهي تعتبر جدة البنت من قبل الأب، هل أزوج ابنتي من هذا الشاب الذي ارتضيناه جميعًا؟ أم آخذ برأي والدتي؟ أفيدونا مأجورين جزاكم الله خيرًا.","title":"حكم تزويج الفتاة مع اعتراض جدتها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. أما بعد: فإن الواجب عليك وعلى جميع الأسرة المساعدة على تزويج الفتاة بالرجل الصالح المرضي في دينه وأخلاقه، ومن خالف في ذلك فلا يعتبر خلافه، سواء كان المخالف الجدة أو غيرها؛ لأن الرسول عليه الصلاة والسلام قال في الحديث الصحيح: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن، ، قالوا: يا رسول الله! وكيف إذنها قال: أن تسكت متفق على صحته، وقال أيضًا عليه الصلاة والسلام: إذا خطب إليكم من ترضون دينه وخلقه؛ فزوجوه، إلا تفعلوه تكن فتنة في الأرض وفساد كبير، وفي لفظ آخر: وفساد عريض، هذا يدل على أن الواجب تزويج الكفء، وعدم رده إذا رضيت به المخطوبة، وما دامت رضيت والحمد لله وأنت ترضاه أيضًا؛ فهذا من نعم الله العظيمة، ونسأل الله للجميع التوفيق، ولا يجوز أن يعترض على ذلك بقول الجدة ولا غيرها. المقدم: جزاكم الله خيرًا سماحة الشيخ! كثيرًا ما يحدث مثل هذا في كثير من البيوت، تعضل البنت عن الزواج بسبب رأي أحد أفراد الأسرة؛ حبذا لو تفضلتم بتوجيه عام في هذا الموضوع. الشيخ: الواجب على الأسرة -وبالأخص على وليها-: أن يختار لها الرجل الصالح الطيب في دينه، والمرضي في خلقه، فإذا رضيت؛ وجب أن تزوج، ولا يجوز لأحد أن يعترض في ذلك لهوى في نفسه، أو لغرض آخر من الدنيا، أو لعداوة وشحناء، كل ذلك لا يجوز اعتباره، وإنما المعتبر كونه مرضيًا في دينه وأخلاقه، ولهذا قال النبي ﷺ في الحديث الصحيح في شأن المرأة: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ودينها، فاظفر بذات الدين تربت يداك، هكذا يقال في الرجل، سواء بسواء، الواجب الظفر بصاحب الدين، وإن أبى بعض الناس بعض الأسرة؛ لا يلتفت إليه. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ! راتب البنت ووظيفتها، أيضًا الحالة المادية والاجتماعية للخاطب، دراسة المخطوبة أيضًا؛ تكون أسبابًا أحيانًا في تأخير الزواج، توجيهكم لو تكرمتم. الشيخ: الواجب البدار بالزواج، ولا ينبغي أن يتأخر الشاب عن الزواج من أجل الدراسة ولا ينبغي أن تؤخر الفتاة عن الزواج للدراسة، فالزواج لا يمنع، فبالإمكان أن يتزوج الشاب ويحفظ دينه وخلقه، ويغض بصره، ومع هذا يستمر في الدراسة والحمد لله، وهكذا الفتاة: إذا يسر الله لها الكفء فينبغي البدار بالزواج وإن كانت في الدراسة، سواء كانت في الثانوية، أو في الدراسات العليا، كل ذلك لا يمنع. فالواجب البدار بالموافقة على الزواج إذا خطب الكفء، والدراسة لا تمنع من ذلك، ولو قطعت الدراسة فلا بأس، حتى ولو قطعت الدراسة، المهم أن تتعلم ما تعرف به دينها، والباقي فائدة، والزواج فيه مصالح كثيرة ولا سيما في هذا العصر، والترك فيه خطورة على الشاب وعلى الفتاة. فالواجب على كل شاب وعلى كل فتاة البدار بالزواج إذا تيسر الخاطب الكفء للمرأة، وإذا تيسرت المخطوبة الطيبة للشاب؛ فليبادر، عملاً بقول النبي الكريم عليه الصلاة والسلام في الحديث الصحيح: يا معشر الشباب! من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم؛ فإنه له وجاء، متفق على صحته، وهذا يعم الشباب من الرجال، والفتيات من النساء، ليس خاصًا بالرجال، بل يعم الجميع، وكلهم في حاجة إلى الزواج، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، إذًا أفهم مما تفضلتم به شيخ عبد العزيز أن كل شيء عدا الزواج يعتبر من الباب الزائد. الشيخ: إذا تعلمت ما تعرف دينها، وتعلم هو كذلك ما يحصل به معرفة دينه؛ فالحمد لله، هذا إذا قدر أن الزوج يمنع، أما إذا كان لا يمنع، فالحمد لله. المقصود: أن الشاب يتعلم ما يفقه به دينه، والفتاة كذلك، ولا يمنع ذلك أن يتزوج الشاب، ولا يمنع من أن تزوج الفتاة، فإن استمر الشاب في الدراسة؛ فالحمد لله، وإن اشتغل بطلب الرزق ليقوم بحاله وحال زوجته فلا بأس، وفي إمكانه أن يتعلم خارج المدرسة، في المساجد وعلى العلماء، أو دراسة مسائية إذا تيسر ذلك، والفتاة كذلك إذا حصل لها تعلم ما لا يسعها جهله من دينها؛ فالحمد لله، لا تأخر عن الزواج، وربما تيسر لها الزواج مع الدراسة، وسمح لها الزوج بذلك، وربما تيسر لها دراسة خاصة مسائية في محل مأمون طيب يرضاه الزوج، وربما درست من طريق سماع (نور على الدرب) وأشباهه من المحاضرات والندوات التي تذاع، إذا تحرتها الفتاة في أوقاتها لقصد الفائدة؛ فإنها دروس عظيمة مفيدة، وهكذا للرجال: الكبار والصغار دروس مفيدة عظيمة، إذا اعتنوا بها في أوقاتها، من هذا البرنامج ومن غيره من الدراسات الإسلامية، نسأل الله للجميع الهداية والتوفيق. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12376/حكم-تزويج-الفتاة-مع-اعتراض-جدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60501.mp3","categories":["قضايا المرأة","نصائح وتوجيهات","شروط وأركان الزواج"]},{"id":14196,"question":"هذه الزوجة التي رمزت لاسمها بـ (هـ. م. م) تقول: بأنها امرأة مصرية مقيمة بمكة المكرمة وتؤرقها هذه المشكلة، تقول: تزوجت من شاب ملتزم دون رضا والدته بعد أن كانت وافقت على الخطبة، بل قامت بالحضور إليها وباركتها لكنها غيرت رأيها؛ لأن هناك من وشى لها ولهذا رفضت إتمام الزواج وأرادت أن تفسخ هذه الخطبة، لكننا تزوجنا أنا وزوجي..الشيخ:أعد.. أعد..المقدم: تقول: تزوجت من شاب ملتزم دون رضا والدته بعد أن كانت قد وافقت على الخطبة بل وحضرتها وباركتها، لكنها غيرت رأيها في الأخير؛ لأن هناك من وشى لها ولهذا فقد رفضت إتمام الزواج وأرادت أن تفسخ هذه الخطبة لكننا تزوجنا على أمل أنها قد تغير رأيها بمرور الأيام، ولكن مضى أربع سنوات وزوجي يسعى لإصلاحها ولكنها ترفض وطلبها الوحيد هو أن يطلقني، وأنا الآن معي ما يقارب من طفلين ونعيش مع زوجي حياة طيبة، ما حكم هذا الأمر وهل زوجي يعتبر عاق؟","title":"حكم زواج الابن بغير رضا والدته","answer":"الجواب: إذا كان الزواج شرعيًا فلا بأس عليه وليس بعاق، والواجب عليها أن تعينه على الزواج وأن لا تمنعه من الزواج إذا كانت الزوجة لا بأس بها في دينها فليس لها حق -الوالدة- أن تمنعه.\nالمقصود أنه إذا كان الزواج شرعيًا لا محذور فيه فإنه قد أحسن لما في ذلك من إعفاف نفسه، والمسارعة إلى ما شرع الله، والواجب عليها هي التوبة إلى الله وأن لا تمنعه من الزواج وأن لا تأمره بطلاق امرأته إلا من علة.\nأما إذا كانت الزوجة غير مرضية في دينها هذا له وجه، إذا كانت السائلة غير مرضية وهي الزوجة وأمه ترغب به عنها لأنها غير مرضية في دينها لفسقها ومعاصيها أو تهمتها بالفساد فهذا له وجه، ينبغي له طاعة أمه في ذلك وفراق الزوجة التي لا خير فيها من جهة أعمالها الرديئة.\nفالحاصل أن التزوج أمر مطلوب، والولد عليه أن يتزوج ولو أبى والداه، عليه أن يتزوج ويعف نفسه، وعليهما أن يساعداه، على والديه أن يساعداه، لكن إذا كانت المخطوبة غير صالحة في دينها فالواجب عليه أن يلتمس غيرها ولا يعصي والديه. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12649/حكم-زواج-الابن-بغير-رضا-والدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54803.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":14201,"question":"يسأل ويقول: لدينا ما يسمى بيسر عقد النكاح، وهو الاتفاق بين الزوجين على المهر وإحضار شاهدين بغير إذن الولي إما لعدم حضوره أو لعدم إذنه، فهل هذا العقد يعتبر صحيح؟","title":"حكم عقد النكاح بدون ولي","answer":"الجواب: ليس بصحيح، لا عقد إلا بولي يقول ﷺ في الحديث الصحيح: لا نكاح إلا بولي، فالمرأة لا تزوج نفسها ولا تزوج غيرها، فلابد في النكاح من الولي والنكاح يحضره أربعة: الولي والزوج والشاهدان هذا هو النكاح الشرعي؛ ولي وهو أقرب العصبة إلى المرأة أبوها ثم جدها وإن علا من ... الذكور ثم ابنها ثم ابن ابنها وإن نزل، ثم أخوها الشقيق، ثم أخوها لأب، ثم بقية العصبة الأقرب فالأقرب، لا بد من الولي وأن يكون مسلمًا معروفًا بالخير عدلًا حسب التيسير، فإن لم يتيسر العدل جاز وإن كان غير عدل إذا كان مسلمًا.\nفالمقصود أنه لا بد من الولي ولا بد من شاهدين معروفين بالخير والعدالة، فالزوج هو صاحب الحاجة والولي يزوج ويقول: زوجتك فلانة بنت فلان أو بنته أو أخته أو نحو ذلك، والزوج يقول: قبلت، والشاهدان يشهدان بذلك. أما ما يسمى بالزواج العرفي وهو كونها تزوج نفسها من دون ولي هذا لا يجوز بل هو باطل عند جمهور أهل العلم، وعليه دل النص الصحيح عن رسول الله عليه الصلاة والسلام قوله: لا نكاح إلا بولي، قوله ﷺ: لا تزوج المرأة المرأة ولا تزوج المرأة نفسها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12666/حكم-عقد-النكاح-بدون-ولي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_616/61605.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":14317,"question":"هل الزواج من ابنة عمي وفي نفس الوقت هي بنت خالتي، هل هذا جائز؟","title":"حكم الزواج من ابنة العم وابنة الخالة","answer":"الجواب: نعم، التزوج من بنات العم وبنات الخال مشروع لا بأس به، الممنوع أن تتزوج عمتك أو خالتك أو أختك، هذا ممنوع، بالنص والإجماع.\nأما الزواج من بنات الخالة أو بنات الخال أو من بنات العم أو بنات العمة فهذا كله لا بأس به. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12778/حكم-الزواج-من-ابنة-العم-وابنة-الخالة","audio":"","categories":["شروط وأركان الزواج"]},{"id":14340,"question":"هل هناك صيغة ثابتة من السنة للعقد بين الزوجين؟ وما هي لو تكرمتم؟","title":"صيغة عقد النكاح","answer":"الجواب: الصحيح ليس بثابت في ذلك شيء معين، لكن كثير من أهل العلم يقولون: إنه يتلفظ بلفظ: أنكحت وزوجت، هذان اللفظان معروفان فيما يتعلق بالنكاح، ولكن الصحيح إنه لا يتعين، لو قال: ملكتك أو جوزتك بنتي، أو أعطيتك بنتي على سنة الله ورسوله، وقصده النكاح، وقال الزوج: قبلت صح بذلك؛ لأن الرسول ﷺ لم يعين لفظًا معينًا في الزواج، ولكن إذا قال: أنكحتك أو زوجتك يكون أحسن خروجًا من الخلاف، إذا قال: أنكحتك بنتي أو أختك أو زوجتك يكون أفضل، وإن قال غير ذلك من الألفاظ التي أراد بها الزواج، ويعرفها الزوج، قال: أعطيتك بنتي، أو ملكتك بنتي، أو وهبتك بنتي على سنة الله ورسوله، أو على مهر كذا، فقال الزوج: قبلت هذا الزواج، وبينهما مهر، وليس هناك موانع، الزوجة راضية بحضرة شاهدين والولي الذي هو أقرب الناس إليها كأبيها وابنها وبعدهما أقرب العصبة.\nإذا كان الولي هو الذي تولى الزواج، وأولاهم الأب، ثم الابن، ثم ابن الابن، فأنزل، ثم أقرب العصبة هذا هو الولي، ويكون ذلك بحضرة شاهدين عدلين، فالجميع أربعة: الزوج، والولي، والشاهدان، إذا كانت المرأة سليمة ليست في عدة، وليست مكرهة، بل راضية، فالنكاح لا بأس به، ولو قال بغير لفظ النكاح، لو قال: أعطيتك، أو ملكتك، أو وهبتك، لا حرج؛ لأن النية معروفة، والمقصود معروف وهو النكاح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12836/صيغة-عقد-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_623/62313.mp3","categories":["شروط وأركان الزواج"]},{"id":14347,"question":"هل هناك صيغة ثابتة من السنة للعقد بين الزوجين؟ وما هي لو تكرمتم؟","title":"صيغة عقد النكاح","answer":"الجواب: الصحيح ليس بثابت في ذلك شيء معين، لكن كثير من أهل العلم يقولون: إنه يتلفظ بلفظ: أنكحت وزوجت، هذان اللفظان معروفان فيما يتعلق بالنكاح، ولكن الصحيح إنه لا يتعين، لو قال: ملكتك أو جوزتك بنتي، أو أعطيتك بنتي على سنة الله ورسوله، وقصده النكاح، وقال الزوج: قبلت صح بذلك؛ لأن الرسول ﷺ لم يعين لفظًا معينًا في الزواج، ولكن إذا قال: أنكحتك أو زوجتك يكون أحسن خروجًا من الخلاف، إذا قال: أنكحتك بنتي أو أختك أو زوجتك يكون أفضل، وإن قال غير ذلك من الألفاظ التي أراد بها الزواج، ويعرفها الزوج، قال: أعطيتك بنتي، أو ملكتك بنتي، أو وهبتك بنتي على سنة الله ورسوله، أو على مهر كذا، فقال الزوج: قبلت هذا الزواج، وبينهما مهر، وليس هناك موانع، الزوجة راضية بحضرة شاهدين والولي الذي هو أقرب الناس إليها كأبيها وابنها وبعدهما أقرب العصبة.\nإذا كان الولي هو الذي تولى الزواج، وأولاهم الأب، ثم الابن، ثم ابن الابن، فأنزل، ثم أقرب العصبة هذا هو الولي، ويكون ذلك بحضرة شاهدين عدلين، فالجميع أربعة: الزوج، والولي، والشاهدان، إذا كانت المرأة سليمة ليست في عدة، وليست مكرهة، بل راضية، فالنكاح لا بأس به، ولو قال بغير لفظ النكاح، لو قال: أعطيتك، أو ملكتك، أو وهبتك، لا حرج؛ لأن النية معروفة، والمقصود معروف وهو النكاح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12836/صيغة-عقد-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_623/62313.mp3","categories":["شروط وأركان الزواج"]},{"id":14434,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ع. ع. ق) من الدمام، أخونا له عدد من الأسئلة فيسأل في سؤاله الأول ويقول:إذا تزوج الإنسان وهو لا يصلي، لا هو ولا الزوجة، وبعد الزواج بمدة طويلة هداهم الله للصلاة والأمور الشرعية، وفي وقت العقد اكتشف أنه كان محدثًا حدثًا أكبر، ولم يغتسل وقت العقد، بل أجرى العقد وهو على ذلكم الحال، هل العقد صحيح، أم بماذا تنصحونه حيال ما ذكر؟جزاكم الله خيرًا.","title":"حكم العقد إذا كان الزوجان لا يصليان","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فإذا كان الرجل والمرأة حين العقد لا يصليان، فالعقد صحيح؛ لأنهما مستويان في ترك الصلاة، وفي الكفر عند من كفرهما بذلك وفي عدمه، فالنكاح صحيح، والصواب أن ترك الصلاة كفر أكبر نعوذ بالله من ذلك، كما قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ولم يقل: بشرط جحدهما الوجوب، بل أطلق -عليه الصلاة والسلام-، فدل على أن من ترك الصلاة كفر، وإن أقر بالوجوب، ومن ذلك قوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، لكنهما مستويان لا يصليان، فالعقد بينهما صحيح كالنصرانيين واليهوديين والوثنيين إذا تزوجا؛ لأنهما مستويان في عدم الدين. أما إذا كان أحدهما يصلي والآخر لا يصلي حين العقد فإن الواجب تجديد العقد بعدما صلى من لا يصلي وتاب إلى الله  يجدد العقد على الصحيح على القول بأن ترك الصلاة كفر أكبر، فيجدد العقد بمهر جديد، وشاهدي عدل، وبواسطة الولي، فالعقد يحضره أربعة: الولي والزوج والشاهدان، فيجدد العقد بمهر وشاهدي عدل بعدما تاب الله على من كان لا يصلي منهما، والحمد لله احتياطًا وخروجًا من خلاف العلماء الذين كفروا تارك الصلاة، وقولهم أصح لظاهر الأدلة الشرعية. وأما كونه تزوج على غير طهارة فهذا لا يضر العقد، وهكذا لو كانت المرأة على حيض حين العقد أو في نفاس لا يضر إذا كانت ليست في عدة، كالبكر عقد عليها وهي في الحيض أو امرأة قد خرجت من العدة عقد عليها وهي في الحيض لا يضر ذلك، ليس من شرط العقد أن يكون الرجل طاهرًا أو المرأة طاهرة، فإذا تم العقد والرجل على جنابة أو المرأة على جنابة أو في حيض أو في نفاس فالعقد صحيح ليس من شرطه الطهارة ما دامت ليست في العدة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12909/حكم-العقد-اذا-كان-الزوجان-لا-يصليان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62401.mp3","categories":["الطلاق","شروط وأركان الزواج","نكاح الكفار","فتاوى متنوعة"]},{"id":14497,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، سمى نفسه جعفر محمد عبدالله، مقيم في ضواحي مدينة العلا الشمالية، الأخ جعفر يسأل ويقول: أنا تزوجت العام الماضي، ولم أعمل في زواجي حفلات؛ لأنني خفت من اختلاط الرجال والنساء، فقال لي بعض الناس: الحفلة لازمة حتى تعلن النكاح، وأخشى إن عملت الاحتفال أن يحدث الاختلاط، فأتحمل الإثم، وجهوني كيف أتصرف؟جزاكم الله خيرًا.","title":"ما حكم الزواج بدون حفلات إعلان النكاح؟","answer":"الجواب: الواجب إعلان النكاح، الواجب إعلان النكاح، حتى يعلم الناس أن فلانًا تزوج، وفلانة تزوجت؛ لأن عدم الإعلان يجعله كالزنا، فالواجب إعلان النكاح بالحفلة التي تكون ليلة الزفاف، ولو على قهوة وشاهي، ما هو بلازم وليمة، لكن السنة وليمة، النبي  قال: أولم ولو بشاة وقد أوجب ذلك بعض أهل العلم، وليس من اللازم الاختلاط، تولم وليمة خفيفة ولو بشاة أو شاتين، تدعو إليها من تحب من إخوانك الطيبين، والنساء مع النساء إذا كان لك أقارب، وخوف الاختلاط ليس مانعًا من الوليمة والاحتفال الشرعي، بل عليك أن تحتفل الاحتفال الشرعي بإعلان النكاح، وجمع مشيعين لك، سواء قليلين أو كثيرين على قهوة أو عشاء، وتمنع الاختلاط بالقوة، لا تجعل اختلاط، يكون النساء مع النساء، الرجل يكون عنده قوة، عنده إيمان يمنعه من الاختلاط.  أما أنه يدع المشروعات خوف الاختلاط، هذا جبن وضعف، لا يليق بالمؤمن، بل يجب أن يكون عنده من القوة ما يمكنه من إقامة السنن والمشروعات، ومنع ما حرم الله، فامنع الاختلاط، وتقيم ما شرع الله، وإلا فلا تدع النساء بالكلية، ادع الرجال، وأقم الاحتفال بالرجال فقط، والحمد لله، واصنع الوليمة بما يسر الله من شاة، أو شاتين أو أكثر من ذلك، تدعو إليها الجيران والأقارب. والخلاصة: أنه لا بد من إعلان النكاح، لا بد من إعلانه، ولو بجمع الناس على شاي، حتى يعلم الناس أنه نكاح، حتى يعلم الجيران والناس أنه تزوج فلان، ويستحب الضرب عليه بالدف، يضربه النساء بالدف ولو قليلًا، ولو ربع ساعة، ولو نصف ساعة بالدف بين النساء خاصة بدون اختلاط، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12969/ما-حكم-الزواج-بدون-حفلات-اعلان-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48814.mp3","categories":["شروط وأركان الزواج"]},{"id":15083,"question":"يقول: تزوج رجل من امرأة، وقبل الدخول بها بأشهر، صرحت له أنها ليست بكرًا، وأنها ارتكبت مع خطيبها الأول جريمة، ورأفة بها، أو رأفةً لها، وتسترًا عليها، وخوفًا عليها من التمادي في هذا المنكر، إذا رفض الزواج منها، عسى أن تتوب إلى الله ؛ لذلك تزوج منها، من أجل ذلك تزوجها وهو راضي النفس، حبًا في عمل الخير، وإرضاءً لله. ويرجو أن يرضى الله عليه، عسى أن يكرمه الله في حياتها معه؟ فما موقفه بالنسبة للدين؟ وهل ينطبق عليه قول الله تعالى: وَالزَّانِيَةُ لا يَنكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ [النور:3]؟","title":"حكم الزواج من امرأة ارتكبت الفاحشة ثم تابت","answer":"الجواب: إذا كانت هذه المرأة قد تابت إلى الله سبحانه من جريمتها، وتزوجها بعد حيضتها حيضة، أو بعد وضعها حملها إن كانت حملت، فلا شيء عليه في ذلك؛ فإن الله يتوب على من تاب ، والستر عليها مشروع، ومطلوب، وعدم إفشاء هذه الفاحشة، وقد أحسن في الستر عليها. وأما نكاحه فصحيح؛ إذا كانت قد تابت إلى الله من جريمتها، وأخبرته بأنها قد ندمت، وتابت، ولم تكن في عدة، بل قد وضعت الحمل إن كانت حبلى، أو مضى عليها حيضة فأكثر إذا كانت لم تحمل، فإن النكاح صحيح، نعم.","link":"https://binbaz.org.sa/fatwas/13582/حكم-الزواج-من-امراة-ارتكبت-الفاحشة-ثم-تابت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_655/nour_65504.mp3","categories":["شروط وأركان الزواج"]},{"id":15248,"question":"هذا سؤال من المستمع (م. أ. ح) من القاهرة، شبرا، مصر، يقول: تزوجت منذ عدة أشهر، ولكن لظروف قاسية أخفيت اسمي الحقيقي وقت عقد الزواج، وعقدت باسم مستعار، والسبب في ذلك استخفافي بشأن الزواج وأمره، نظرًا لضعف إيماني في ذلك الوقت، ولكن الآن -والحمد لله- اكتشفت أنني كنت في ضلال، وقد ندمت على كل ما فعلت، وعزمت على التوبة الصادقة -إن شاء الله-، وقد حيرني أمر هذا الزواج بتلك الصورة. فأرجو إرشادي إلى سبيل الرشاد.","title":"حكم الزواج باسم مستعار","answer":"الجواب: هذا السؤال فيه إشكال، وأرى أن يؤجل جوابه إلى حلقة أخرى، حتى أتأمله جيدًا، وحتى لا نقول على الله بغير علم.  فالمقصود: أن هذا السؤال فيه بعض الإشكال، ونرى أن يؤجل إلى الحلقة الآتية -إن شاء الله-. المقدم: إن شاء الله، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13752/حكم-الزواج-باسم-مستعار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_670/nour_67004.mp3","categories":["شروط وأركان الزواج"]},{"id":15415,"question":"هذان سؤالان من المستمع (ج. م. ح) من الموصل، العراق، يقول في سؤاله الأول: تزوجت من ابنة عمي منذ فترة، ولي منها أطفال، ولكن علمت بعد ذلك أن أخاها الأصغر قد رضع من والدتي، مع العلم أنني أنا لم أرضع من والدتها، وهي أيضًا لم ترضع من والدتي، فهل يلحقنا تأثير الرضاع هذا؟","title":"حكم من تزوج امرأة رضع أخوها من أمه","answer":"الجواب: لا يضر، لا، رضاع أخيها لا يضر، ما دام أنت لم ترضع من أمها، وهي لم ترضع من أمك، لا يضر رضاع أخيها، لا يضر، نعم.","link":"https://binbaz.org.sa/fatwas/13924/حكم-من-تزوج-امراة-رضع-اخوها-من-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68415.mp3","categories":["شروط وأركان الزواج"]},{"id":15458,"question":"سؤاله الآخر يقول: هل يجوز أن يتزوج الرجل زوجة عمه، أو زوجة خاله بعد طلاقها، أو وفاة أحدهما؟","title":"ما حكم الزواج بزوجة العم أو الخال؟","answer":"الجواب: لا حرج، كما يتزوج زوجة أخيه لا بأس أن يتزوج زوجة عمه وخاله. فالمقصود: أن زوجة العم، وزوجة الخال إذا لم يكن بينك وبينها قرابة ولا رضاعة فلا بأس، ما هي بزوجة العم مثل زوجة الأب ولا زوجة الخال، مثل زوجة الأب، لا، بعض الناس يظن أن زوجة الخال لها شأن غير زوجة الأخ وهذا غلط، زوجة الأخ والخال والعم كلهن أجنبيات له أن يتزوج إحداهن إذا مات زوجها أو طلقها بعد خروجها من العدة كما يتزوج زوجة أخيه، أخوه أقرب، فأخوه لو مات أو طلق جاز له أن ينكح زوجة أخيه بعد العدة، فهكذا زوجة الخال وزوجة العم من باب أولى؛ لأنهما أبعد من الأخ، إلا إذا كان بينهما قرابة خاصة، أو رضاعة تقتضي التحريم هذا شيء آخر، أما مجرد كون الخال نكحها، أو العم نكحها، هذا لا يحرمها على الشخص، لا يحرمها على ابن أخته ولا يحرمها على ابن أخيه، نعم.","link":"https://binbaz.org.sa/fatwas/13980/ما-حكم-الزواج-بزوجة-العم-او-الخال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_687/nour_68702.mp3","categories":["شروط وأركان الزواج"]},{"id":15691,"question":"هنا رسالة مطولة ومكتوبة باللهجة العامية، وصلت إلى البرنامج من جدة، وباعثتها إحدى الأخوات، رمزت إلى اسمها بالحروف: (ف. أ. ح. ن) أختنا لها قضية ملأت بها صفحة كاملة، لخصت هذه القضية في النقاط التالية:أولًا: زوج أمها هو الذي تولى ولايتها عند كتابة العقد مع وجود أخيها لأمها عند الزواج.","title":"حكم نكاح المرأة إذا تولاه زوج أمها","answer":"الجواب: كلاهما ليس بولي لا زوج أمها ولا أخوها من أمها، كلاهما ليس بولي في النكاح، وإنما وليها في النكاح العصبة أبوها إذا وجد، ثم ابنها إن كان لها بنون، ثم أخوها الشقيق، ثم أخوها لأب، ثم ابن أخيها الشقيق، ثم ابن أخيها لأب، ثم عمها الشقيق، ثم عمها لأب، وهكذا الأقرب فالأقرب. فإذا كان ما لها أقارب عصبة فوليها الحاكم القاضي يزوجها؛ لأنه نائب السلطان، والنبي  يقول: «السلطان ولي من لا ولي له». أما زوج أمها إذا كان ليس بابن عم لها، زوج أمها ليس ابن عم لها ليس بولي، وهكذا أخوها لأمها إذا كان ليس ابن عم لها ليس بولي. أما إذا كان زوج أمها ابن عم لها، وليس هناك من هو أقرب منه، فلا بأس أن يزوجها؛ لأنه ابن عم لأنه عصبة، لا لأنه زوج أمها. وهكذا أخوها لأمها إذا كان ابن عمها، وليس هناك عصبة أقرب منه يزوجها؛ لأنه ابن عم، لا لأنه أخ لأم. وإذا لا يوجد أحد بذلك فإنها ترجع إلى الحاكم إلى المحكمة الشرعية، والمحكمة الشرعية تتولى ذلك، إما أن يتولاه القاضي، وإما يوكل القاضي من يقوم بذلك من الثقات، نعم. المقدم: وفي حالة وقوع العقد وهو لم يتصف بأي صفة صحيحة؟ الشيخ: يفسخ، يفسخ العقد، ويجدد من جديد على الوجه الشرعي، يفسخ ويجدد، ويمتنع الزوج من قربانها حتى يجدد العقد إذا كان له رغبة، وهي لها رغبة إذا اتفقا يجدد العقد. المقدم: تقول أيضًا: إن زوج أمها عمل ليطلقها من زوجها، وقد أنكر غالب المهر، وقد تطلقت بسببه؟\nالشيخ: هذا إلى المحكمة، هذا إلى المحكمة، نعم. المقدم: زوجها مرة ثانية، وهو الذي تولى ولايتها مع وجود أخيها لأمها؟ الشيخ: تقدم الحديث في هذا، وأنه لا يصح لا منه ولا من أخوها لأمها، إلا إذا كانا ابني عم لها، وليس هناك من هو أقرب منهما جاز أن يتولى زوج الأم تزويجها، إذا كان ابن عم لها، ليس هناك من هو أقرب منه، وهكذا الأخ لأم يجوز أن يتولى تزويج الأخت لأم إذا كان ابن عمها، وليس هناك من هو أقرب منه.\nوإذا تم العقد لزوج الأم وليس ابن عم أو من الأخ لأم وليس ابن عم أو هو ابن عم، ولكن يوجد من هو أقرب منه، فإنه يفسخ، ويجدد من جديد إذا رغبا في تجديده، إذا رغب الزوج والزوجة يجدد، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا، إذًا يعتبر العقد والحال ما ذكر إذا لم يتصف بالصفات الصحيحة يعتبر باطلاً؟ الشيخ: نعم، نعم. المقدم: وعليها أن تعيد كتابة العقد من جديد؟ الشيخ: نعم، مع وليها الأقرب.","link":"https://binbaz.org.sa/fatwas/14245/حكم-نكاح-المراة-اذا-تولاه-زوج-امها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57212.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":15698,"question":"هل يجوز الزواج من شقيقة زوجة أبي؟","title":"حكم زواج الرجل بأخت زوجة أبيه","answer":"الجواب: نعم، شقيقة زوجة أبيك لا بأس، بنتان: إحداهما أخذها أبوك، والثانية تأخذها أنت، فلا بأس؛ لأبيك واحدة، ولك واحدة، كذلك إذا كانت بنتها وهو لم يدخل بها -بنت الزوجة من غيره، لم يدخل بها- حل لك، أما إذا دخل بها، صارت ربيبة لأبيك، وحرام على أبيك، ولكنها تحل لك أنت؛ لأنها ليست أختًا لك، وإنما هي ربيبة لأبيك، إذا كانت من زوج آخر، قبله أو بعده. فالمقصود: أنه لك أن تنكح أخت زوجة أبيك، وعمتها، وخالتها، وبنتها من غيره، إذا لم يكن هناك رضاعة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14256/حكم-زواج-الرجل-باخت-زوجة-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57307.mp3","categories":["شروط وأركان الزواج"]},{"id":15724,"question":"هذا سائل أبو عبدالله من الرياض، أرسل -الحقيقة- بمجموعة من الأسئلة، يقول: إلى سماحة الشيخ عبد العزيز بن عبد الله بن باز -حفظكم الله تعالى-.رجل مسلم، ملتزم بدينه، محافظ على الصلوات الخمس -والحمد لله-، تزوج من امرأة مسلمة ملتزمة، فكان أحد الشاهدين على عقد النكاح رجل لا يصلي، وربما وقع في الكبائر، كشرب الخمر، فهل عقد النكاح في مثل هذه الحالة صحيح من الناحية الشرعية؟ علمًا بأنه قد حضر كتابة العقد عدد كبير من الرجال المسلمين المصلين، وشهدوا بأنفسهم إجراءات الصك للزواج، ما حكم ما وقع بين الزوجين من نكاح؟ وهل يلزم الإعادة لكتابة العقد؟","title":"حكم عقد النكاح إذا كان أحد الشاهدين لا يصلي","answer":"الجواب: نعم؛ إذا كان عند العقد -عند قوله: زوجت، وعند قول الزوج: قبلت- لم يحضرهما إلا شاهدان أحدهما لا يصلي؛ يعاد العقد؛ لأنه ليس بعدل، يعاد لأن العقد لا بد فيه من شاهدي عدل، مع الولي، فإذا كان عند إجراء العقد -حين قال: زوجتك، حين قال: الزوج: قبلت- لم يحضرهما إلا شاهدان، أحدهما فاجر، معروف الفجور، أو كافر، كتارك الصلاة يجدد العقد، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14285/حكم-عقد-النكاح-اذا-كان-احد-الشاهدين-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57412.mp3","categories":["شروط وأركان الزواج"]},{"id":16234,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع الحميدي، مقيم في الرياض السليمانية، أخونا له رسالة طويلة، وموضوع أطول يتعلق بالطلاق، يقول: تزوجت قبل خمسة أعوام، وكنت وقتها لا أصلي، ولا أصوم، ولا أقوم بأي فريضة أبدًا، كنت على خلاف دائم مع زوجتي، قلت لها ذات يوم: أنت طالق، أمام أهلها، وحضرت لهما في اليوم التالي، وأخذتها إلى بيتي بالمرة، ثم المرة الثانية أرسلت لها ورقة، وقلت لهما: أنت طالق، وبعد مرور ثلاثة أيام حضرت، وأخذتها إلى بيتي، وبعد مرور تسعة أشهر قررت السفر للسعودية، وأخبرت أهلها على طلاقها، ثم أخذوا عفشي من بيتي في غيابي مقابل أن أطلقها، المهم طلقتها تفاديًا للمشاكل، وحضرت للسعودية، والحمد لله استقمت، وعرفت الكثير عن الإسلام، وبدأت الصلاة والصوم، وحجيت أكثر من مرة، وحفظت الكثير من كتاب الله، مكثت في السعودية سنتين، ورجعت إلى بلدي، وعقدت عقدًا جديدًا، وبمهر جديد على زوجتي الأولى؛ لأنني سمعت من هذا البرنامج بأن الذي لا يصلي عقده باطل، لذا قلت: بأن زواجي من أوله باطل، ولذلك عقدت عليها من جديد، أرجو إفادتي عن صحة ما فعلت؟ جزاكم الله خيرًا.","title":"حكم من عقد على طليقته بعد أن كان تاركًا للصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.  إذا كان الواقع هو ما ذكرت في السؤال، وأنك حين تزوجتها وأنت لا تصلي، وهي تصلي فإن العقد يكون غير صحيح؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء، وإن لم يجحد الوجوب، أما من جحد وجوبها؛ فإنه يكفر بإجماع المسلمين، وبذلك تبين بالطلقة الأولى، ولا يلحقها ما بعدها، ويكون عقدك الجديد بعد التوبة إذا كانت هي تصلي؛ يكون عقدك الجديد بعد التوبة صحيحًا، والحمد لله. ونسأل الله أن يهديكما جميعًا، وأن يصلح حالكما جميعًا، ويكون قد مضى عليها طلقة، وهي الطلقة الأولى، والطلقة الثانية، وما بعدها لا تلحقها لكونها تصلي، وأنت لا تصلي، فالعقد غير صحيح، ولا يلحقها بسبب ذلك إلا طلقة، والعمدة على النكاح الجديد الذي بعد التوبة، نسأل الله لنا ولكم الثبات على الحق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14926/حكم-من-عقد-على-طليقته-بعد-ان-كان-تاركا-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80701.mp3","categories":["نكاح الكفار","شروط وأركان الزواج"]},{"id":16416,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ع. ز. ي) يقول: أنا شاب أبلغ من العمر الثامنة عشرة، تقدمت لخطبة ابنة عمي، ولكنهم رفضوا بحجة أننا إخوان من الرضاعة، ولكني لم أرضع من أمها، وهي لم ترضع من أمي، ولكن أمها أرضعت أختي التي هي أختي من أب فقط، هل صحيح نحن أخوان من الرضاعة، أم لا؟الشيخ: أعد.المقدم: يقول: أنا شاب أبلغ من العمر الثامنة عشرة، تقدمت لخطبة بنت عمي، ولكنهم رفضوا؛ بحجة أننا أخوان من الرضاعة، ولكني لم أرضع من أمها، وهي لم ترضع من أمي، لكن أمها أرضعت أختي التي هي أخت من أب فقط، هل صحيح نحن أخوان من الرضاعة، أم لا؟ وهل يصح زواجي منها، أم لا؟ جزاكم الله خيرًا.","title":"حكم زواج الرجل من بنت امرأة أرضعت أخته","answer":"الجواب: إذا كان الواقع كما ذكرت في السؤال فلا حرج في زواجها، وإرضاع أمها لأختها لا يسري عليها، بل الزواج بها لا حرج فيه؛ لأنها ليست أختًا من الرضاعة لك، إذا كان الواقع مثلما ذكرت في السؤال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15165/حكم-زواج-الرجل-من-بنت-امراة-ارضعت-اخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81210.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":16674,"question":"بعد هذا ننتقل إلى السودان عبر رسالة بعث بها المستمع عبدالله عبدالرحمن السيدح -فيما يبدو- أخونا له قضية ربما تكون مشوشة بعض الشيء، يقول: جدي من والدي تزوج من امرأة، ولم ينجب منها، وطلقها، فجاء رجل آخر من الأقارب، وتزوجها، وأنجب منها بناتًا، وتقدمت أنا للزواج من إحدى البنات، وعندما خطبتها سأل والدي البعض فقالوا: إنها لا تحل لي، واختلف في ذلك الأمر، وهالني اختلافهم؛ فلجأت إلى الله، ثم إليكم؛ لعلي أستمع القول الفصل، جزاكم الله خيرًا.","title":"حكم زواج الرجل من بنت زوجة أبيه","answer":"الجواب: لا حرج عليك في الزواج من بنات زوجة أبيك من غير أبيك، من الزوج الجديد، إذا كانت لم ترضعك؛ فأنت أجنبي من بناتها، إذا كانت لم ترضعك، فإن لك أن تتزوج بإحدى بناتها من الزوج الجديد، وإنما يحرمن على أبيك؛ لأنهن ربائب لأبيك، يحرمن عليه إذا كان دخل بأمهن، قد وطئ أمهن يحرمن على أبيك، أما أنت لا، لا يحرمن عليك، لا بأس أن تتزوج إحدى بناتها، ولا وجه للاختلاف في هذا، ليس في هذا اختلاف بحمد الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15420/حكم-زواج-الرجل-من-بنت-زوجة-ابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_760/nour_76004.mp3","categories":["شروط وأركان الزواج"]},{"id":16871,"question":"من جمهورية مصر العربية المستمع (م. ن. أ) بعث برسالة ضمنها جمعًا من الأسئلة، عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة بقي له بعض آخر، يقول: لي ابنة عم أرغب في الزواج منها، وهي كذلك، وعندما أردت أن أتقدم لها، منعني أخي الأكبر، وقال لي: إن زواجي من امرأة تكبرني في السن حرام، ولا يحل، وأخي هذا إمام مسجد، ويخطب في الناس، فهل هذا صحيح؟ مع العلم أن هذه الفتاة تكبرني في السن بثلاث سنوات فقط، أرجو إفادتي، جزاكم الله خيرًا.","title":"حكم زواج الرجل من امرأة أكبر منه أو العكس","answer":"الجواب: هذا غلط، كلام أخيك غلط، ولا حرج أن تتزوج امرأة تكبرك، أو تصغر عنك، لا حرج، أو تساويك، كله واسع، والحمد لله، لو تزوجت امرأة سنها أربعون، وأنت عشرون فلا بأس، أو سنها خمسون، وأنت عشرون لا بأس، وقد تزوج النبي ﷺ خديجة أم أولاده، وهي في سن الأربعين، وكانت سنه حين تزوجها خمسًا وعشرين -عليه الصلاة والسلام- بينه وبينها خمس عشرة سنة، وتزوج عائشة، وهي بنت تسع، وهو ابن خمسين سنة، بل ابن ثلاثة وخمسين سنة، عليه الصلاة والسلام. فالمقصود: أن اختلاف السن بين الزوج والزوجة لا حرج فيه، سواء كان يكبرها، أو تكبره، لا حرج في ذلك، وإنما المهم أن تكون من ذوات الدين، فإذا كانت من ذوات الدين؛ فعليك بها، وإن كانت أكبر منك، وهي كذلك لا بأس أن تتزوج من هو أكبر منها، وأسن منها، لا حرج في ذلك إذا كان صالحًا لها، لدينه وخلقه، ولو كانت بنت أربعين، وهو ابن ستين، أو كانت بنت عشرين، وهو ابن ثلاثين، أو بنت خمسة عشر، وهو ابن عشرين، أو ابن خمس وعشرين، كل هذا لا حرج فيه، سواء كانت تكبره، أو يكبرها، لا حرج في هذا عند جميع أهل العلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15629/حكم-زواج-الرجل-من-امراة-اكبر-منه-او-العكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82422.mp3","categories":["شروط وأركان الزواج"]},{"id":16888,"question":"سؤاله الأخير يقول: هل يجوز الزواج من بنت عم والدتي وما الحكم في ذلك؟الشيخ: هل يجوز؟المقدم: الزواج من بنت عم والدتي؟","title":"حكم زواج الرجل من ابنة عم والدته","answer":"الجواب: لا بأس بذلك، ولكن بنت عمه أقرب، لا بأس بنكاح بنت العم، بنت عمه، وبنت عم أبيه، وبنت عم أمه، لا حرج إذا لم يكن بينهما رضاع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15646/حكم-زواج-الرجل-من-ابنة-عم-والدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76504.mp3","categories":["شروط وأركان الزواج"]},{"id":16919,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين وقع في نهايتها بقوله: أخوكم في الله (م. ن. ع) يسأل ويقول: لي بنت عم رضعت معي رضعة واحدة، أريد الزواج بها، فهل يجوز ذلك؟","title":"حكم زواج الرجل ممن رضعت معه رضعة واحدة","answer":"الجواب: نعم، إذا كانت لم ترضع إلا رضعة واحدة من أمك، أو أنت رضعت واحدة من أمها، فالرضعة لا تحرم، ولك أن تزوجها، لقول النبي ﷺ: لا تحرم الرضعة، ولا الرضعتان خرجه مسلم في صحيحه، ولقوله ﷺ لزوجة... أبي حذيفة: أرضعي سالمًا زوجة أبي حذيفة يقول ﷺ لزوجة أبي حذيفة بن عتبة: أرضعي سالمًا خمس رضعات؛ تحرمي عليه خمس، ولما ثبت عن عائشة -رضي الله عنها- قالت: \"كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات، فتوفي النبي ﷺ والأمر على ذلك\" خرجه مسلم في صحيحه، والترمذي، وهذا لفظ الترمذي، ولفظ مسلم -رحمه الله-: \"فتوفي النبي ﷺ وهي فيما يقرأ من القرآن\". فالمقصود: أن التحريم مضبوط بخمس، معلق بخمس رضعات، فإذا كانت الرضعات أقل من خمس؛ فإنها لا تحرم، الرضعة: كونه يمص الثدي، ويبتلع اللبن، ويطلق الثدي، ثم يعود إليه في المجلس، أو في مجالس أخرى خمس مرات، هذه الرضعة، أما إن كان أمسك الثدي، لكن لا يجزم أنه حصل لبن، أو ما حصل لبن، ما يعتبر، أو يشك هل كمل خمسًا، أو ما كمل خمسًا؛ لا يعتبر، لابد من خمس معلومات يقين، كل رضعة فيها لبن يصل إلى جوفه في الحولين قبل أن يفطم. فإذا كانت أقل من خمس، أو بعد الحولين؛ فإنها لا تعتبر، ولا يكون رضاعه معتبرًا، أو شك فيه، هل بلغ خمسًا، أو ما بلغ، أو ... هل وصل اللبن إلى جوفه، أم لا؟ أو كانت المرضعة ما فيها لبن، إنما تشغله فقط لئلا يصيح، تشغله بالثدي، وإلا ما فيها لبن، أو لبن ما يعتبر ماء، ما له قيمة، ما يسمى لبنًا، ما دام يتسرب منها ماء، فهذا لا يسمى لبنًا، فلا بد أن يكون لبنًا ينفع الطفل، ولا بد أن يكون خمس مرات، أو أكثر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15677/حكم-زواج-الرجل-ممن-رضعت-معه-رضعة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82601.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":17062,"question":"يقول: ابنة عمي طلقتها من عام ستة وثمانين، وحتى اليوم هذا لم تتزوج، وكلما تقدم إليها أحد رفضت وتقول: ولد عمي موجود، وبعد رجوعي إلى السودان، تقدمت لاسترجاعها فرفضت، وقلت لها: سوف أعترض على أي شخصٍ يتقدم للزواج منك، علمًا بأن عمي والأسرة كلهم موافقون؛ لأنني مطلقها طلقة واحدة، أرجو إفادتي جزاكم الله خيرًا.","title":"هل يجوز إجبار المطلقة رجعيًا على الرجوع بعد العدة؟","answer":"الجواب:  ليس لك أن تجبرها، وليس لك أن تعترض، ليس لك أن تعترض على من يخطبها، حرام عليك، طلقتها، واعتدت، وانتهت من سنوات طويلة، فإن رغبت فيك فالحمد لله ما دام طلقة واحدة، أو طلقتين تزوجها بعقد جديد، وأما إذا أبت فلا... مضى سنوات طويلة، أما لو راجعتها في العدة فلك المراجعة، لكن ما دام تركتها حتى اعتدت، ومضت هذه السنون الكثيرة ثم تريد الآن تخطبها، لا بد من رضاها حتى ولو رضي أهلها، الحق لها هي، فإن رضيت وإلا فليس لأحد أن يجبرها، لا أب، ولا غيره، الرسول  يقول: الأيم أحق بنفسها من وليها، والبكر تستأذن وإذنها صماتها، ويقول -عليه الصلاة والسلام-: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن قالوا: يا رسول الله !كيف إذنها؟ قال: أن تسكت. فلا بد من إذن من الأيم، ومن البكر، الأيم التي قد تزوجت مثل هذه التي سألت عنها، لا بد من إذنها، وموافقتها، وليس لأحد جبرها، لا أب، ولا غيره بنص الرسول ﷺ، فاتق الله، واحذر طاعة الشيطان، ولا تظلمها، وهكذا أهلها عليهم أن يحذروا ظلمها، فجعل ........... نفسها، إن تزوجت، فالمسألة لها، والمصلحة لها، وإن أبت فالمضرة عليها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15854/هل-يجوز-اجبار-المطلقة-رجعيا-على-الرجوع-بعد-العدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_721/nour_72108.mp3","categories":["شروط وأركان الزواج"]},{"id":17167,"question":"يقول: جرت العادة في بعض البلدان أن يكتب عقد الزواج الأول بواسطة ما يعرف بالمأذون، بحيث يوضع يد الوكيل عن البنت، ويد الخاطب، ويتم القبول والإيجاب، وبحضور جمع من المسلمين، هل يكفي ذلك، أم لا بد من الانتظار حتى ليلة الزواج؟ جزاكم الله خيرًا.","title":"متى يكتب عقد النكاح؟ وحكم المصافحة عند العقد","answer":"الجواب: العقد في أي وقت جائز، ولو قبل الزواج بمدة، ولو قبل الدخول بمدة، ولا حاجة إلى وضع الأيدي، وليس هذا بمشروع، إنما المشروع أن يقول: زوجتك، يقوله الولي يخاطب الزوج: زوجتك ابنتي، أو أختي، أو بنت عمي موليته التي هو وليها، والزوج يقول: قبلت، قبلت هذا الزواج، هذا هو المشروع بحضرة شاهدين عدلين، يكفي، ...... عند المأذون، أو عند غير المأذون، عند المأذون، أو عند القاضي، أو في أي مكان. يقول له الولي: زوجتك ابنتي، أو أختي، أو موليتي الأخرى بنت عمه، أو نحو ذلك، والزوج يقول: قبلت هذا الزواج، ورضيته، هذا السنة بحضرة شاهدين، إذا كانت المرأة سليمة من الموانع، والزوج سليم من الموانع، يعني: خاليين من الموانع، الزوجة بكر، أو معتدة قد خرجت من العدة، والزوج ليس به مانع، مسلم وهي مسلمة، أو مسلم وهي كتابية، لا بأس. المقصود: لا بد أن يكونا خاليين من الموانع، ليس بالزوج مانع، ولا بالزوجة مانع، ويكون بالإيجاب، والقبول، وحضرة شاهدين عدلين عند المأذون، أو عند القاضي، أو في بيت الولي، أو في بيت الزوج، والحمد لله. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15986/متى-يكتب-عقد-النكاح-وحكم-المصافحة-عند-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72216.mp3","categories":["شروط وأركان الزواج"]},{"id":17267,"question":"هذا السائل سوداني يقول في هذا السؤال، ومقيم في الرياض: سماحة الشيخ ما صيغة عقد الزواج؟ وما هي شروطه؟ وما هي الآيات التي تقرأ مأجورين؟","title":"صيغة عقد الزواج وشروطه","answer":"الجواب: الزواج له شروط، وله أركان، فلابد من توافرها، وخطبة النكاح معروفة: إن الحمد لله.. مذكورة في كتب الحديث، في كتاب النكاح إن الحمد لله، نحمده، ونستعينه عند العقد يقولها أفضل، وإن قال: زوجته قال: قبلت، ولم يأت بخطبة، ولا غيره، فلا بأس إذا كان توافرت الشروط إذا كان الزوجان خاليين من الموانع، وبرضا الزوجين، وحضور شاهدين، وصدر من الولي بولي المرأة الذي هو أقرب عصبتها فلا بأس إذا توافرت الشروط، من قرأ الخطبة إن الحمد لله.. المعروفة فلا بأس، فهو أفضل، وإن لم يقرأها فلا حرج. الرسول ﷺ زوج مرأة بغير خطبة التي أهدت نفسها إليه، ووهبت نفسها له، قال للخاطب: زوجتكها بما معك من القرآن، ولم يذكر عنه أنه خطب الخطبة المعروفة. فالمقصود: إن قرأها الإنسان فهو أفضل: إن الحمد لله.. إلى آخره، وإلا زوجها بدون خطبة، قال: زوجته، قال الزوج: قبلت بحضرة شاهدين، وصدر من الولي الشرعي؛ فلا بأس، الحمد لله، إذا توافرت الشروط. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16108/صيغة-عقد-الزواج-وشروطه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59217.mp3","categories":["شروط وأركان الزواج"]},{"id":17470,"question":"يقول: أردت أن أتزوج بفتاة، لكن تلك الفتاة مشغولة موظفة بإدارة، ورغم ذلك لم تحتجب، ما حكم الشرع في الزواج بها، هل هو ممكن، أم لا؟ جزاكم الله خيرًا.","title":"حكم الزواج بامرأة تعمل مع الرجال ولا تتحجب","answer":"الجواب: إذا كانت مسلمة طيبة توحد الله، تعبد الله وحده، لا تعبد أصحاب القبور، وكانت تصلي، فإنها يجوز الزواج بها، وتعلم الحجاب، يقال لها: تحجبي؛ لأنه لا يجوز للمرأة أن تكشف للأجانب؛ لأن الله يقول سبحانه في كتابه العظيم: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ البعول: الأزواج إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ .. [النور:31] الآية من سورة النور، ويقول سبحانه في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. فتعلم أنه يجب عليها الحجاب، ولا توظف مع الرجال، توظف في عمل النساء، لا توظف في عمل الرجال؛ لأن عملها مع الرجال فتنة، من أسباب الشر، ووقوع الفواحش، لكن تكون في عمل النساء ممرضة.. طبيبة للنساء، مديرة لمدرسة النساء.. عميدة لا بأس، مع النساء خاصة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16354/حكم-الزواج-بامراة-تعمل-مع-الرجال-ولا-تتحجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72507.mp3","categories":["النظر والخلوة والاختلاط","شروط وأركان الزواج"]},{"id":17496,"question":"هذا السائل من سوريا يقول في هذا  هل يجوز للبنت بعد أن عقد عليها أن توكل غير وليها بإتمام العقد ليلة الزفاف؛ لأن البنت عندنا بعد أن يأخذ الأب المهر ويتم التراضي على هذا الزواج وفي ليلة الزفاف يحضر الشهود وتقوم البنت بتوكيل شخص غير وليها لإتمام صيغة العقد، ومثال ذلك: يأتي بالعريس وبالوكيل من غير الولي، ثم يقول وكيل البنت: زوجتك موكلتي فلانة بنت فلانة بمهر قدره كذا على سنة الله ورسوله، ثم يقول العريس: قبلت نكاح موكلتك فلانة على سنة الله ورسوله، فما هو قولكم في ذلك؟","title":"حكم توكيل غير الولي في عقد الزواج","answer":"الشيخ: هذا لا يجوز، ليس لها أن توكل، إنما الولي هو الذي يتولى ذلك، ولكن تستأذن، فإذا أذنت زوجها وليها لقوله ﷺ: لا نكاح إلا بولي، ويقول ﷺ: البكر تستأذن وإذنها سكوتها والأيم تستأمر، فالأيم: وهي التي قد تزوجت؛ تستأمر وتأذن نطقًا، والبكر يكفي سكوتها، ولكن لا يزوج كلًا منهما إلا الولي؛ الأب، ثم الجد، ثم الابن، ثم ابن الابن وإن نزل، ثم الأقارب حسب الميراث كالأخ الشقيق، ثم الأخ لأب، ثم ابن الأخ الشقيق، ثم ابن الأخ لأب ... وهكذا. وليس للمرأة أن تزوج نفسها، ولا أن توكل من يزوجها، بل الواجب أن يتولى هذا الولي سواء في ليلة الزفاف أو قبل ذلك؛ لا بد أن يتولى النكاح الولي فيقول: زوجتك، ويقول الزوج: قبلت، بحضرة شاهدين بعد رضاء البنت أو الأخت لا بد أن تكون راضية، نطقًا إن كانت ثيبًا أو بالسكوت إن كانت بكرًا، هذا هو الواجب، وهذا هو المشروع الذي عليه جمهور أهل العلم. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16409/حكم-توكيل-غير-الولي-في-عقد-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_774/nour_77402.mp3","categories":["شروط وأركان الزواج"]},{"id":17520,"question":"حدثونا لو تكرمتم عن الصيغة الصحيحة لعقد النكاح؟","title":"صيغة عقد النكاح","answer":"الجواب: الصواب أنه يفعل بكل صيغة، ما له صيغة معينة، هذا هو الصواب، لكل أهل بلد أو قبيلة عرفهم، لكن المشهور منها: أنكحتك وزوجتك، يقول الولي للزوج: أنكحتك أختي أو بنتي أو زوجتك أو ملكتك، وإن قال: وهبتك أو أعطيتك أو ألفاظ أخرى يعرفون معناها، وقال الزوج: قبلت، صح ذلك، فلو قال للزوج: أعطيتك ابنتي أو وهبتك ابنتي وقصده الزواج، وقال الزوج: قبلت ذلك، صح بحضرة شاهدين، إذا كانت الشروط متوفرة من رضا البنت، وليس فيها مانع لا إحرام وليست زوجة ولا معتدة، إذا كان ليس بها مانع وقبلت فلا بأس بحضرة شاهدين، برضاها وحضرة شاهدين وأن تكون خالية من الموانع، الزوج والمرأة خاليين من الموانع، ليس فيهما موانع. فالحاصل أن الألفاظ لا حرج في تنوعها، وقال بعض أهل العلم: لا بد أن يكون بلفظ: زوجت وأنكحت، ولكن ليس عليه دليل، فالصواب أن النكاح ينعقد بالألفاظ الدالة على معناه كالبيع والهبة والإجارة ونحوها، فإذا قال: ملكتك ابنتي، أو أعطيتك ابنتي، أو وهبتك ابنتي أو أختي أو عمتي قصده التزويج وهم يعرفون ذلك، وقال: قبلت، بحضرة الشاهدين وبكمال الشروط فلا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16450/صيغة-عقد-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83708.mp3","categories":["شروط وأركان الزواج"]},{"id":17623,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (م. م. ن) رسالتها قضية مطولة بعض الشيء، وقضية هامة فيما أرى -سماحة الشيخ- تقول: أنا بنت زوجوني من رجل أكبر من أبي، وهذا الرجل متزوج من قبل ولم ينجب أولادًا، وزوجوني غصبًا عني، وأمضيت مع هذا الرجل تسعة أشهر وكرهت العيش معه، ورجعت إلى أهلي وطلبت الطلاق ورفض، وهو يقول: إن المهر الذي دفعته يتجاوز مائة ألف ريال، ووالدي يقول: إن هذا المهر ثمانون ألف ريال ذهب، والآن أريد الطلاق بأي حال، هناك من يقول: ليس لك هذا، والبعض الآخر يقول: بل هو من حقك، أرجو أن توجهوني جزاكم الله خيرًا.","title":"حكم إكراه المرأة على الزواج بمن لا ترضاه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفهذه المسألة مسألة خصومة والمرجع فيها المحكمة، فعليك أو وليك أن يراجع المحكمة مع الزوج، والحاكم الشرعي ينظر في الأمر ويحكم بينكما بما يراه شرعًا، ونسأل الله للجميع التوفيق. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، هل تتفضلون سماحة الشيخ بتوجيه الناس فيما يخص تقارب السن بين الخاطب والمخطوب؟\nالشيخ: الواجب على الأولياء أن لا يزوجوا مولياتهم إلا بالرضا، هذا هو الواجب، يقول النبي ﷺ: لا تنكح الأيم حتى تستأمر -الأيم: التي قد تزوجت سابقًا- ولا تنكح البكر حتى تستأذن. قالوا: يا رسول الله! كيف إذنها؟ قال: أن تسكت، وفي الحديث الآخر يقول ﷺ: والبكر يستأذنها أبوها، وإذنها سكوتها. فلا يجوز للأب ولا غير الأب أن يزوجوا إلا بالرضا ولو أنها بنته ولو أنها بكر، ليس له على الصحيح من أقوال العلماء أن يزوجها إلا بإذنها، هذا شيء يتعلق بمصلحتها فليس له أن يزوجها إلا بإذنها، يختار لها الكفء الطيب في دينه وأخلاقه وأسرته، يختار لها الطيب ويشير وينصح لها هو وإخوتها ينصحونها وأعمامها الطيب ولكن متى أبت لا تجبر هي أعلم بنفسها، وهكذا بقية الأولياء من باب أولى، إخوانها وأعمامها لا يجبرونها على الزواج، لابد من إذن.\nوأما كونها تمتنع فلا ينبغي لها أن تمتنع إذا جاء الكفء ينبغي لها أن تقبل من أبيها ومن إخوتها وأعمامها، إذا جاء الكفء في دينه وأسرته ينبغي لها أن تقبل والزواج فيه خير كثير ومصالح جمة، وفي الحديث يقول ﷺ: إذا جاءكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض وفساد كبير ويقول ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء وهذا يعم البنات والبنين. فالشباب من الرجال والنساء عليه أن يتزوج إذا استطاع، والرجل يستطيع بالتماس المرأة وتسليم ما يلزم من المهور، والمرأة تستطيع إذا خطبها الكفء أن تجيب، وفي إمكان وليها أيضًا أن يسعى لها، وأن يلتمس لها الكفء، ولو خطب لها لا حرج، لو خطب لها من يراه كفؤًا فلا حرج في ذلك، فقد ثبت أن عمر  لما تأيمت ابنته حفصة من زوجها عرضها على عثمان وقال له: ما عندي رغبة في الزواج في هذا الوقت، وعرضها على الصديق  أبي بكر فسكت الصديق وأخبر عمر بعد ذلك أنه إنما سكت لأنه سمع أن النبي ﷺ يرغب في الزواج منها فتزوجها النبي عليه الصلاة والسلام. فلا بأس أن يخطب الرجل لموليته من بنت أو أخت، يقول لفلان الذي يعرف أنه طيب: ترى عندي بنت، أو .. أخت إذا كان لك رغبة، ولكن لا يزوجها إلا بإذنها، يعرض عليها ويخبرها أن هذا كفؤ وأنه طيب وصفته كذا وصفته كذا، والمشروع لها أن تجيب وأن تحرص على الزواج إذا جاء الكفء الطيب. أما الجبر؛ فلا يجوز جبر البنات وإلزامهن بزوج لا يرضينه لا من أبيهن ولا من إخوانهن ولا من غيرهم من الأولياء، وعليها هي -البنت- أيضًا أن تجتهد في الموافقة على الخاطب الكفء ولا تتعنت ولا تتشدد في الأمور؛ لأنها قد تتشدد في الأمور أو تتعنت فتتعطل، فيتأخر وجود الزوج الكفء، فينبغي البدار بالقبول إذا جاء الكفء، ينبغي البدار منها ومن أوليائها .نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16549/حكم-اكراه-المراة-على-الزواج-بمن-لا-ترضاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_843/nour_84302.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":17729,"question":"سماحة الشيخ هذه سائلة صفية من سوريا - دمشق تقول: السلام عليكم ورحمة الله وبركاته، سؤالي يا سماحة الشيخ: ما حكم إجبار الفتاة على الزواج من رجل لا تريده أبدًا ولا يناسبها، هل هو زواج صحيح؟ أم باطل في الشريعة الإسلامية؟","title":"حكم إجبار الفتاة على الزواج من رجل لا تريده","answer":"الجواب: لا يجوز جبر الفتاة على الزواج، النبي ﷺ قال: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن، قالوا: يا رسول الله إنها تستحي، قال: إذنها سكوتها فليس لأبيها ولا غيره إجبارها، بل الواجب أخذ إذنها: إن كانت بكرًا فبسكوتها، وإن كانت ثيبًا فبإذنها الصريح، أما أن تجبر لا تجبر على من لا تريد لا بكرًا ولا ثيبًا، ليس لأبيها ولا لأوليائها إجبارها؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/16688/حكم-اجبار-الفتاة-على-الزواج-من-رجل-لا-تريده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59535.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":17807,"question":"تقول السائلة يا سماحة الشيخ: هل يجوز العقد للفتاة بدون حضور ولي أمرها وهو على قيد الحياة؟","title":"حكم حضور الولي عقد موليته","answer":"الجواب:  يقول النبي ﷺ: لا نكاح إلا بولي ليس لأحد أن يعقد على امرأة بدون وليها لا صغيرة ولا كبيرة لا نكاح إلا بولي يقول ﷺ: لا تزوج المرأة نفسها، ولا تزوج غيرها ليست محرمًا لنفسها ولا لغيرها، وعليها أن تطلب من وليها أن يزوجها أو يوكل إذا كان له شغل أو بعيد يوكل من يقوم مقامه. ووليها أقرب الناس إليها من العصبة أبوها ثم جدها وإن علا، ثم ابنها وابنه وإن نزلوا، ثم الأخ الشقيق ثم الأخ لأب، ثم ابن الأخ الشقيق ثم ابن الأخ لأب، ثم العم الشقيق ثم العم لأب، ثم ابن العم الشقيق ثم ابن العم لأب.. وهكذا الأقرب فالأقرب، فأقربهم وأقدمهم الأب، ثم الجد وإن علا، ثم بعد هذا إذا فقد الأب والجد يكون الابن القريب، ثم بعده ابن الابن.. وهكذا. وليس لها أن تزوج نفسها، وليس للأبعد أن يزوج مع وجود الأقرب، وإذا كان للأقرب عذر وكل من يقوم مقامه، فإن لم يتيسر بأن كان محل بعيد ولم يقدر عليه زوج الذي يليه، زوج القريب الذي يليه زوج موليته. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16806/حكم-حضور-الولي-عقد-موليته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77820.mp3","categories":["شروط وأركان الزواج"]},{"id":17809,"question":"تقول السائلة يا سماحة الشيخ: هل يجوز العقد للفتاة بدون حضور ولي أمرها وهو على قيد الحياة؟","title":"حكم حضور الولي عقد موليته","answer":"الجواب:  يقول النبي ﷺ: لا نكاح إلا بولي ليس لأحد أن يعقد على امرأة بدون وليها لا صغيرة ولا كبيرة لا نكاح إلا بولي يقول ﷺ: لا تزوج المرأة نفسها، ولا تزوج غيرها ليست محرمًا لنفسها ولا لغيرها، وعليها أن تطلب من وليها أن يزوجها أو يوكل إذا كان له شغل أو بعيد يوكل من يقوم مقامه. ووليها أقرب الناس إليها من العصبة أبوها ثم جدها وإن علا، ثم ابنها وابنه وإن نزلوا، ثم الأخ الشقيق ثم الأخ لأب، ثم ابن الأخ الشقيق ثم ابن الأخ لأب، ثم العم الشقيق ثم العم لأب، ثم ابن العم الشقيق ثم ابن العم لأب.. وهكذا الأقرب فالأقرب، فأقربهم وأقدمهم الأب، ثم الجد وإن علا، ثم بعد هذا إذا فقد الأب والجد يكون الابن القريب، ثم بعده ابن الابن.. وهكذا. وليس لها أن تزوج نفسها، وليس للأبعد أن يزوج مع وجود الأقرب، وإذا كان للأقرب عذر وكل من يقوم مقامه، فإن لم يتيسر بأن كان محل بعيد ولم يقدر عليه زوج الذي يليه، زوج القريب الذي يليه زوج موليته. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16806/حكم-حضور-الولي-عقد-موليته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77820.mp3","categories":["شروط وأركان الزواج"]},{"id":17888,"question":"المستمع: عبد الله عثمان ، بعث برسالة، ملخص ما في هذه الرسالة يسأل سماحتكم عن حكم إجبار البنت على الزواج، ولاسيما من شخصٍ قد يكبرها سنًا، أو قد يكون عليه بعض النقص الخلقي؟ جزاكم الله خيرًا.","title":"حكم إجبار البنت على الزواج","answer":"الجواب: ليس للولي أن يجبر المرأة على التزوج، ولو بأكمل الناس، ليس له إجبارها، بل هي لها الخيار، لقوله ﷺ: لا تنكح الأيم؛ حتى تستأمر، ولا تنكح البكر؛ حتى تستأذن قالوا: يا رسول الله! كيف إذنها؟ قال: أن تسكت، وفي الحديث الآخر يقول ﷺ: والبكر يستأذنها أبوها، وإذنها سكوتها، فليس للأب ولا لغيره أن يجبر البنت على الزواج، إذا بلغت تسعًا فأكثر، بل لابد من إذنها ولو بالسكوت، وأما الأيم التي قد تزوجت، فلابد من إذنها الصريح بالكلام، تقول: نعم، وليس له جبرها أبدًا، ولو كان أباها، ولو كان الزوج من أصلح الناس، لأن هذا يختص بها، من مصلحتها، فلا تجبر. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16907/حكم-اجبار-البنت-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72812.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":18118,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول المرسل (ح. م) أخونا يقول: تشاكل الأب والأم في زواج البنات، الأب يرضى لبناته الرجل الصالح ولو كان كبيرًا في السن.والأم تقول: لا أزوج بناتي إلا شابًا ولو كان يشرب الدخان أو يحلق لحيته، تشاكلوا ووصل الأمر إلى الخلاف، مع من يكون الحق لو تكرمتم شيخ عبد العزيز ؟","title":"تقديم رأي البنت في اختيار الزوج","answer":"الجواب: مع البنت الذي ترضى البنت، يكون مع البنت، إن رضيت الشيخ الكبير مع أبيها فلا بأس، وإن لم ترض تزوج الشاب ولو كان يشرب الدخان، المعصية لا تمنع الزواج ولو كان يشرب الدخان أو حالق لحيته لا تمنع الزواج هذه، لكن إذا تيسر الصالح الطيب السليم الذي لا يشرب الدخان ولا يحلق فهذا أنعم وأكرم، ولكن الجو الآن والمجتمع الآن يقل فيه السليم من كل شيء لكن من لا يصلي لا يزوج ومن يتعاطى الخمور هذا خطر عظيم. أما التدخين وإن كان محرم التدخين لكنه أسهل من شرب الخمر المعروف بشرب الخمر، وإن كان حلق اللحية كانت معصية ظاهرة لكنه أسهل من شرب الخمر، نسأل الله العافية، وإذا تيسر من لا يحلق لحيته ولا يدخن فهذا يقدم على غيره. المقدم: هو أولى. الشيخ: نعم، فينبغي للبنت أن توافق عليه. المقدم: جزاكم الله خيرًا، الإشكال وقع بين الأب والأم شيخ عبد العزيز ، البنات الآن لم يتدخلن حتى الآن. الشيخ: ينبغي أن يراعى أمر البنت يشاورها الأب وتشاورها الأم، فإذا رضيت بأحد الشخصين الذي قاله أبوها هي مع أبيها، أو ما قالته أمها فهي مع أمها تحكم هي؛ لأن الرسول  قال: لا تنكح الأيم حتى تستأمر ولا تنكح البكر حتى تستأذن قالوا: كيف إذنها؟ قال: أن تسكت لكن من لا يصلي لا يزوج؛ لأنه كافر، نسأل الله السلامة، من ترك الصلاة كفر، نسأل الله العافية. كذلك من يعرف بالتساهل بسب الدين أو بالاستهزاء بالدين هؤلاء كفرة لا يزوجون أبدًا ولو رضيت البنت. نعم. المقدم: جزاكم الله خيرًا، شيخ عبد العزيز لعلها مناسبة أن تتفضلوا بنصح الأسر حتى لا يختلفوا في مسائل مثل هذه، ويتركون الجانب المعني جانبًا. الشيخ: لا شك أن نصيحتي للأسر العناية بالبنات، والحرص على تزويجهن بالأكفاء حسب الطاقة والإمكان، فإذا لم يتيسر الأكفاء الكمل زوج بالناقص، ولو كان عنده شيء من التدخين، أو قص اللحية أو حلقها إذا كان يصلي ومستقيم في دينه لولا هذه الخصلة، فهو خير من ترك البنت هكذا خير من تركها بلا زوج. أما من عرف بالكفر كترك الصلاة أو سب الدين أو الاستهزاء بالدين هذا لا يزوج ولو أرادته البنت لا يحل ولا يزوج، فينبغي للوالدين أن يتشاورا وأن لا يتعاكسا، بل ينبغي للوالدين أن يتفقا وأن يتحريا ما فيه مصلحة البنت، وعدم تعطيلها. نعم. المقدم: بارك الله فيكم وجزاكم خيرًا.","link":"https://binbaz.org.sa/fatwas/17170/تقديم-راي-البنت-في-اختيار-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_905/nour_90503.mp3","categories":["شروط وأركان الزواج"]},{"id":18545,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من مستمعة من سلطنة عمان، رمزت إلى اسمها بالحروف (م. س) أختنا تقول: إنني فتاة أبلغ من العمر واحدًا وعشرين عامًا، وأتمنى من الله أن يرفع عني هذا الظلم الذي أعانيه.ومشكلتي هي أن والدي يرفض أن يزوجني بأي أحد يتقدم لي، حتى وإن كان صالحًا وخاليًا من العيوب التي يرد بها الزوج؛ بحجة أنه يريد أن يزوجني لأحد أبناء أخيه، وأنا محرومة من أن أسأل عن رأيي، بل الأمر كله لأبي.ثم تستمر على هذا المنوال سماحة الشيخ، وتنتهي إلى أن تسأل سماحتكم: ما هو توجيهكم لها ولوالدها؟جزاكم الله خيرًا، إذ أنها تطمح في ذرية صالحة -إن شاء الله-.","title":"تزويج البنت بمن لا ترغب فيه","answer":"الجواب: الواجب على والدك أن يزوجك إذا خطب الكفء، وليس له أن يحبسك لابن عم أو غيره، بل يجب على الوالد أن يزوج موليته إذا خطبها كفء الذي يناسبها، وليس له أن يجبرها على إنسان لا ترضاه، لا من الأقارب ولا غيرهم. فالواجب عليه تقوى الله، وأن يخاف الله ويراقبه؛ فهي أمانة، بنته أمانة، وهكذا أخت الإنسان وهكذا بنت أخيه إذا كان وليها أمانة، يجب على ولي المرأة أن يختار لها الكفء وأن يزوجها بالكفء إذا تيسر، وأن لا يحبسها ويظلمها من أجل قريب له، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17647/تزويج-البنت-بمن-لا-ترغب-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73318.mp3","categories":["شروط وأركان الزواج"]},{"id":18621,"question":"سماحة الشيخ، هذا سوداني رمز لاسمه بـ (أ. ب) مقيم بمنطقة عسير محايل، يقول في هذا  هل يجوز للأخوين أن يتزوجا من أختين؟","title":"حكم زواج الأخوين من أختين","answer":"الجواب: نعم، لا بأس أن يتزوج أخوان من أختين، زيد وعمرو خطبا فاطمة وعائشة، ابنتي فلان، لا بأس، كل واحد يأخذ واحدة، الحمد لله، ليس ما بينهما رضاعة، ولا قرابة تمنع، الحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17729/حكم-زواج-الاخوين-من-اختين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78706.mp3","categories":["شروط وأركان الزواج"]},{"id":18624,"question":"إذا تزوج الرجل امرأة، وأنجبت منه أبناء، ثم توفت هذه الزوجة الأولى، هل يجوز له شرعًا أن يتزوج من أختها الصغرى أو الكبرى؛ لكي تعطف على أبناء أختها أو من تحت يديه؟","title":"حكم الزواج بأخت الزوجة بعد وفاتها","answer":"الجواب: نعم، لا حرج، يتزوج أختها إذا ماتت، أو طلقها وبانت منه، خرجت من العدة، لا بأس، يتزوج أختها، أو عمتها، أو خالتها، الحمد لله، المحرم الجمع، أما إذا كانت ماتت، أو طلقت؛ ما له جمع، إذا ماتت أو طلقت، وخرجت من العدة، له أن يأخذ أختها وعمتها وخالتها؛ حتى تعطف على أولاد الأولى، نعم. المقدم: جزاكم الله خيرًا. الشيخ: يعني: ما لم يكن بينهما مانع من الرضاع. المقدم: نعم، أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17731/حكم-الزواج-باخت-الزوجة-بعد-وفاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78707.mp3","categories":["شروط وأركان الزواج"]},{"id":18663,"question":"رسالة مطولة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: المرسلة (ع. ي. ز. هـ) الرسالة مكونة من ثلاث صفحات، أختنا مشكلتها: أن ابن عمها تقدم لخطبتها، والجميع موافقون إلا والدتها لم توافق على ذلك؛ بسبب أحقاد قديمة فيما بين الأسرتين، وترجو من سماحة الشيخ التوجيه لأولياء الأمور في هذا، جزاكم الله خيرًا.","title":"حكم زواج البنت بغير رضا أمها","answer":"الجواب: الواجب على أولياء المرأة، وعلى أمها، وعلى أقاربها الموافقة إذا خطبها الكفء، الكفء في دينه، المستقيم الموافقة على ذلك؛ لما روي عنه -عليه الصلاة والسلام- أنه قال: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد كبير وفي اللفظ الآخر: وفساد عريض ولأن المرأة على خطر إذا جلست بدون زوج، وهي أهل للزواج، ولا سيما في هذا العصر، فإن الخطر أكبر. فالواجب على الأولياء وعلى أم المرأة وعلى جدتها وعلى أخواتها أن يسهلوا في ذلك، وأن يسهلوا الأمر، وأن لا يشددوا إذا كان الخاطب مرضيًا في دينه لا حرج فيه، فإن أبت الأم ولم ترض فلا مانع أن تزوج بغير إذنها إذا وافق الأب وكان الزوج مرضيًا، وعليها أن تستسمح أمها بما تستطيع ولو بعد الزواج. المقدم: ولو بعد الزواج. الشيخ: ولو بعد الزواج؛ لأن الرسول  يقول: إنما الطاعة في المعروف هكذا يقول النبي ﷺ: إنما الطاعة في المعروف ويقول: لا طاعة لمخلوق في معصية الخالق. وترك الزواج مع تيسر الزواج، ومع وجود الخاطب إما معصية، وإما مكروه جدًا، والأقرب أنه معصية؛ لقول النبي ﷺ: يا معشر الشباب، من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج وهذه استطاعت ويسر الله لها الزواج، ورضي والدها -يعني: أباها- فالواجب المبادرة والمسارعة إلى هذا الخير حرصًا على عفة الفرج، وغض البصر، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17770/حكم-زواج-البنت-بغير-رضا-امها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91908.mp3","categories":["شروط وأركان الزواج","بر الوالدين"]},{"id":18840,"question":"بسم الله الرحمن الرحيم.الوالد العزيز الشيخ عبد العزيز بن عبد الله بن باز المحترم، حياكم الله.أرجو الإجابة على سؤالي؛ لأني حائرة في أمري، بارك الله فيكم، وعظم لكم المثوبة.  أجبرني والدي على الزواج من ابن عمي، وكنت مشمئزة ونافرة من ابن عمي، ولا أدري ما هو السبب، وتم الزواج وأنا قلبي نافر، وأحس بضيق شديد وهموم وغموم، ولم يكن لي أي نية موجهة إلى رجل آخر، ولم أجد مخرجًا من هذا الأمر، وقد أنجبت ثلاثة أولاد، وكلهم بكم الألسنة، صم الآذان، وقد قيل لي: إن السبب هو قد حصلت رضاعة ما بيني وبين ابن عمي المذكور، وقد سألت أمي فأفادت: إنه قد حصل بيني وبينه عدة رضعات، وأفادت إنها أخبرت والدي أثناء زفافي على هذا الرجل، بل أثناء خطبتي عليه، فلم يصدقها، بل ظن أنها تريدني لرجل آخر، وأنا في حيرة كيف أعمل الآن، أرجو التوضيح والتفصيل والإرشاد إلى ما فيه الخير؟ السائلة: (ن. ع. أ) من اليمن الشمالي، لواء الحديدة.","title":"حكم من أجبرت على الزواج ثم وجدت بينهما شبهة رضاع","answer":"الجواب: لا ريب أن الواجب على كل رجل أن يتقي الله في بناته، وأن لا يزوج بنته إلا عن رضاها، وأن لا يجبرها بأحد لا ترضاه، هذا هو الواجب على الأولياء، الأب والإخوة والأعمام وغيرهم، الواجب عليهم جميعًا ألا يزوجوا مولياتهم إلا بإذنهن، والأب بالأخص قد يتساهل في هذا؛ لأن بعض أهل العلم يجيز له أن يزوجها بغير اختيارها إذا كانت بكرًا، ولكن هذا القول وإن قال به بعض العلماء، فهو قول ضعيف قول مرجوح، والصواب: أنه ليس له أن يزوج بناته -أبكارًا كن أو ثيبات- إلا بإذنهن، إذا بلغن التسع فأكثر؛ لقول النبي ﷺ: لا تنكح البكر حتى تستأذن، ولا تنكح الأيم حتى تستأمر قالوا: يا رسول الله، البكر تستحي فكيف إذنها؟ قال: إذنها سكوتها وقال -عليه الصلاة والسلام-: البكر يستأذنها أبوها، وإذنها صماتها. فقد صرح النبي ﷺ بأنه ليس للأب ولا غيره أن يزوج المولية إلا بإذن، والأب هو المقدم، ومع ذلك نهي عن التزويج إلا بإذن، فالأولياء الآخرون من باب أولى، لكن إذا كان حين أمرك بالزواج أطعت ووافقت؛ إرضاءً له ومحبة له وتعظيمًا لأمره -وإن كنت كارهة- فلا حرج الزواج صحيح. وما وقع من وجود البنين الثلاثة الصم البكم؛ فهذا أمره إلى الله، قد يكون له أسباب غير ما ذكرت من الرضاع، قد يكون له أسباب أخرى، وأنت ليس عليك من هذا بأس؛ لأنك لم تعلمي الرضاع، وإنما البأس على أبيك الذي علم الرضاع وتساهل، فالإثم عليه، وعليه التوبة إلى الله من ذلك. وإذا كانت الأم قد حفظت خمس رضعات؛ فإنه يكون أخًا لك، وليس لك الزواج عليه والنكاح باطل، ولكن أنت ليس عليك إثم؛ لأنك لم تعلمي، والأولاد أولاكما لاحقون بأبيهم؛ للجهل وعدم العلم ببطلان النكاح. والواجب على أبيك التوبة إلى الله  من ذلك، فإذا كانت أمك ثقة، وشهدت بخمس رضعات أو أكثر، حال كون ابن عمك في الحولين؛ فإن النكاح يكون باطلًا، والإثم ثابت على أبيك، وعلى أمك نصيب من ذلك؛ لأنها لم تعلمك ولم تعتن بالأمر ولم تشدد فيه، فعليها نصيبها من الإثم، ولكن إثم الأب أكبر. أما إن كان الرضاع أقل من ذلك: رضعة أو رضعتين أو ثلاثًا أو أربعًا؛ فالنكاح صحيح؛ لأن التحريم إنما يحصل بخمس رضعات فأكثر، معلومات في الحولين، على أن تكون الشاهدة ثقة بذلك. والرضعة: هي أن يمسك الصبي أو الصبية الثدي ويمتص اللبن ثم يطلق ذلك، هذه يقال لها: رضعة. فإذا كان ابن عمك رضع من أمك خمس رضعات فأكثر، في كل رضعة يمسك الثدي ويمتص اللبن ويذهب إلى جوفه، ثم يعود بعد ذلك ويرضع، حتى يكمل خمسًا في مجلس أو في مجالس، في يوم أو في أيام؛ فإنك أخته، والنكاح باطل. وأسأل الله أن يشفي أبناءك الثلاثة، وأن يعظم أجرك، وأن يعفو عن أبيك عما حصل منه من الخطأ والتقصير، وعن أمك عما حصل منها من التقصير، نسأل الله أن يعفو عن الجميع؛ وأن يعوضك خيرًا من ابن عمك إذا ثبت الرضاع، أو طلقك؛ لأنك تكرهينه. على كل حال: هذه مصيبة، والدنيا هي دار المصائب، ونسأل الله أن يحسن العاقبة للجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17986/حكم-من-اجبرت-على-الزواج-ثم-وجدت-بينهما-شبهة-رضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_878/nour_87805.mp3","categories":["الرضاع","شروط وأركان الزواج"]},{"id":19178,"question":"المستمع: عبد الله صالح المطيري من عقلة الصقور له ثلاثة أسئلة، في سؤاله الأول يقول: ما حكم من يرغم ابنته على الزواج من رجل لا ترضاه؟","title":"حكم إجبار الوالد بنته على الزواج ممن لا تريده","answer":"الجواب: لا يجوز ذلك؛ لأن النبي ﷺ يقول: والبكر يستأذنها أبوها، وإذنها سكوتها. فليس له أن يرغمها على شخص ولو كان تقيًا، ولو كان أتقى الناس ليس له إرغامها، وإنما ينصح لها ويشير عليها بما يراه خيرًا لها، وعليها أن تطيع والدها في الخير والمعروف إذا كان الزوج صالحًا عليها أن تطيعه، وعليها أن تقدر عطفه وحنوه عليها، وإحسانه إليها. لكن لا يلزمها طاعته إذا كان قلبها لا يرضى هذا الزوج ولا يميل إليه، لا بأس عليها أن تعتذر إلى أبيها، ولا يجوز لأبيها أن يرغمها. ولكن متى استطاعت أن تطيع والدها في زوج صالح يناسبها فإنه خير لها وأفضل لها، طاعة الوالد من أفضل الطاعات في طاعة الله جل وعلا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18358/حكم-اجبار-الوالد-بنته-على-الزواج-ممن-لا-تريده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93210.mp3","categories":["شروط وأركان الزواج","قضايا المرأة"]},{"id":19619,"question":"سماحة الشيخ حفظكم الله يقول هذا السائل: عندنا في بعض الحالات يزوج بعض الأولياء، يزوجون البنات والأخوات غصبًا عنهم حتى ولو كانت رافضة لهذا الرجل، وأحيانًا يأخذون المهر، ولا يعطون المرأة شيئًا من هذا المهر، فما توجيه سماحتكم؟","title":"حكم تزويج المرأة غصبًا بمن لا تريد","answer":"الجواب: لا يجوز تزويج المرأة إلا بإذنها، ولا يجوز إجبارها، سواء كانت بكرًا أو ثيبًا يقول النبي ﷺ: لا تنكح البكر حتى تستأذن، ولا تنكح الثيب حتى تستأمر، ويقول ﷺ: الثيب أحق بنفسها من وليها، واليتيمة تستأمر، وإذنها سكوتها . فليس لأبيها ولا غيره أن يجبرها، لا بد من إذن هذا هو الصواب، ولا يحل لأب، ولا أخ، ولا عم، ولا غيرهم أن يجبر البنت، بل يجب استئذانها؛ لقوله ﷺ: والبكر يستأذنها أبوها، وإذنها سكوتها، وفي اللفظ الآخر: واليتيمة تستأمر، وإذنها سكوتها، نسأل الله العافية. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/18885/حكم-تزويج-المراة-غصبا-بمن-لا-تريد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94817.mp3","categories":["شروط وأركان الزواج"]}]
